/* GENERATED by scripts/build_ai_knowledge.py from docs/ai_knowledge/*.md + tutorials/*.md — do not edit by hand. (SPB-AI 2026-09-30) */
(function () {
    'use strict';
    var CHUNKS = [{"t":"How Shokker Paint Booth Pro works > The big idea: paint file in, zones decide the look","k":"card","b":"The buyer opens their car's paint file (a flat, unwrapped 2048x2048 picture of the whole car: left side, right side, hood, roof, front, rear laid out as separate islands). Shokker turns it into a finished iRacing paint + a \"spec map\" that controls how shiny/metallic/rough every pixel is. The look is decided by ZONES. The paint canvas is flat, so \"left/right/top/bottom\" mean the flat picture, not the car. The grid A-H (columns, left to right) by 1-8 (rows, top to bottom) is how the copilot talks about places."},{"t":"How Shokker Paint Booth Pro works > What a zone is","k":"card","b":"A zone = (which pixels it covers) + (a look for them). The look = a base material (gloss, matte, satin, chrome, candy, pearl, metallic, ...) OR a monolithic special finish (a complete exotic look), a colour mode (keep the paint's own colour / solid colour / gradient / the finish's own colour), optional pattern on top, optional spec patterns (change the shine/metal/roughness texture), an optional second base blended over the first, intensity, and spec-channel shifts."},{"t":"How Shokker Paint Booth Pro works > Which pixels a zone covers (the REGION)","k":"card","b":"- By paint colour: one or several picked colours with a tolerance (6-100; 30-50 is normal). Every pixel on the paint close to that colour belongs to the zone. Anti-aliased edges need a bit of tolerance.\n- By PSD layer: restrict the zone to pixels that exist on chosen layers (Numbers, Sponsors, Car Paint, ...). Colour + layer together = \"that colour, but only on that layer\".\n- By a box: limit the zone to a rectangle of the canvas (cells like B3:D5). Colour + box = \"that colour, only inside the box\".\n- Catch-alls: \"Remaining\" = everything no zone above it claimed (the classic body zone, always at the bottom). \"Everything\" = every pixel (combine with a layer or box to make it precise)."},{"t":"How Shokker Paint Booth Pro works > PRIORITY: the top zone wins","k":"card","b":"Zones are a stack. Position 1 (the TOP of the list) has the highest priority: where two zones select the same pixel, the higher one gets it, the lower one gets nothing there. So a new zone that must show on pixels another zone already selects has to be placed ABOVE it (the copilot places new zones at the top by default). A \"Remaining\" zone belongs at the bottom. If a zone \"does nothing\", the usual reasons are: a zone above already claims those pixels; its colour tolerance is too tight; it is bound to the wrong layer; it is muted; intensity is 0."},{"t":"How Shokker Paint Booth Pro works > Colour modes (what colour the finish paints)","k":"card","b":"- source: keep the car's own paint colour, only change the shine/spec (great for gloss/matte/satin/pearl/candy over an existing livery colour).\n- solid #rrggbb: paint the whole zone that colour.\n- gradient: 2-10 colour stops blended across the whole canvas in a direction (horizontal left-to-right, vertical top-to-bottom, diagonal_down, diagonal_up, radial from the centre, angular around the centre). The gradient runs over the entire 2048x2048 canvas, so a horizontal gradient changes colour with the canvas column, not along the car's length. Because the car is unwrapped, several islands share the same columns; to fade each side of the car separately, use one zone per side (region box) with its own gradient.\n- finish: the finish brings its own colour (chrome, carbon, holographic, ...)."},{"t":"How Shokker Paint Booth Pro works > Strengths and adjustments","k":"card","b":"- intensity 0-100: overall strength of the whole zone.\n- base_strength 0-200%: how much of the finish replaces the original paint (100 = full; lower = show more of the original paint).\n- spec_strength 0-200%: overall strength of the shine/metal map.\n- hue -180..180, saturation -100..100, brightness -100..200: tweak the base colour.\n- scale / rotation: size and angle of the finish's own texture.\n- spec_shift metal / rough / clearcoat (-127..127): push those channels up or down for the whole zone (more metal, rougher, less clearcoat...)."},{"t":"How Shokker Paint Booth Pro works > The unwrapped-paint reality","k":"card","b":"Text and numbers on the paint are often mirrored/rotated on other islands. Sponsor logos, numbers and stripes are usually separate PSD layers: prefer selecting them by layer name (exact, no colour bleed) over colour matching. Colour matching is best for big flat colours (body, stripes). When a colour is used both on the body and on a logo, add a layer restriction or a box."},{"t":"Spec map, finishes and looks > The spec map in iRacing (what \"spec\" means)","k":"card","b":"iRacing reads a second image, the spec map, beside the paint. Its channels: RED = metallic (0 = plastic/paint, 255 = bare metal/chrome), GREEN = roughness (0 = perfect mirror, 255 = fully matte), BLUE = clearcoat (inverted: 16 = maximum glossy clearcoat, 255 = no clearcoat/dull). Gloss paint is roughly M0 R20 CC16; matte M0 R215 CC215; chrome M255 R2 CC0; metallic paint M200 R50 CC16. When a buyer says \"the spec finish\" or \"how it reflects\" they mean this map: reflective/mirror = low roughness + high metal; matte = high roughness; flake/sparkle = tiny bright specks in the metal channel; holographic = rainbow-shifting specks or bands."},{"t":"Spec map, finishes and looks > Four kinds of \"finish\" in Shokker","k":"card","b":"- BASE: a plain material for a zone (gloss, matte, satin, chrome, candy, pearl, metallic, carbon, brushed metal ...). key looks like base::chrome. The colour comes from the zone's colour mode.\n- MONOLITHIC: a complete special look that brings its own colour and texture together (exotic, animated-looking, themed). key looks like monolithic::name. Use one when the buyer describes a whole special effect (\"holographic\", \"galaxy\", \"hologram\").\n- PATTERN: a paint-colour pattern layered on top of the base (carbon weave, camo, stripes, flames ...). Changes what you SEE.\n- SPEC PATTERN: a texture that changes the spec map only (flake, sparkle, micro-metal, holographic prism, engine-turn, weave ...). Changes how the surface REFLECTS, not the colour. Up to 5 stack on a zone, each with opacity, scale, rotation and channels (M = metallic, R = roughness, C = clearcoat).\nA zone may also have a SECOND BASE blended over the first (for example gloss body + a pearl overlay at 40%)."},{"t":"Spec map, finishes and looks > How to choose (design sense)","k":"card","b":"- Big body areas: candy, pearl, metallic, satin or gloss in the livery colour read premium; chrome on a large area is loud and shows every flaw, so use it for accents, numbers, trim.\n- Adjacent areas must contrast in colour or in shine (matte next to gloss, chrome next to dark). Keep numbers/sponsors readable: high-contrast colour and a clean finish.\n- A limited palette (2-3 colours + one accent) looks expensive.\n- \"Flake\" = a spec pattern from the Sparkle & Micro-Metal group (holographic_flake, gold_flake, ...) on top of a metallic-capable base (metallic, chrome, candy, pearl).\n- \"Holographic / rainbow / iridescent / prismatic\" = a holographic spec pattern (holo_prism_shift, spec_holographic_oil_circuit) and/or a holographic monolithic finish; pair with a bright reflective base.\n- \"Reflective / mirror / wet\" = chrome or a very low-roughness base plus high clearcoat.\n- \"Worn / weathered / dirty\" = roughness up, clearcoat down, weathering spec patterns."},{"t":"Spec map, finishes and looks > Adjusting a look","k":"card","b":"Too shiny: raise roughness with spec_shift rough +40, or lower spec_strength. Too flat: lower roughness, raise clearcoat, add a flake spec pattern. Colour too strong over the livery: lower base_strength. Texture too big/small: scale."},{"t":"Worked recipes: what buyers ask -> what to do > Recipe: \"a gradient from blue to gold to white\"","k":"card","b":"The gradient goes on the zone that owns the big body area. edit_zone {zone: <body zone>, finish: <a coating base like gloss/pearl/candy>, gradient: {stops: [{pos:0,color:\"#0a3fd6\"},{pos:50,color:\"#d4a017\"},{pos:100,color:\"#ffffff\"}], direction: \"horizontal\"}}. Pick the direction that matches the flat layout: horizontal = left to right across the canvas, vertical = top to bottom, diagonal_down/diagonal_up, radial from the centre. Choose true colours (gold = #d4a017 or #e0a800; white = #ffffff; deep blue = #0a3fd6). If the body zone only covers some colours of the paint, the gradient shows only there."},{"t":"Worked recipes: what buyers ask -> what to do > Recipe: \"reflective holographic finish\"","k":"card","b":"On the same zone add spec patterns: edit_zone {zone, spec_patterns: [{id:\"holo_prism_shift\", opacity:80}]} (check with search_spec_patterns \"holographic\"), and make the base reflective (pearl, metallic or chrome). Optionally add a holographic monolithic finish if the buyer wants the whole special effect instead of a gradient body (a monolithic brings its own colour, so it replaces the gradient colour: prefer base + spec pattern when the buyer asked for a specific colour gradient)."},{"t":"Worked recipes: what buyers ask -> what to do > Recipe: \"accents on the rear of each side, the same blue as the front accents, in a chrome flake look\"","k":"card","b":"1. Find the front accents' colour: the paint colours list shows the accent hex and which grid cells it sits in; if unsure ask_vision \"where are the accent stripes on the front and rear of each side?\".\n2. Rear accents = the same paint colour (or the same layer) but limited to the rear cells. add_zone {name:\"Rear accents\", region:{colors:[\"#accent hex\"], cells:\"<rear cells, e.g. A7:D8>\"}, finish:\"base::chrome\" (or a metallic base), color: <the blue hex of the front accents or \"source\">, spec_patterns:[{id:\"holographic_flake\" or another chrome/metal flake id from search_spec_patterns \"flake\", opacity:70}]}.\n3. If the rear accents share a colour with the front ones, the front zone above may already claim them (the footprint shows blocked_by): the new zone sits at the top, so it wins its box.\n\"Same blue as the front\" means read the actual front accent colour from the paint colours or from the zone that covers it; do not guess a blue."},{"t":"Worked recipes: what buyers ask -> what to do > Recipe: \"make the numbers/sponsors/stripes chrome (or any finish)\"","k":"card","b":"Use the PSD layer if one exists by that name: edit_zone or add_zone with region:{layers:[\"Numbers\"], everything:true} and finish. Otherwise select by the number colour with tolerance 30-45."},{"t":"Worked recipes: what buyers ask -> what to do > Recipe: \"matte body with gloss accents / two-tone\"","k":"card","b":"Body zone (remaining or its paint colour): finish base::matte or satin, color \"source\". Accent zone above it: finish base::gloss (or candy/chrome) on the accent colour."},{"t":"Worked recipes: what buyers ask -> what to do > Recipe: \"make it pop\"","k":"card","b":"Find the biggest flat area and the strongest contrast pair. Push one to a deep glossy candy/pearl of its own colour, keep the other matte/satin or chrome accent; add a subtle flake spec pattern (opacity 30-50) on the body for depth. Explain what you did in one sentence."},{"t":"Worked recipes: what buyers ask -> what to do > Recipe: \"why does it look flat / wrong / nothing changed?\"","k":"card","b":"Look at the zone in STATE (get_state): if visible_pct is much lower than share_pct, higher zones block it (say which, offer to move it up). If share is 0 the colour/tolerance/layer selects nothing (offer the fix). If intensity/base_strength is low, raise it. Answer in plain words and offer to fix."},{"t":"Worked recipes: what buyers ask -> what to do > Recipe: \"undo / go back\"","k":"card","b":"Every AI change is one undo step in Pro (Ctrl+Z, or the Undo button under the reply). You cannot delete zones yourself: mute them (muted:true) and tell the buyer they can delete it in the zone list."},{"t":"Worked recipes: what buyers ask -> what to do > Recipe: \"change the car / the body / the whole car\" (keep the numbers and sponsors)","k":"card","b":"If the paint has a layer named like \"Car Paint\" or \"Body\", put the change on that layer only: edit the catch-all zone (or add a zone) with region {layers:[\"Car Paint\"]}. Numbers, sponsors, tape and logos sit on other layers, so they stay exactly as they are; tell the buyer (\"I kept your numbers and sponsors\"). If the buyer names the decals or says \"everything\", include them. A whole-car finish that brings its own colour (chameleon, candy, holographic) on the catch-all WITHOUT a layer restriction paints over every number and logo."},{"t":"Worked recipes: what buyers ask -> what to do > Recipe: \"start over / reset\"","k":"card","b":"Zones cannot be deleted by the copilot. Mute every zone except the catch-all, then set the catch-all to plain gloss with colour \"source\" (keeps the car's own paint). Never mute all zones: Pro cannot render with none (\"No zones provided\")."},{"t":"What the copilot can and cannot do, and where things are in the app > The copilot CAN (Pro mode)","k":"card","b":"Read every zone; change any zone's region (paint colours, layers, a named part of the car (hood, roof, left / right side, trunk, bumpers, spoiler: known from the built-in car library or shown once by the buyer) with a portion or a band, catch-all), finish (it knows the whole ~4,800-look catalogue with measured colour, shine, metal and texture), colour/gradient, pattern, spec patterns, second base, strengths, hue/sat/brightness, spec channel shifts, name, mute, priority; add and duplicate zones; change PSD layer visibility / opacity / blend; look at the paint and at the live preview and spec map; offer several complete designs with live thumbnails to pick from; remember the buyer's taste and facts about the car; answer how-to questions; undo its own work as one step."},{"t":"What the copilot can and cannot do, and where things are in the app > The copilot CANNOT (say so plainly, then give the manual steps)","k":"card","b":"- Delete zones, open or save files, import a paint/PSD, export or deploy to iRacing, change the car folder or user id, render the final full-resolution paint. It can tell the buyer exactly where to click.\n- Draw or paint by hand (brush, lasso, layer pixels), add text/logos, move or edit layer artwork. (Tools in the toolbar do those.)\n- See the buyer's screen beyond the paint canvas and the live preview it can capture.\n- Guarantee how iRacing lights the car on track; it can only set spec values."},{"t":"What the copilot can and cannot do, and where things are in the app > Where things are (Pro layout)","k":"card","b":"- Left column: ZONES list (top = highest priority), + Add Zone, Reset All Zones. Each zone card: what pixels it covers (colour picker/eyedropper \"PICK COLOR FROM CAR\", tolerance, \"Restrict to layers\", box), APPLY AREA, BASE (base material picker, colour mode incl. gradient), patterns, spec patterns, second base, intensity.\n- Centre: RENDER button (full-quality render), SOURCE (the paint) and LIVE PREVIEW (updates as zones change; \"Refresh\" if it says stale), channel previews (COMBINED, R METAL, G ROUGH, B COAT).\n- Right column: LAYERS (PSD layers), Open Layered, + Layer, Actions.\n- Top: tool row (Move, Pick, Color, Wand, Lasso, Rect, Brush, Fill, Erase) and menus (History, Select, Retouch, Mask, Transform, Adjust); ZONE/LAYER target switch; Render History; Save / Open (SHOKK files); Import Recipe; SPEC SCULPT; Shokk Drop; Settings.\n- Export: after RENDER, the finished paint and spec files go to the iRacing car folder set at the top (iRacing Car Folder + iRacing User ID); \"Auto-deploy after render\" can send them automatically. In iRacing, use the paint in the car's paint shop as a custom paint."},{"t":"What the copilot can and cannot do, and where things are in the app > Talking style","k":"card","b":"Plain words, no ids or jargon, 1-4 short sentences. Say what you changed and what you assumed. If unsure what the buyer means, ask ONE short question with 2-4 options. Never answer \"nothing to change\" without saying why."},{"t":"What the copilot can and cannot do, and where things are in the app > Works without an AI key","k":"card","b":"The built-in design library lays out whole schemes from a short description with no AI and no key: \"retro red white and blue stripes\", \"black and gold two-tone\", \"Gulf style\", \"stealth with a red accent\", and spec looks (\"make the hood mirror chrome in the spec only\"). With an OpenRouter key the copilot adds custom ideas, any finish from the catalogue, spec textures and corrections."},{"t":"What the copilot can and cannot do, and where things are in the app > Three ways to talk to Shokker (all optional)","k":"card","b":"1. **No key (free):** the built-in design library: describe a scheme or a part colour or a spec look, then refine it (\"thinner\", \"make the red orange\", \"matte\", \"another take\", \"undo\").\n2. **Your OpenRouter key:** the full copilot (about a third of a cent per answer): custom ideas, any finish, spec textures, corrections, checks of its own work.\n3. **Your own Claude plan (Claude Desktop or Claude Code):** open the AI panel, press the gear, switch on \"Let an AI assistant (Claude or ChatGPT/Codex) control Shokker Paint Booth\" and press \"Install in Claude Desktop\"; then ask Claude \"Using Shokker Paint Booth, give me a Gulf-style livery\". No API key or extra cost; Claude uses the same car knowledge and every change shows in the panel with Undo. Claude can see the preview picture and checks its own work.\nCar parts: Shokker recognises many iRacing templates by itself; for a car it does not know it asks once (drag a box around each part) and remembers. The gear drawer can copy, save or load a car map."},{"t":"What the copilot can and cannot do, and where things are in the app > ChatGPT / Codex subscription connection","k":"card","b":"**Your ChatGPT plan (Codex):** in the bridge settings open Connect ChatGPT / Codex, review the connection, then Add SPB to Codex settings. Restart Codex, sign in with ChatGPT and choose a model using its model picker or /model. Chat in Codex with SPB open. Your subscription limits apply. Use Take over in SPB before asking the in-app copilot to edit while an external assistant has control."},{"t":"Design taste for race-car paint > What makes a finish POP (owner's proven winners)","k":"card","b":"Saturation alone does not pop. What works: (1) COMPLEMENTARY neighbour contrast: a colour next to its opposite or a clearly different value (deep blue beside warm gold, black beside hot pink, white beside red); (2) a spec that is the colour-OPPOSITE of the paint: warm paint on a MATTE surface next to cool colour on METAL (and the reverse) reads far richer than one shine everywhere; (3) one hero area (a big panel or the hood) that is loud, with calm neighbours; (4) fine texture (micro flake, weave) for depth instead of big blobby patterns. A look that is mud at thumbnail size (many mid-tones) will be mud on the car."},{"t":"Design taste for race-car paint > Readability first (iRacing is seen at speed and at distance)","k":"card","b":"Numbers and sponsor logos must contrast strongly with what is behind them (light on dark or dark on light) and should not sit on busy texture. Do not put sparkle, strong patterns or chameleon shifts directly behind numbers. Keep a limited palette: 2-3 colours plus one accent looks expensive; 5 colours looks cheap. Stripes and accents guide the eye along the body; large single-colour areas should have a subtle finish variation so they do not look flat."},{"t":"Design taste for race-car paint > Palettes that work (hex starting points)","k":"card","b":"- Premium dark: body near-black #0d0d10 (matte or satin), accent gold #d4a017 (gloss/metal), numbers white.\n- Racing blue and gold: #0a3fd0 body, #d4a017 accent, #ffffff numbers.\n- Stealth: body #1a1c20 matte, accents #3a3d44 satin, numbers #e8e8ea.\n- Hot and cold: #ff5a1f orange with #00b7ff cyan, black separators.\n- Clean white performance: #f2f2f2 gloss body, #c8102e red stripe, black numbers.\n- Retro 70s: cream #efe2c2, orange #e0731f, brown #6b3b1e stripes.\n- Miami neon: #ff2bd6 pink, #00e5ff cyan, black base.\n- Heritage red: #c8102e body, white numbers, silver accents.\nExact colours from the buyer (\"#0033AA and #FF6600\") are used exactly: solid colour mode on a base that takes the zone colour (gloss/satin/matte/candy/pearl/metallic), never a finish that brings its own palette."},{"t":"Design taste for race-car paint > Finish choice by goal","k":"card","b":"- Exact brand colour: a base that TAKES the zone colour (gloss, satin, matte, metallic, pearl, candy).\n- Deep wet colour: candy over a metallic base. Soft shimmer: pearl. Sparkle: metallic or a flake spec pattern.\n- Special effect where the whole look is the point (galaxy, lava, chameleon, carbon, camo, stained glass): a complete special look from the catalogue (find_finishes by theme, then look at finish_details and show_finishes). It brings its own colours.\n- Stealth: matte or satin dark with very low metal. Show car: mirror chrome or high-gloss candy. Old race car: weathered / worn looks, roughness up.\n- Chrome is loud: accents, numbers, trim, not the whole car, unless asked."},{"t":"Design taste for race-car paint > Themes -> where to look in the catalogue","k":"card","b":"Camo: TACTICAL & FIELD, Ghost Camo, Bark Camo. Flames: Flames, FRACTURED FLAMES. Space: FRACTURED COSMOS, Galaxy, Sparkle Galaxy. Japanese: RISING SUN, ANIME INSPIRED. Mexican: VIVA MEXICO. British: UNION JACKED. American patriotic: LET FREEDOM RING. Dragons/scales: FORBIDDEN DRAGON, Iridescent Insects. Retro: Sock Hop, Groovy Vibes, FAR OUT. Neon/cyber: CYBERPUNK, NEON UNDERGROUND, Signal. Luxury/gold: MONEY SHOKK, Electroplated Gold, ASTRA. Worn/rust: Foundation EFX, Weathered Paint, Hardware: Battle Worn. Colour-shift: Prizm, Spectrum Shift, FRACTURED NIGHTSHIFT. Carbon/weave: Carbon Fiber, FRACTURED MINDS. Liquid metal: Mercury, Liquid Metal, Chrome, PARADIGM. Wood/leather/fabric: Foundation EFX, WORLD OF COLOR, FAR OUT."},{"t":"Design taste for race-car paint > Honest limits of a paint file","k":"card","b":"The paint is a flat texture: it cannot glow in the dark, cannot show text or pictures unless they already exist as layers, cannot change the car's shape, windows or wheels beyond what the sheet paints, and iRacing's lighting decides how chrome and flake look on track. Say so plainly and do the closest real thing (for example a phosphorescent-looking finish for \"glow in the dark\")."},{"t":"Layers, car panels and exporting > PSD layers and their roles","k":"card","b":"A layered paint template (PSD) carries: BODY PAINT (Car Paint: the livery colours), NUMBERS, SPONSORS, TAPE / stripes, DECALS / LOGOS (Pitbox Colors, Color Change Logos, Car_decal, Windshield Banner) and TEMPLATE layers (Mask, Wire, Car_Mandatory) in a group called \"Turn Off Before Exporting TGA\". Template layers show the car's UV outlines and mandatory elements for the painter; they must be OFF in the exported paint. A zone can be limited to a layer (region layers) so a finish lands only on that art, and a zone that changes \"the body\" should be limited to the body layer so numbers and sponsors stay as they are.\nLayer controls the copilot can change: visible, opacity (0-100), blend mode (normal = source-over, multiply, screen, overlay, darken, lighten, color-dodge, color-burn, hard-light, soft-light, difference, exclusion, hue, saturation, color, luminosity). It cannot delete, merge, rename, reorder, or paint on layers. Locked layers must be unlocked by the buyer."},{"t":"Layers, car panels and exporting > The car's panels (UV islands)","k":"card","b":"The 2048 x 2048 sheet is the car unwrapped: two long body sides (one may be upside down), hood, roof, trunk or truck bed, front and rear fascia, bumpers, small strips (rockers, splitters, mirrors, spoilers) and wheels. The template Mask layer separates paintable panels (transparent) from dead space (opaque); the Wire layer outlines each panel in green. The copilot finds the panels by geometry but cannot reliably NAME them from the picture, so when a request depends on which panel is the hood, the roof, the left or right side, it shows the car and the buyer taps the panel once; the name (and which end is the front, for sides) is remembered for this car. Then \"the rear half of the left side\" is exact."},{"t":"Layers, car panels and exporting > Exporting to iRacing (the copilot cannot do this; tell the buyer)","k":"card","b":"Switch the template layers (Mask, Wire, Car_Mandatory) OFF, then press **RENDER**. With the **IRACING CAR FOLDER** set (that alone does it; \"Auto-deploy after render\" in Settings only matters when the car folder is empty) the paint TGA (car_num_<ID>.tga for Custom Number, car_<ID>.tga for Sim-Stamped Number) and car_spec_<ID>.tga are copied into the iRacing car folder after every render (iRacing loads car_num_ only with Settings > Graphics > Hide Car Numbers ON; see the Support cards); in iRacing press Alt+Tab, then Ctrl+R to reload the paint. The top of the window holds the IRACING USER ID, the SOURCE PAINT path and the IRACING CAR FOLDER. \"Deploy to a different car\" copies a render into another car's folder. \"Export ZIP Package\" (Settings) bundles paint + spec + preview into a .zip on every render."},{"t":"Layers, car panels and exporting > Undo","k":"card","b":"Every copilot answer is one undo step for the zones it changed, plus one step per layer it changed; the Undo button under the answer takes all of them back. Ctrl+Z also works."},{"t":"Where things are in the app RIGHT NOW (AI knowledge card, generated from the real UI) > Top toolbar menu: History","k":"card","b":"- **Undo Ctrl+Z** \u2014 Undo (Ctrl+Z) \u2014 undo last stroke, transform, or layer action. Also available via right-click \u25b8 Undo.\n- **Redo Ctrl+Y** \u2014 Redo (Ctrl+Y / Ctrl+Shift+Z) \u2014 redo last undone action. Also available via right-click \u25b8 Redo.\n- **Undo History\u2026** \u2014 Undo History \u2014 open recent action list"},{"t":"Where things are in the app RIGHT NOW (AI knowledge card, generated from the real UI) > Top toolbar menu: Select","k":"card","b":"- **\u229e Select All Color** \u2014 Select All Color (A) \u2014 click to sample matching pixels across the full visible source; Shift adds, Alt subtracts\n- **Grab Object** \u2014 Grab Object (G) \u2014 click inside a solid part of a number or logo to include its outline and shadow. Samples visible paint: hide wire/template guide layers if they split the artwork. Shift adds, Alt subtracts.\n- **Smart Region Fill** \u2014 Smart Region Fill \u2014 click inside an edge-bounded region; Tolerance changes boundary sensitivity, Shift adds, Alt subtracts\n- **\u2b0c Move Selection Border** \u2014 Move Selection Border \u2014 Arrow moves 1px, Shift+Arrow moves 10px; drag inside to move freely; pixels do not move\n- **\u2295 Pick Layer Element** \u2014 Pick Item (explicit) \u2014 always force isolation of one sponsor/number/shape inside the layer for its own tight transform box\n- **\u29c9 Zone Pick** \u2014 Zone Pick \u2014 click spec patterns / bases / sub-pieces for independent move, rotation and proportional resize (handles, live numbers, snapping).\n- **\u2b2d Elliptical Marquee** \u2014 Elliptical Marquee (M) \u2014 drag a Zone selection; Shift makes a circle, Alt draws from center, Esc cancels"},{"t":"Where things are in the app RIGHT NOW (AI knowledge card, generated from the real UI) > Top toolbar menu: Retouch","k":"card","b":"- **\uff0b Add blank for Color Brush**\n- **Color Brush** \u2014 Color Brush (C) \u2014 paint solid RGB or the selected Pattern Brush onto the selected Layer\n- **Recolor** \u2014 Recolor Tool (R) \u2014 on the selected Layer, first click samples source; paint foreground hue/chroma while preserving light and texture\n- **Healing Brush** \u2014 Healing Brush (Shift+J) \u2014 Alt+click clean texture on the selected Layer, then paint to blend its detail into the target\n- **Smudge** \u2014 Smudge Tool (Q) \u2014 smear selected Layer pixels in the drag direction\n- **Burn** \u2014 Burn (J) \u2014 darken selected Layer pixels under the brush"},{"t":"Where things are in the app RIGHT NOW (AI knowledge card, generated from the real UI) > Top toolbar menu: Mask","k":"card","b":"- **\uff0b Grow 1 px** \u2014 Grow Selection 1px \u2014 expand the active Zone selection by one pixel\n- **\uff0b Grow 2 px** \u2014 Grow Selection 2px \u2014 add edge safety around an active Zone selection\n- **\u2212 Shrink 1 px** \u2014 Shrink Selection 1px \u2014 contract the active Zone selection by one pixel\n- **\u2212 Shrink 2 px** \u2014 Shrink Selection 2px \u2014 pull the active Zone selection inward\n- **Fill Holes** \u2014 Fill Selection Holes \u2014 include empty islands fully enclosed by the active selection\n- **Feather 2 px** \u2014 Feather Selection 2px \u2014 soften the active Zone selection edge\n- **\u223f Smooth Edges** \u2014 Smooth Edges \u2014 smooth jagged mask boundaries\n- **\u2298 Invert Mask** \u2014 Invert Mask \u2014 swap selected and unselected areas\n- **Copy Mask** \u2014 Copy Mask \u2014 copy this zone's mask to another zone\n- **Mirror Mask** \u2014 Mirror Mask \u2014 flip mask horizontally\n- **Include Region** \u2014 Include Region \u2014 paint areas to keep in zone color match\n- **Exclude Region** \u2014 Exclude Region \u2014 paint areas to remove from zone color match\n- **Erase Spatial** \u2014 Erase Spatial Strokes \u2014 remove include/exclude paint"},{"t":"Where things are in the app RIGHT NOW (AI knowledge card, generated from the real UI) > Top toolbar menu: Spec Tools","k":"card","b":"- **Decal Rescue Kit\u2026** \u2014 Decal Rescue Kit \u2014 apply a flat, satin, or gloss non-metallic spec beneath sim-stamped numbers and sponsors while preserving source paint\n- **Lighting Mask\u2026** \u2014 iRacing Lighting Mask \u2014 control the spec TGA alpha channel for fake holes, grille openings, recessed vents, and deep seams\n- **Material Sampler\u2026** \u2014 Material Sampler \u2014 click the compiled spec map to read exact M/R/CC/A values and transfer them to an active Zone selection\n- **\u224b Range Remapper\u2026** \u2014 Material Range Remapper \u2014 tune Metallic, Roughness, and Clearcoat ranges inside the active Zone while preserving spec texture"},{"t":"Where things are in the app RIGHT NOW (AI knowledge card, generated from the real UI) > Top toolbar menu: Transform","k":"card","b":"- **\u229e Transform** \u2014 Transform (Ctrl+T) \u2014 Layer mode: selected artwork or selection. Zone mode: current pattern or base.\n- **Fit Layer to Zone Selection** \u2014 Fit Layer to Zone Selection \u2014 proportionally fit the selected artwork Layer inside the active Zone mask, then Enter applies or Esc cancels"},{"t":"Where things are in the app RIGHT NOW (AI knowledge card, generated from the real UI) > Top toolbar menu: Adjust","k":"card","b":"- **Brightness / Contrast** \u2014 Brightness / Contrast \u2014 adjust image brightness and contrast\n- **Hue / Saturation** \u2014 Hue / Saturation \u2014 shift colors and saturation levels\n- **Color Replace** \u2014 Color Replace \u2014 change one color to another everywhere\n- **\u2298 Invert Colors** \u2014 Invert Colors \u2014 negate all pixel colors\n- **Grayscale** \u2014 Grayscale \u2014 convert to black and white\n- **Gradient Map** \u2014 Gradient Map \u2014 map a color gradient to luminosity\n- **\u2295 Vibrance** \u2014 Vibrance \u2014 boost muted colours without over-saturating already-vivid ones\n- **Color Temperature** \u2014 Color Temperature \u2014 warm or cool the image (Kelvin shift)"},{"t":"Where things are in the app RIGHT NOW (AI knowledge card, generated from the real UI) > Top toolbar menu: RENDER HISTORY","k":"card","b":"- **Gallery** \u2014 Open render history gallery \u2014 view all past renders in a grid, search + compare\n- **Recent** \u2014 Recent Renders \u2014 recall one of the last 10 saved renders (survives restart) and restore its full recipe"},{"t":"Where things are in the app RIGHT NOW (AI knowledge card, generated from the real UI) > Header command buttons (top of the window)","k":"card","b":"- **SPEC SCULPT** \u2014 Open the complete guided Spec Sculpt look library\n- **Shokk Drop** \u2014 SHOKK DROP \u2014 import art, Import DNA spec, share .spbdrop packs\n- **FRACTURE THIS PAINT** \u2014 FRACTURE THIS PAINT \u2014 one click drops Soul Core Emerald / Pink Flash into this zone's base material (and its base color unless Color Lock is on)\n- **Save / Open** \u2014 SPB Projects \u2014 save or load a complete workflow: the open paint (PSD included), every zone, and all layer settings in one file\n- **Import Recipe** \u2014 Import a .shokkerrecipe file (your own or one shared with you) and restore the full recipe into your zones"},{"t":"Where things are in the app RIGHT NOW (AI knowledge card, generated from the real UI) > Layers panel (right column, LAYERS tab) buttons","k":"card","b":"- **Open Layered** \u2014 Import a layered PSD, XCF, or ORA file\n- **+ Layer** \u2014 Add Layer \u2014 import PNG/JPG as a new layer on top\n- **Actions** \u2014 Layer document actions\n- **+ Blank layer** \u2014 Add a blank transparent layer to paint on with the Retouch brushes\n- **Flatten document** \u2014 Flatten the whole document into one Layer \u2014 hidden Layers and Zone links are disclosed before removal\n- **Merge visible** \u2014 Merge all VISIBLE layers into one (hidden layers survive) \u2014 Ctrl+Shift+E\n- **Photoshop round-trip** \u2014 Export layers for Photoshop editing and bring the TGA back (round trip)\n- **Thumbnail size** \u2014 Cycle layer thumbnail size (small / medium / large)\n- **Close** \u2014 Close Finish Library (Esc)"},{"t":"Where things are in the app RIGHT NOW (AI knowledge card, generated from the real UI) > Saving your work and coming back later","k":"card","b":"Press **Save / Open** (header row, top right of the tool row): SPB Projects saves or loads a complete workflow in one file - the open paint (PSD included), every zone, and all layer settings. **Import Recipe** / **Share Recipe** move just the zone recipe (colours, finishes, effects) as a .shokkerrecipe file, which works across cars. There is no File menu; Ctrl+S is not documented for projects, so point to the **Save / Open** button."},{"t":"Where things are in the app RIGHT NOW (AI knowledge card, generated from the real UI) > Adding a logo or an image","k":"card","b":"Use the Layers panel (right column, LAYERS tab): **+ Layer** adds a PNG / JPG / WebP / GIF as a new image layer; **Open Layered** imports a whole PSD / XCF / ORA template. Spec Stamps (**Import Stamp**) take a transparent PNG whose alpha marks an area that only changes the spec map. The copilot itself cannot import files."},{"t":"Livery design: how real paint schemes are built > How a livery is built from parts","k":"card","b":"A race-car paint scheme is a base colour, one or two accent colours and a trim colour, laid on the car's named parts. The car is laid out flat on the sheet: two side panels, hood, roof, trunk, front and rear bumper, spoiler. Work part by part with region {part:\"left side\"} and bands, never with boxes across the sheet. The built-in design library (design_recipes, apply_scheme) already knows the proportions: use it for every livery, scheme, throwback and \"X down the sides\" request, then adjust."},{"t":"Livery design: how real paint schemes are built > Where things go on a side panel (height measured from the roof-line down to the rocker)","k":"card","b":"0.00-0.12 the window / roof-line edge; 0.10-0.25 the beltline (a thin stripe here separates body from glass); 0.30-0.65 the door centre where the number lives: keep it calm; 0.64-0.70 a pinstripe above the lower band; 0.68-1.00 the lower body / rocker band, the classic place for the second colour. Front 22% of the length is the front fender; rear 24% is the rear quarter. Sides are mirrored: use both sides in one region {part:[\"left side\",\"right side\"]}."},{"t":"Livery design: how real paint schemes are built > Classic scheme families","k":"card","b":"Retro lower band: body colour, bold lower band, thin trim line above it, bumpers and spoiler in the band colour (Pepsi-style, Sunoco-style, Gulf-style). Classic twin stripes: two parallel stripes along the sides continuing as a centre stripe over hood, roof and trunk (1970s-80s, Martini-style). Two-tone: second colour from the belt down plus hood and bumpers. Colour block: hood, roof and rear quarters in different colours (80s neon, 90s teal). Bookends: contrasting front and rear ends with a quiet body (modern clean). Stealth: dark on dark with one thin accent."},{"t":"Livery design: how real paint schemes are built > Era palettes","k":"card","b":"1960s-70s: powder blue and orange (Gulf-style), navy and white, harvest orange, rust brown, mustard, cream. 1970s-80s: red white and blue with chrome trim (Pepsi-style), black and gold (luxury, JPS-style), blue and yellow (Sunoco-style). 1980s: hot pink, cyan and purple on black or white, sharp blocks. 1990s: teal, purple and magenta splashes. Modern: matte black with one accent, or white with one strong colour. Always check design_recipes: it returns the matching palette (base, a, b, c, trim)."},{"t":"Livery design: how real paint schemes are built > Composition rules that make a scheme look professional","k":"card","b":"One dominant colour (about 60%), one accent (about 30%), one trim (about 10%). Use white or black as the quiet colour so the accents sing. Line the blocks up across the car: the side band continues the bumper colour; the hood stripe continues over the roof and trunk. Keep contrast between the number and its background (the numbers sit on the door centre; do not run a busy stripe behind them). Never paint over numbers, sponsors or tape: the body paint layers only. Flat (matte) paint with chrome trim lines is the modern retro look; gloss everywhere is the showroom look. A \"twist\" on a retro scheme is one unexpected element: a candy or pearl panel, a flipped colour, a metallic roof; not more than one."},{"t":"Livery design: how real paint schemes are built > Finish choices for schemes","k":"card","b":"Flat paint: base::matte. Showroom: base::gloss. Satin: base::satin. Chrome trim lines: base::chrome (a pinstripe in chrome reads as real chrome on a matte car; this is the \"chrome accents over a flat finish\" look). Metallic or candy blocks beside flat blocks create the pop (opposite colour AND opposite shine)."},{"t":"Livery design: how real paint schemes are built > Spec-only changes (shine, metal, roughness) without touching the paint","k":"card","b":"Use a FOUNDATION finish (base::f_*) with color \"source\" on a zone that covers the area: it changes the spec map and leaves the paint exactly as it is (measured on real templates: 0% paint change). NEVER base::chrome, base::metallic or base::candy for this: those repaint the car (78-85% of the hood changed in the test). Looks: mirror chrome = base::f_chrome, satin chrome = base::f_satin_chrome, dark chrome = base::f_dark_chrome, polished metal = base::f_metallic, matte metal = base::f_matte_metallic, pearl = base::f_pearl, satin pearl = base::f_satin_pearl, candy = base::f_candy, brushed metal = base::f_brushed, frosted = base::f_frozen, matte = base::f_soft_matte, satin = base::f_clear_satin, gloss = base::f_soft_gloss. Optionally refine with spec_shift {metal, rough, clearcoat}, spec_patterns (channels M / R / C) and spec_strength. A pearl or colour flip = a holographic or prismatic spec pattern on the metal and clearcoat channels. The paint pictures must look the same before and after."},{"t":"Livery design: how real paint schemes are built > When the buyer says the placement is wrong","k":"card","b":"Do not invent new coordinates. Name the part and its band from get_car_map (\"the lower third of the left side\"), compare to what the zone really covers (STATE zones: covers text and visible share), and fix the part, portion or band. If a part is not known, ask the buyer to show it once (point_at). Say plainly which part you changed."},{"t":"Field playbook: lessons from live design sessions > Playbook: start of every design session (template / wireframe / Wire / Mask layers off, read zones, two pages)","k":"card","b":"1) spb_status, then spb_get_car_map (this also warms the car's named parts so apply_scheme sees them). 2) Switch the TEMPLATE layers OFF yourself with spb_edit_layer: Wire, Mask, Car Mandatory (group \"Turn Off Before Exporting TGA\"). They are sometimes on by default to show the panels, and they draw grids, outlines and fake headlights over the preview you are judging. With Mask off, the dead space between panels shows the base paint colour: that is not on the car and iRacing never shows it. 3) Read the zones (spb_get_zones) before editing: zone numbers move when zones are added on top; use the zone's name or id from the result and check the \"queued: edit zone N (name)\" line names the zone you meant. 4) If two different designs come back on consecutive reads, two SPB pages are open: ask the buyer to close the other tab before changing anything. (Learned 2026-10-01.)"},{"t":"Field playbook: lessons from live design sessions > Playbook: buyer words: \"crushed down to X%\" / pattern smaller / pattern size means scale, \"a touch of colour\" means sparkle, \"same shade\" means sample","k":"card","b":"\"Crushed down to X%\" / \"make the pattern X% of the size\" = the zone's texture SCALE (scale 0.05-5, and spec_patterns[].scale), NOT spec_strength or intensity. Leave spec strength alone unless they say strength. \"A touch of colour\" in a dark area = sparkles or flecks of that colour, NOT a gradient fade. \"Only the yellow in the logo\" = select that colour (+ tolerance) on that art's LAYER inside a small box around it. \"Same shade as X\" = sample X's colour; do not guess a named colour. \"Keep the strokes\" = recolour only the fill colour with a tight tolerance and leave outline colours unselected. \"Starting from the base file\" = clean zones: ask the buyer to reset the zones in the app rather than calling undo many steps. (Owner corrections, 2026-10-01.)"},{"t":"Field playbook: lessons from live design sessions > Playbook: recolour only part of a piece of art (number fill, logo colour)","k":"card","b":"Use a zone with region {layers:[\"Numbers\"], colors:[\"#262626\"], tolerance: 10-16} so only the fill colour is taken and the white and black strokes stay. Sample the real fill colour first (dark fills are often #202020-#2a2a2a, close to a black stroke, so keep the tolerance tight). Then zoom the preview to confirm the outline and drop-stroke survived. For a colour inside one logo (e.g. the yellow of a spray-can graphic), combine colors + a small rect box around that logo + layers limited to the decal layers. WITHOUT the layer limit the box also grabs body paint whose ORIGINAL colour matches (a pink body zone sitting on a yellow base layer gets turned back to yellow inside the box). Check region_check.takes_pixels_from: it should name only the decal/numbers zone."},{"t":"Field playbook: lessons from live design sessions > Playbook: gradients run across the whole sheet","k":"card","b":"A zone gradient is laid over the entire 2048x2048 canvas, not along each part. The car is unwrapped, so a fade on one island does not continue on the bumper or the other side: it will not line up and the buyer notices. Use gradients only for deliberate whole-sheet effects or one-zone-per-panel fades. For \"a little colour coming into the black\" use a flake/sparkle material instead (see the sparkle card). (Owner: the fade \"doesn't line up anyway\", 2026-10-01.)"},{"t":"Field playbook: lessons from live design sessions > Playbook: a touch of colour in black: coloured sparkle / flake in a dark area (blue in the black)","k":"card","b":"What works: a monolithic flake finish as the zone material, then the zone sliders. Black with blue sparkle = monolithic::cf_deep_space (black + deep blue/purple/silver flake) with brightness -45, hue -20 (pushes purple to blue), saturation +60 (makes the flecks read blue, not grey). Measured: about 55% pure black with blue flecks. What does NOT work: paint patterns cannot take a colour (metal_flake draws silver; stardust at high opacity floods the area blue, at low opacity becomes an even navy tint); a second_base over a monolithic special did not show at all. A spec pattern can be added back on top for texture (e.g. spec_patterns snake_scale_diamond, scale 0.25, channels MRC) without changing the colour."},{"t":"Field playbook: lessons from live design sessions > Playbook: adjust a finish's colour with the H/S/B sliders","k":"card","b":"Most \"brings its own palette\" finishes can be steered with hue / saturation / brightness on the zone instead of hunting for another finish. Too dark or navy -> brightness +30 to +40. Leaning violet -> hue -15 (towards sky blue). Grey reading tinted -> saturation -10. Flecks gone grey after darkening -> saturation up. Example that worked: monolithic::fmo_moonstone_adular (blue-white glow over silver schiller) with brightness +35, hue -15, saturation -10 = light ice-blue and steel-grey plates, a real two-colour design with no gradient. (2026-10-01.)"},{"t":"Field playbook: lessons from live design sessions > Playbook: spec-only looks on a solid colour","k":"card","b":"A monolithic special given a SOLID colour keeps that colour flat and contributes its spec: monolithic::fm_python_skin with color #ff2d95 gave a flat pink with a diamond scale pattern in the spec only. Use this for \"keep the colour, give it a <texture> look\" on body colours. For art that must stay pixel-identical (numbers, sponsors) use a Foundation finish with color \"source\" (base::f_soft_gloss for plain gloss). When stacking a chrome fill over gloss decals, keep the special fill zone ABOVE the decal gloss zone (lower index wins) and check spb_get_zones order afterwards."},{"t":"Field playbook: lessons from live design sessions > Playbook: checking effects the preview cannot show","k":"card","b":"The preview image is about 768 px for a 2048 px sheet, so fine effects (sparkle, micro flake, holographic grating at small scale, snakeskin at scale 0.25) average out and can look flat or tinted. Do not conclude \"it did nothing\" from the picture: zoom a crop and measure pixel values, and read spb_preview spec=true. Spec map colours: red = metal, green = roughness, blue = clearcoat (high = dull). Example: base::efx_holographic_drift at scale 0.25 on white accents read flat green in the spec preview but measured metal ~75 vs ~26 for plain gloss, so it was working. Candy, chrome and metal twists are invisible in the flat colour preview: always confirm them on the spec map."},{"t":"Field playbook: lessons from live design sessions > Playbook: things that went wrong (avoid)","k":"card","b":"- spb_undo with many steps after the buyer reset the zones by hand restored an OLD state from earlier sessions (dozens of zones). Prefer muting a zone or editing it back; ask the buyer to reset when they want the base file.\n- The lightning paint pattern on matte black reads as grey cracked glass, not bolts, at any scale.\n- apply_scheme's base colour is limited to the paintable mask: once Mask is hidden, the dead space keeps the old colour. Harmless in iRacing; to cover it anyway use region {everything:true, layers:[body paint layers]}.\n- The zone list does not report scale or spec strength: if the buyer set a value by hand, ask for it instead of overwriting it.\n- On the ARCA Chevrolet SS the spoiler has no body-paint pixels, so schemes skip it."},{"t":"Field playbook: lessons from live design sessions > Playbook: make artwork \"reveal\" / light up when light hits it (face, mask, logo art)","k":"card","b":"Spec-only, two zones on the art, both color \"source\" so the picture never changes: (1) the whole art layer -> base::f_soft_matte (shadows absorb light); (2) ABOVE it, the art's light tones only (region layers:[art layer], colors:[\"#d0d0d0\",\"#a0a0a0\"], tolerance ~40) -> base::f_satin_chrome (broad soft flare). In the sim the light parts flash silver as the sun or track lights sweep across, and the dark parts stay dead, so the shape appears out of the paint. Check spb_preview spec=true: chrome (red) should sit only on highlights, matte (teal) on shadows. Watch for other art on the same layer: light text there gets the chrome too (on a RAM truck the MyersMask layer also held a whole hood panel). Use f_chrome for a harder mirror flash. (Owner request \"highlight dynamically as light hits it, like a reveal\", 2026-10-02.)"},{"t":"Support and troubleshooting: render and iRacing problems > Support: the iRacing User ID (Customer ID) and why a wrong one means \"nothing shows\"","k":"card","b":"Shokker's **iRacing User ID** field is your iRacing **Customer ID**, 4 to 7 digits (helmet icon top right in iRacing, then Profile; also the members site, My Account). It is NOT the car number. iRacing matches a paint to a driver by this number inside the file name, so a file with another ID paints THAT driver's car, never yours, and iRacing says nothing. Shokker blocks a render when the field is empty or not 4 to 7 digits (\"Enter your iRacing User ID (4-7 digits)...\"). A wrong but valid ID renders fine and produces files iRacing never loads for you. Shokker can read the ID from files already in your iRacing paint folders (/api/iracing-id-detect; it fills an empty field by itself after a moment when it is confident). Loading a project or session file can overwrite the ID and the car folder with the saved ones, so check them after loading someone else's file."},{"t":"Support and troubleshooting: render and iRacing problems > Support: Custom Number vs Sim-Stamped Number and iRacing's Hide Car Numbers setting","k":"card","b":"There is no field to type a car number in Shokker. The two switches next to the ID only choose the FILE NAME: **Custom Number** writes car_num_<ID>.tga (the paint carries its own number); **Sim-Stamped Number** writes car_<ID>.tga (iRacing stamps the number and sponsors on top). iRacing decides which one to LOAD with its own setting, Settings > Graphics > **Hide Car Numbers**: ON loads car_num_<ID>.tga, OFF (default) loads car_<ID>.tga. They must agree, or iRacing finds no file and silently shows the paint-shop colours. Restart iRacing after changing the setting; iRacing updates can switch it back. Safest when unsure: render once in each mode, both files stay in the folder. The spec is always car_spec_<ID>.tga. Seeing the number twice means a number-stamp layer of the template was left visible when rendering. (Fixed 2026-10-02: the Custom Number switch used to snap back to ON at every launch because /status did not carry the saved value; with an older engine it can still do that until Shokker is restarted once.)"},{"t":"Support and troubleshooting: render and iRacing problems > Support: where iRacing looks, and the car folder field","k":"card","b":"iRacing reads a car's paint from Documents\\iRacing\\paint\\<car folder>\\. The car folder is created by iRacing the first time you run that car in a race or test session. Its name is the car's path with a space instead of the slash, for example \"stockcars chevyss\"; hovering the tool-tip in iRacing's paint shop shows the exact folder. Shokker's **iRacing Car Folder** must be that car's FOLDER (not a .tga, not Documents\\iRacing\\paint itself, not a helmets/suits folder). The car menu next to the field lists the folders iRacing created, newest first (newest is not always YOUR car: check the name). Quirk: if the typed folder does not exist but its parent does, Shokker silently saves into the PARENT and reports success, so a typo in the last word means the files land where iRacing never reads them. If Documents is redirected or synced by OneDrive, make sure Documents\\iRacing\\paint is the one iRacing really uses. A paint for car A in car B's folder is ignored."},{"t":"Support and troubleshooting: render and iRacing problems > Support: how files get into iRacing (car folder, Auto-deploy, Deploy Now, ZIP)","k":"card","b":"With **iRacing Car Folder** set, every RENDER copies the paint (car_num_<ID>.tga or car_<ID>.tga) and car_spec_<ID>.tga into it (it also leaves spec_*.tga, paint_base.tga and ORIGINAL_* backups of files it replaced: harmless). **Auto-deploy after render** (Settings gear) only matters when the car folder is EMPTY: then it copies into the last car Shokker remembered. With no car folder and no Auto-deploy car, nothing is copied (banner \"No iRacing folder set\"). **Deploy Now** under the render sends the LAST render to another car's folder; only the two newest renders are kept (\"Job not found\" otherwise). **Export ZIP Package** builds a ZIP you download from a link under the render; it is never copied into iRacing. Only RENDER writes into iRacing: live preview and auto-render never do. Paint size must be 2048x2048 (or 1024x1024): other sizes are ignored by iRacing."},{"t":"Support and troubleshooting: render and iRacing problems > Support: making iRacing show the new paint (reload)","k":"card","b":"After a render: Alt+Tab to iRacing, in a session with your car, press **Ctrl+R** (Reload Car Textures). The car flashes white, then shows the files on disk. No restart is needed for a new paint or spec. In a replay, move to a moment when your car is not in the pit lane (iRacing does not reload cars in their pit stalls). The 3D Car Viewer (My Content) reloads a saved paint by itself. A restart IS needed after changing Hide Car Numbers or the 2048 paint textures option. If a car folder did not exist yet, run the car once, then copy/render again. Replays always show whatever files are on disk now."},{"t":"Support and troubleshooting: render and iRacing problems > Support: checklist when \"my paint does not show in iRacing\" (most likely first)","k":"card","b":"1 The iRacing User ID is not your Customer ID. 2 The number switch and iRacing's Hide Car Numbers disagree (only one of car_ / car_num_ exists and iRacing wants the other). 3 The car folder is wrong: other car, the paint root, a typo (parent fallback), not created yet. 4 Nothing was copied: no car folder set, or the render failed (read the red banner). 5 No reload: Ctrl+R, replay pit stall. 6 Wrong size (not 2048x2048 / 1024x1024) or not a real TGA: iRacing silently shows paint-shop colours. 7 Black or partly missing paint: re-export 24-bit TGA (a template alpha channel can blank the paint); glass cars need 32-bit with the glass alpha; check the \"2048 paint textures\" graphics option and restart. 8 Trading Paints Downloader running with \"Update My Own Paints\" on may swap files in the same folder: close it while testing. 9 Others cannot see it: iRacing never shares textures; they need your files (Trading Paints). Always read the live settings first (check_setup / the Talk to Shokker checklist) instead of guessing."},{"t":"Support and troubleshooting: render and iRacing problems > Support: the paint looks different in iRacing than in Shokker","k":"card","b":"- Chrome or metal looks dark or flat: the paint under a metallic part must be near WHITE (iRacing multiplies paint by metal); spec needs metallic ~255 (red) and roughness near 0 (green); blue 255 is dull. Flat chrome on an overcast track can look grey.\n- No shine at all: car_spec_<ID>.tga missing or older than the change; Ctrl+R. iRacing compiles it to a .mip; if the shine still looks old, move car_spec_<ID>.mip out of the folder and reload.\n- Template lines or masks on the car: Wire, Mask, Car_Mandatory or the \"Turn Off Before Exporting TGA\" group were visible when rendering. Switch them off and render again.\n- Number or sponsors twice, or sparkly: iRacing stamps its own numbers and sponsors; the stamp layers must be off, and stamped items take the material of whatever the spec has under them.\n- Preview vs sim: the preview is a quick flat view; iRacing adds sun, shadows, materials and stamps."},{"t":"Support and troubleshooting: render and iRacing problems > Support: the RENDER button will not start (guards, in the order the app checks them)","k":"card","b":"\"A render is already running\" (wait). Button reads OPEN PAINT FIRST / LOADING PAINT (open the template and wait). \"Paint engine is offline - it restarts automatically\" (wait 10 s, else reopen the app). \"Set the Source Paint path\" / \"Source Paint needs a FULL path\" (use the PSD/XCF/ORA or TGA/PNG/JPEG button, or paste the full path). \"Enter your iRacing User ID (4-7 digits)\". \"To render: pick a color on the paint (Pick + Add), then assign a Finish ... Both are required\" (a zone needs a colour AND a finish; muted zones are skipped; it also appears when a zone is limited to a hidden or missing layer). The button is never greyed for missing zones: it shows the toast. A stale imported spec map with no valid zone ends in \"No valid zones\". After a Spec Sculpt save, main RENDER keeps that spec and ignores zones for shine: clear the imported spec map in Settings."},{"t":"Support and troubleshooting: render and iRacing problems > Support: render errors and what they mean","k":"card","b":"**render_busy**: one render at a time; Terminate only stops the app WAITING, the engine still finishes and still copies the files into iRacing; wait a minute. **Render server unreachable / engine offline / hung**: the engine restarts itself; if not, close and reopen the app; antivirus may block python.exe. **Timed out after 5 minutes**: too heavy, use fewer zones. **aggregate RLE decode budget exceeded / decode failed / out of memory**: more than about 16 zones with their own painted area (256 MB of masks); undo or start over. **OUTPUT FOLDER ERROR / iRacing output folder not found / No active car configured**: fix the car folder. **Failed to push ... PermissionError / Copy verification failed**: another program holds the TGA (iRacing paint preview, image viewer): close it and render again. **Unknown base/pattern id ... Did you mean**: a retired finish in a zone; pick another. **Finish Pack needed**: the finish lives in a pack that is not installed (download it if your version has a Finish Packs screen, then restart), or pick another finish. **cross_origin_forbidden**: use the Shokker window, not a hand-opened browser tab. **Job not found**: only the 2 newest renders are kept. Console and logs: Settings > Report a Problem builds a redacted report."},{"t":"Support and troubleshooting: render and iRacing problems > Support: the live preview is stuck, blank or stale","k":"card","b":"Press F5 (or click the red \"Preview failed - showing the LAST GOOD render\" bar). It fails when the engine is offline, a zone has a huge mask set (about 16 zones with their own painted area is the limit), or a decode error occurs; it retries by itself (\"Server busy - retrying\", \"Refreshing preview source\"). Preview times out after 18 s and retries a faster one. A different PSD opened with the old preview still showing means the preview source did not refresh: F5. The preview is not the render and never writes files."},{"t":"Support and troubleshooting: render and iRacing problems > Support: Trading Paints, other drivers, and sharing","k":"card","b":"iRacing never sends textures between drivers; others see your paint only if your files are in THEIR paint folder, which the Trading Paints service and its Downloader do. Shokker only writes local files (a Copy TP Desc button copies a text description; no upload). The Downloader writes into the same folders with the same names: while testing a local paint, close it or turn off \"Update My Own Paints\" (whether it overwrites a local file is not documented: say \"may\"). Trading Paints calls car_ files Sim-Stamped Number paints and car_num_ files Custom Number paints (Custom Number needs TP Pro). Always give the car a plain paint-shop colour scheme in iRacing so others do not see a white car. OneDrive on Documents\\iRacing can break the Downloader."},{"t":"Support and troubleshooting: render and iRacing problems > Support: the spec file and the .mip","k":"card","b":"car_spec_<ID>.tga is optional. Red = metallic, green = roughness (0 mirror, 255 rough), blue = clearcoat (0 off, 16 very shiny, 255 dull), alpha = lighting mask. 24-bit, or 32-bit with alpha. iRacing compiles it to car_spec_<ID>.mip the first time it loads it: for your own car it reads the .tga when that is newer than the .mip, then rebuilds the .mip, so Ctrl+R is enough after a render; other drivers need the .mip (Trading Paints shares it). When the spec is final you can delete the spec .tga so iRacing stops rebuilding it at every start. Numbers and sponsors that iRacing stamps take the material of whatever the spec holds under them."},{"t":"Support and troubleshooting: render and iRacing problems > Support: limits and things Shokker does not do","k":"card","b":"Cars only: helmet and suit folders are not Shokker targets in this build. No automatic Trading Paints upload. Terminate does not stop the engine. Report a Problem does not include your ID or number mode (ask for them, or run the Talk to Shokker check). Shokker cannot read iRacing's own settings (Hide Car Numbers, 2048 paint textures): ask the buyer to look. It cannot see what the sim shows: ask what they see (white car, paint-shop colours, old paint, black parts) before concluding. The AI never renders, saves, exports or deletes for the buyer."},{"t":"Support and troubleshooting: render and iRacing problems > Support: how to help a buyer with a render or iRacing problem (for AIs)","k":"card","b":"1 Call check_setup FIRST (in-app) or spb_check_setup (MCP): it reads their live settings and the files in their car folder and returns findings. 2 Tell them ONE or two likely causes in plain words, most likely first, using the findings; do not dump the whole list. 3 Give exact clicks (top bar, Settings gear, Layers panel). 4 Ask for the exact message when there is one; match it against \"Support: render errors\". 5 Say which side a step is on (Shokker or iRacing) and that Hide Car Numbers and Ctrl+R are iRacing side. 6 Never invent file names, menu items or iRacing options that are not on these cards. 7 Offer the one-click fixes the checklist card has (ID from folder, number mode switch, open car menu, template layers off). 8 When it works, tell them to render again and press Ctrl+R."},{"t":"Support and troubleshooting: render and iRacing problems > Support: where the settings are","k":"card","b":"Top bar: iRacing User ID, Custom Number / Sim-Stamped Number, Source Paint (PSD/XCF/ORA and TGA/PNG/JPEG buttons), iRacing Car Folder (car menu and folder button), RENDER, SPEC SCULPT. Settings gear (top right): Auto-deploy after render, Export ZIP Package, Import Spec Map, Report a Problem, License (render does not need a license check). Under the render: Deploy Now (to another car), Save to keep, Download ZIP Package. Layers panel: template layers (Wire, Mask, Car_Mandatory). Chat: the helper answers questions and checks settings; the gear in the chat sets an AI key and the Brain (Claude or OpenAI models through OpenRouter)."},{"t":"Support and troubleshooting: render and iRacing problems > Support: the two ways to use Claude or OpenAI with Shokker (the gear MODEL is for way 1 only)","k":"card","b":"1) INSIDE Shokker: the buyer types in the Shokker chat; Shokker's own designer answers what it can free and offline, and only what it cannot figure out goes to the Copilot model set in the gear (MODEL; recommended deepseek/deepseek-v4.1-flash, a fraction of a cent per request; there is deliberately no model picker in the studio) through an OpenRouter key pasted once under the gear. 2) FROM the Claude or ChatGPT/Codex app: the buyer types in THAT app, which drives Shokker through the MCP bridge (gear > \"Chat from Claude or ChatGPT\"; install Shokker in that app once) using the buyer's own Claude / ChatGPT plan, no key; the model is chosen inside that app, the Copilot model does not apply. A render or iRacing problem needs neither: \"Check my setup\" (free, offline) reads the live settings."},{"t":"Finish advice: how Shokker helps you pick a finish > Finish advice: what the built-in advisor does (and what to do when it cannot)","k":"card","b":"Ask in plain words and the Shokker copilot answers WITHOUT an AI key: \"what finish should I put on the stripes to make them pop\", \"show me chrome finishes\", \"candy vs pearl\", \"what finish is on my hood right now\", \"which finishes have the most sparkle\", \"something that looks like brushed aluminum\". It answers with 3-6 REAL catalogue finishes as swatch cards (shown on your own car colour): each card has a one-line reason, what kind of finish it is, a **Use on the stripes / hood / body** button (one click applies it, with Undo) and a **Details** button. Follow-ups work: \"show me more\", \"something calmer\", \"something bolder\", \"what about satin instead\", \"and the roof?\". Orders such as \"make my stripes pop\" apply the first pick (Undo takes it back) and keep the others as cards. Yes/no questions (\"will chrome numbers be readable\") get a verdict, \"review my finishes\" lists what to change on the current scheme, and with a picture attached **What finish is this?** (AI) names the closest catalogue finishes. It never changes the car until you press Use. Plain design orders (\"make the stripes chrome\") still go to the designer and are applied straight away. If the advisor cannot find anything it falls back to the AI (when a key is set) or the manual."},{"t":"Finish advice: how Shokker helps you pick a finish > Finish advice: which finishes keep my colours (shine only) and which repaint","k":"card","b":"Each card says what the finish does to colour. **\"shine only: keeps your paint colours\"** = a Foundation finish (Gloss, Satin, Matte, Pearl, Metallic, Candy, Chrome, Satin Chrome, Brushed ...): it changes only HOW the surface shines (the spec map) and your existing paint colours stay. **\"takes the zone colour\"** = the finish needs a colour from the zone (set the zone colour; Candy over red gives candy red). **\"brings its own colours\"** = a complete special look (galaxy, oil slick, holographic ...) with its own palette: it replaces the colour. For an existing livery with sponsors, start with the \"keeps your paint colours\" ones."},{"t":"Finish advice: how Shokker helps you pick a finish > Finish advice: how to choose for stripes, numbers, hood and body","k":"card","b":"- Thin accents (stripes, lower band, trim): they have to read at a glance. A DIFFERENT SHINE from the body does it (matte stripes on a gloss body, or gloss stripes on a flat body); a bright metal edge (satin chrome) or candy glow also works. Chrome is great on thin lines and loud on big areas.\n- Numbers: clean edges and no glare. Gloss, satin or matte; the colour contrast behind the digits matters more than the finish. Avoid chrome, glitter and colour-shifting finishes on numbers (they break up the edges at speed).\n- Big areas (hood, roof, body): pearl, candy, metallic, satin or gloss in the livery colour read premium; one real material (carbon, brushed metal) on one panel lifts the whole car.\n- Adjacent areas must differ in colour or in shine; 2-3 colours plus one accent looks expensive.\n- Premium = restraint. Shimmer looks expensive when it is fine (pearl, fine metallic) and in one place; real glitter is best as one accent."},{"t":"Finish advice: how Shokker helps you pick a finish > Finish glossary: gloss, satin, matte, pearl, metallic, candy, chrome (plain words)","k":"card","b":"- Gloss: standard shiny paint, sharp reflections; the safe default under numbers and sponsors. Satin: low sheen between gloss and matte, hides small flaws. Matte: no clear-coat shine, soft flat colour; the stealth look.\n- Pearl: tiny pearlescent particles, soft shimmer and a slight colour shift with the angle. Metallic: fine aluminium flake, sparkle in sun. Candy: translucent, strongly tinted coat over bright metal, so the colour looks very deep.\n- Chrome: mirror metal that reflects the surroundings; Satin Chrome: the same metal with soft reflections; Dark Chrome: chrome with a black cast. Brushed: fine grain like raw metal. Carbon fibre: woven pattern under clear coat.\n- In the sim iRacing multiplies the paint colour by the metal level in the spec, so any normal colour turned fully metallic goes dark (a chrome part has to be painted white or nearly white): partial-metal finishes (metallic, pearl, satin chrome) keep their colour better. Finish never changes how the car drives, only how it looks."},{"t":"Finish advice: how Shokker helps you pick a finish > Finish search: how the whole catalogue is understood (finish cards, three lanes, more options)","k":"card","b":"Every one of the ~4,800 catalogue items (finishes, paint patterns, spec patterns) has a CARD written once by an AI from its picture and its measurements: a plain-words look, what it resembles, 10-16 words a painter might type, mood, era, car class, best placement, loudness 1-5, busyness 1-5, what it pairs with and what to avoid. Search uses the cards, so \"dusty dirt late model\", \"whiskey amber candy\", \"something expensive like a watch face\" or \"fighter jet grey\" find real matches instead of words in a name. Suggestions come in THREE lanes: **keep** (shine-only finishes that keep your paint colours), **complete** (complete looks that bring their own palette; they replace the colour, so they are ranked by how well the palette suits YOUR colours), **texture** (a spec pattern that changes only the shine, or a paint pattern, layered on top). Say \"show me more\" for options that never repeat, \"bolder\" / \"calmer\" to move the dial, or describe the mood, car class or era you want. Thin accents prefer plain finishes with a different shine from the body; numbers get plain finishes only."},{"t":"Finish advice: how Shokker helps you pick a finish > Finish kits: a finish plan for the whole car in one step","k":"card","b":"Ask \"suggest a finish combo for the whole car\" (or \"what finishes go together\", \"finish package for everything\") and the copilot proposes THREE kits: **Classic** (proven, calm, readable), **Premium** (pearl, metal, candy depth) and **Bold** (stronger finishes plus a complete-look hero panel on the hood). **Premium** and **Bold** also add a fine shine texture (a spec pattern: it changes only the shine pattern, your colours stay) on the hood or roof. A kit covers the body, the stripes and the numbers that your car actually has; the roles are chosen TOGETHER: the accents get a different shine from the body (that is what makes thin lines read), the numbers always stay plain and readable, and no kit repeats another kit's finishes. **Use this kit** applies it in one step (one Undo). \"Show me different kits\" gives three new ones."},{"t":"Finish advice: how Shokker helps you pick a finish > Talking it through: follow-ups that point at what you were just shown","k":"card","b":"The copilot remembers the list it just showed, so you can talk to it like a person:\n- **Point at one:** \"tell me about the second one\", \"I like the second one but more sparkly\", \"use the third one\".\n- **Like X but ...:** \"something like Undertow but calmer\", \"like chrome but darker\", \"texture like carbon fiber but finer\". Changes it understands: calmer, bolder, darker, lighter, glossier, flatter, more / less sparkle, more / less metallic, warmer, cooler, more colourful, more muted, simpler, busier, finer, coarser, and a colour (\"... but in blue\"). Say \"more like this\" to page through more of the same.\n- **Bare tweaks:** after any list just say \"darker\", \"less metallic\", \"a bit shinier\": it re-finds finishes close to what you were looking at, moved that way.\n- **Why:** \"why did you pick that\", \"why not chrome\": it explains from the finish's card (look, loudness / busyness, how it is rated for that part, cautions) or says honestly when there is no real reason against it.\n- **What goes with:** \"what goes with chrome\" gives accents that read next to it (a different shine); \"what finish goes with candy red\" gives finishes for that colour.\n- **Which is best:** \"which of these is best for night racing\" re-ranks the list you just saw for that goal and names a pick. ..."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Header rows (1 of 3)","k":"card","b":"Top of the window: iRacing User ID, Number type, Source Paint (TGA / PSD) and iRacing Car Folder. These decide WHAT is painted and WHERE the files go. Where: Pro > top of the window, first rows (iRacing User ID, Source Paint, iRacing Car Folder).\n- **Download Update** (button): Downloads the new Shokker version. Watch out: Save your project first; installing restarts the app.\n- **Remind Me Later** (button): Hides the update banner for now.\n- **IRACING USER ID box** (text input): Your iRacing customer number (4-7 digits); it is part of the saved file names. Watch out: A wrong ID means iRacing ignores the files.\n- **CUSTOM NUMBER** (toggle): Custom Number: the number is part of your paint and iRacing will not add one. Watch out: Needs Settings > Graphics > Hide Car Numbers ON in iRacing to load car_num_.\n- **SIM-STAMPED NUMBER** (toggle): Sim-Stamped Number: iRacing stamps your number on the car in the series font. Watch out: Do not also paint a number on the template.\n- **SOURCE PAINT box** (text input): The paint file Shokker works on (a flat TGA / PNG / JPEG, or a PSD): type or paste a path, or use the buttons beside it. Watch out: Pasting a folder path here does not load a paint. A flat TGA has no layers; a PSD does."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Header rows (2 of 3)","k":"card","b":"- **TGA/PNG/JPEG** (button): Browse for a flat paint picture (TGA / PNG / JPEG / BMP) and load it as the paint. Watch out: Dropping an image on the canvas also REPLACES the paint; it does not add a logo (use + Layer for that).\n- **PSD/XCF/ORA** (button): Browse for a layered PSD / XCF / ORA template so every layer (body, numbers, sponsors, tape) stays separate. Watch out: Make sure the template layers (Mask, Wire, Car_Mandatory) are OFF before exporting.\n- **IRACING CAR FOLDER box** (text input): The iRacing car folder the finished paint and spec files are written to. Watch out: Point to the car FOLDER, not a TGA file. It sets the file names car_num_ID.tga or car_ID.tga and...\n- **Pick detected iRacing car** (button): Pick your car from the list of iRacing cars Shokker detected (most recently painted first). Watch out: If your car is missing, paint it once in iRacing or browse for the folder.\n- **Browse iRacing car folder in Windows File Explorer** (button): Browse for the iRacing car folder in Windows. Watch out: Pick the car's own folder inside Documents/iRacing/paint, not a TGA file.\n- **FRACTURE THIS PAINT** (button): One click puts a Soul Core Emerald / Pink Flash finish into the selected zone's base (and its colour unless Color Lock is on). Watch out: Changes the zone's colour too unless the Lock is on."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Header rows (3 of 3)","k":"card","b":"- **Settings** (button): Opens Settings: licence, keyboard shortcuts, ZIP export, spec map import, Live Link, Training Wheels.\n- **Tutorial** (button): Training Wheels: step-by-step quests that teach the app as you use it (load, zone, finish, render, then patterns, spec, overlays), plus a hint chip for your next move. Watch out: Toggle it any time; it is also a checkbox in Settings.\n- **Make UI chrome smaller** (button): shrink toolbar / panel chrome (does NOT zoom the canvas)\n- **UI Larger** (button): grow toolbar / panel chrome (does NOT zoom the canvas)\n- **SPEC SCULPT** (button): Open the complete guided Spec Sculpt look library\n- **Shokk Drop** (button): import art, Import DNA spec, share .spbdrop packs\n- **Encyclopedia** (button): SPB Encyclopedia: how everything in Shokker works - spec maps, zones, finishes, every control. Press / inside to search."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Any mode: PRO / CHAT pill","k":"card","b":"Switches between the full shop and the talk-to-Shokker front door. The paint and zones carry across. Where: Any mode > top row > PRO / CHAT pill.\n- **PRO** (button): Switch to the full Pro shop.\n- **CHAT** (button): Switch to Chat (talk to Shokker)."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Top toolbar (1 of 6)","k":"card","b":"Tool row (Move, Pick, Color, Wand, Lasso, Rect, Brush, Fill, Erase), the HISTORY / SELECT / RETOUCH / MASK / SPEC TOOLS / TRANSFORM / ADJUST menus, the ZONE / LAYER target switch, RENDER HISTORY, Save / Open and Import Recipe. Where: Pro > top toolbar (tool row).\n- **Move** (button): Move tool (V): in Layer mode click a sponsor / number to drag it; Alt forces the whole layer. Watch out: Switch ZONE / LAYER to LAYER first.\n- **Pick** (button): Pick Item (Y): pick one sponsor / number inside a layer for independent move / rotate.\n- **Color** (button): Color (P): click a colour on the paint to select by it. In Pro zone mode it feeds the selected zone's colour list.\n- **Wand** (button): Magic Wand (W): click to select similar colour; Shift adds, Alt subtracts; Tolerance sets how similar.\n- **Lasso** (button): Lasso (L): draw a free-hand selection. Watch out: Enter closes the shape.\n- **Rect** (button): Rectangle select (O): drag a box selection.\n- **Brush** (button): Brush (B): paint the zone's mask, or the selected layer's pixels. Watch out: ZONE mode paints a mask; LAYER mode paints pixels.\n- **Fill** (button): Fill bucket (K): fill a region of the zone mask or the layer.\n- **Erase** (button): Eraser (E): erase zone mask or layer pixels.\n- **History** (menu): HISTORY menu: Undo, Redo, Undo History."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Top toolbar (2 of 6)","k":"card","b":"- **Undo Ctrl+Z** (button): Undo the last stroke, transform or layer action (Ctrl+Z).\n- **Redo Ctrl+Y** (button): Redo (Ctrl+Y or Ctrl+Shift+Z).\n- **Undo History\u2026** (button): Opens the recent-actions list so you can jump back several steps.\n- **Select** (menu): SELECT menu: Select All Color, Grab Object, Smart Region Fill, Move Selection Border, Pick Layer Element, Zone Pick, Elliptical Marquee.\n- **Select All Color** (button): Select All Color (A): select every pixel of the sampled colour across the whole paint.\n- **Grab Object** (button): Grab Object (G): click inside a number or logo and its whole outline is selected. Watch out: Works best on clear solid shapes.\n- **Smart Region Fill** (button): Smart Region Fill: click inside an edge-bounded area to select it.\n- **Zone Pick** (button): Zone Pick: click a spec pattern / base piece to move, rotate and resize it independently.\n- **Retouch** (menu): RETOUCH menu: Color Brush, Recolor, Healing Brush, Smudge, Burn - pixel retouching on the selected layer. Watch out: Grey until a blank layer exists: use the Add blank for Color Brush button.\n- **\uff0b Add blank for Color Brush** (button): Adds a blank layer so the Color Brush has somewhere to paint.\n- **Color Brush** (button): Color Brush (C): paint solid colour or a pattern brush onto the selected layer. Watch out: Needs a blank paintable layer (use + Blank layer)."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Top toolbar (3 of 6)","k":"card","b":"- **Recolor** (button): Recolor (R): paint a new hue over a sampled colour on the selected layer.\n- **Mask** (menu): MASK menu: Grow / Shrink / Fill Holes / Feather / Smooth / Invert / Copy / Mirror a zone's area, plus Include / Exclude Region.\n- **Spec Tools** (menu): SPEC TOOLS menu: Decal Rescue Kit, Lighting Mask, Material Sampler, Range Remapper.\n- **Decal Rescue Kit\u2026** (button): Puts a flat / satin / gloss NON-metallic spec under sim-stamped numbers and sponsors so they read cleanly.\n- **Lighting Mask\u2026** (button): Controls the spec alpha channel (fake holes, grille openings, recessed vents). Watch out: Advanced.\n- **Material Sampler\u2026** (button): Click the compiled spec map to read exact Metallic / Roughness / Clearcoat values and copy them to a zone.\n- **Range Remapper\u2026** (button): Retunes Metallic / Roughness / Clearcoat ranges inside the active zone while keeping the texture.\n- **Transform** (menu): TRANSFORM menu: Transform (Ctrl+T) and Fit Layer to Zone Selection.\n- **Adjust** (menu): ADJUST menu: Brightness/Contrast, Hue/Saturation, Color Replace, Invert, Grayscale, Gradient Map, Vibrance, Color Temperature. Watch out: These edit the paint pixels; finishes and zone Hue Shift are render settings."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Top toolbar (4 of 6)","k":"card","b":"- **Hue / Saturation** (button): Shifts hue and saturation of the selected layer or paint. Watch out: Applies to pixels, unlike zone Hue Shift which is a render setting.\n- **Color Replace** (button): Replaces one colour with another everywhere on the layer or paint. Watch out: This edits pixels; for finishes use a zone.\n- **ZONE** (button): ZONE mode: toolbar tools edit zones and masks. Watch out: Tools behave differently in ZONE vs LAYER mode - check this switch if a tool \"does nothing\".\n- **LAYER** (button): LAYER mode: toolbar tools edit the selected layer's pixels.\n- **Recent** (button): Recent Renders: recall one of your last 10 saved renders and restore its recipe.\n- **Save / Open** (button): Save / Open: saves or loads a complete workflow in one file (paint incl. PSD, every zone, all layer settings). Watch out: There is no File menu; this is the save.\n- **Import Recipe** (button): Imports a .shokkerrecipe (yours or shared) and restores the recipe (colours, finishes, effects) on this car.\n- **Xform** (button): Layer mode: selected artwork or selection. Zone mode: current pattern or base.\n- **Excl** (button): paint areas on the car to REMOVE from this zone's color match (red overlay)\n- **Move Selection Border** (button): Arrow moves 1px, Shift+Arrow moves 10px; drag inside to move freely; pixels do not move"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Top toolbar (5 of 6)","k":"card","b":"- **Pick Layer Element** (button): always force isolation of one sponsor/number/shape inside the layer for its own tight transform box\n- **Elliptical Marquee** (button): drag a Zone selection; Shift makes a circle, Alt draws from center, Esc cancels\n- **Healing Brush** (button): Alt+click clean texture on the selected Layer, then paint to blend its detail into the target\n- **Smudge** (button): smear selected Layer pixels in the drag direction\n- **Burn** (button): darken selected Layer pixels under the brush\n- **\uff0b Grow 1 px** (button): expand the active Zone selection by one pixel\n- **\uff0b Grow 2 px** (button): add edge safety around an active Zone selection\n- **Shrink 1 px** (button): contract the active Zone selection by one pixel\n- **Shrink 2 px** (button): pull the active Zone selection inward\n- **Fill Holes** (button): include empty islands fully enclosed by the active selection\n- **Feather 2 px** (button): soften the active Zone selection edge\n- **Smooth Edges** (button): smooth jagged mask boundaries\n- **Invert Mask** (button): swap selected and unselected areas\n- **Copy Mask** (button): copy this zone's mask to another zone\n- **Mirror Mask** (button): flip mask horizontally\n- **Include Region** (button): paint areas to keep in zone color match\n- **Exclude Region** (button): paint areas to remove from zone color match"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Top toolbar (6 of 6)","k":"card","b":"- **Erase Spatial** (button): remove include/exclude paint\n- **Transform** (button): Layer mode: selected artwork or selection. Zone mode: current pattern or base.\n- **Fit Layer to Zone Selection** (button): proportionally fit the selected artwork Layer inside the active Zone mask, then Enter applies or Esc cancels\n- **Brightness / Contrast** (button): adjust image brightness and contrast\n- **Invert Colors** (button): negate all pixel colors\n- **Grayscale** (button): convert to black and white\n- **Gradient Map** (button): map a color gradient to luminosity\n- **Vibrance** (button): boost muted colours without over-saturating already-vivid ones\n- **Color Temperature** (button): warm or cool the image (Kelvin shift)\n- **RENDER HISTORY** (menu): click a thumbnail to rebuild it fully\n- **Gallery** (button): view all past renders in a grid, search + compare"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Settings (gear)","k":"card","b":"Licence key, Keyboard Shortcuts, ZIP export, Live Link / auto-deploy, imported spec map, Training Wheels, file picker style. Where: Pro > Settings (gear) > License.\n- **ZIP export checkbox** (toggle): Bundles paint TGA, spec TGA and preview into a ZIP on every render.\n- **Import TGA** (button): Import an existing spec map TGA to merge under your render. Watch out: Use Clear to go back to the default spec.\n- **Auto-deploy (Live Link) checkbox** (toggle): Auto-deploy: copies every render to your iRacing car folder automatically. Watch out: Only matters when the car folder is empty; with a car folder set, files are copied after each render anyway.\n- **Licence key box** (text input): Enter your Shokker Paint Booth license key (format: SHOKKER-XXXX-XXXX-XXXX, 19 characters total)\n- **Activate** (button): Validate and activate your license key\n- **Deactivate** (button): required if you want to use the key on a different machine\n- **Training Wheels checkbox** (toggle): step-by-step quests and a next-move hint chip that teach the app while you use it\n- **Keyboard Shortcuts** (button): Show all keyboard shortcuts (press ?)\n- **Clear** (button): Remove imported spec map and render on default base\n- **Close (Esc)** (button): Close shortcuts overlay (Esc)"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: ZONES (left column)","k":"card","b":"The list of zones, top = highest priority. Each card shows what it covers. + Add Zone, Reset All Zones, More menu. Click a card to open its ZONE POPOUT PANEL. Where: Pro > left column (ZONES).\n- **+ Add Zone** (button): Adds an empty zone at the top. Watch out: A new zone does nothing until you give it a colour / layer / box AND a finish.\n- **Reset All Zones** (button): Resets to the default set of zones (confirmed, undoable).\n- **More** (button): Opens the More menu (presets, randomise, apply to all, library, templates, SHOKK files, channel PNG export).\n- **Collapse arrow (left column)** (button): Collapses or expands the ZONES column.\n- **Zone editor tab (E)** (button): Shows or hides the floating ZONE POPOUT PANEL (press E)."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: ZONES > More menu (1 of 2)","k":"card","b":"Presets Gallery, randomise, Apply Finish to All, Shokker Library, Undo History, templates, SHOKK files, PNG channel export. Where: Pro > left column > ZONES > More (three-dot) menu.\n- **Presets Gallery** (button): Browse ready-made zone layouts / looks and apply one.\n- **Rand Current Zone** (button): Randomises the finish of the selected zone. Watch out: Ctrl+Z undoes.\n- **Rand All Zones** (button): Randomises every zone. Watch out: Overwrites your finishes (undoable).\n- **Apply Finish to All** (button): Gives the same finish to every zone.\n- **Shokker Library** (button): Opens the Shokker Library of saved looks.\n- **Undo History** (button): Opens the Undo History list.\n- **Save as Template** (button): Saves the current zone layout as a named template.\n- **Load Template... dropdown** (dropdown): Dropdown of your saved zone templates; choosing one loads it.\n- **LOAD SHOKK FILE** (button): Loads a saved .shokk session.\n- **SAVE SHOKK** (button): Saves the zones and finishes (and optionally the paint) as a .shokk file.\n- **PNG Channels Export** (button): Exports the paint and the spec channels as PNG pictures for inspection or Photoshop.\n- **Export folder box (PNG channels)** (text input): Folder where PNG channel exports are written.\n- **Browse Folder** (button): Choose the export folder in Explorer."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: ZONES > More menu (2 of 2)","k":"card","b":"- **Smart Randomize checkbox** (toggle): Smart Randomize: picks good-looking combinations instead of pure chance.\n- **e.g. My 3-Color Layout (max 60 chars)** (text input): use a descriptive name you'll recognize later\n- **Save** (button): Save current zone layout as a reusable template"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: ZONE POPOUT PANEL (1 of 9)","k":"card","b":"Where one zone is edited: COLOR (which pixels), APPLY AREA (box / lasso), BASE (finish + colour + strengths + spec sliders), SPEC OVERLAYS, PATTERN, OVERLAYS (2nd to 5th base). Where: Pro > ZONE POPOUT PANEL.\n- **Reset Zone** (button): Puts this one zone back to its defaults (finish, colour, patterns, sliders). Watch out: It resets the zone, not the whole car - Reset All Zones in the left column does that.\n- **COLOR (section)** (section): Decides WHICH PIXELS of the paint this zone owns: by clicked colour, by PSD layer, or as catch-all (Remaining). Watch out: A zone with no colour, layer or box set does nothing (\"No color or region set yet\" warning).\n- **RESTRICT TO LAYERS (checkboxes per PSD layer)** (toggle): Tick a layer (Car Paint, Sponsors, Numbers, Tape ...) and the zone only covers pixels that exist on that layer. Watch out: Layers named Mask / Wire / Car_Mandatory are template layers - do not restrict to them. Unticking...\n- **PICK COLOR FROM CAR** (button): Arms an eyedropper: click a colour on the car and this zone grabs every pixel of that colour. Each further click ADDS another colour. Watch out: Anti-aliased edges need tolerance; if edges are left over raise tolerance. Colours that also appear on..."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: ZONE POPOUT PANEL (2 of 9)","k":"card","b":"- **Remaining** (button): Makes this zone the catch-all: it gets every pixel no zone above it claims. Watch out: Put it at the BOTTOM of the zone list; higher zones win overlaps.\n- **HEX (colour box and colour wheel) + Apply** (text input): Type or pick a colour to select by (with Apply), or use the wheel which applies live. Watch out: This chooses which paint pixels to catch, it does not recolour them. To RECOLOUR use BASE > Base Color >...\n- **Colour tolerance (sliders next to the colour chips)** (slider): How close a pixel must be to the picked colour to belong to the zone (about 30-50 normal; 6 = exact shade, 100 = loose). Watch out: Too high grabs neighbouring colours; too low leaves fringes around lettering.\n- **Hard Edge** (toggle): Cuts the zone edge sharp instead of softly anti-aliased. Watch out: Hard edges can look jagged on diagonal lines.\n- **APPLY AREA (section)** (section): Limits the zone to a drawn shape (box or lasso) or a refined colour area, on top of the colour/layer choice. Watch out: \"Draw box\" boxes are on the flat unwrapped sheet; one box may cover several car panels.\n- **Draw box** (button): Click, then drag a rectangle on the paint; the zone only affects what is inside it. Watch out: The box is on the flat sheet - the hood and the roof are different rectangles, not one."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: ZONE POPOUT PANEL (3 of 9)","k":"card","b":"- **Lasso (apply area)** (button): Draw a free-hand outline; the zone only affects what is inside. Watch out: Close the shape by returning near the start point.\n- **Refine color** (button): Keeps the colour selection but lets you paint a green brush to limit it to places you choose. Watch out: Needs a colour already set on the zone.\n- **Activate (apply area)** (button): Turns the stored apply area on again after you cleared or paused it.\n- **Clear (apply area)** (button): Removes the drawn box / lasso so the zone is back to colour/layer only.\n- **Fit pattern/base swatch into box** (toggle): Instead of tiling across the sheet, fit one copy of the pattern / base texture into the drawn box. Watch out: Only base + pattern are fitted, not spec overlays.\n- **BASE (section)** (section): Everything about the surface look: finish, colour source, hue / saturation / brightness, strengths, scale, rotation, spec sliders. Watch out: Without picking a finish the zone shows source paint unchanged.\n- **Base Material (finish picker button)** (picker): Opens the finish picker popup: bases (gloss, matte, satin, chrome, candy, pearl, metallic ...) and special looks. Shows the current finish name. Watch out: Foundation (f_*) finishes change only the spec when colour = Use source paint; bases like chrome / candy..."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: ZONE POPOUT PANEL (4 of 9)","k":"card","b":"- **Lock (Base Color lock)** (toggle): When on, switching finish keeps your zone colour instead of auto-adopting the finish's default colour.\n- **BASE COLOR dropdown** (dropdown): Where the zone colour comes from: Use finish's own color / Use source paint (spec only) / Use solid color / From special / Custom gradient. Watch out: Solid colour on a finish that brings its own colours (carbon, camo, holographic ...) flattens it to one...\n- **Solid colour swatch / hex (appears with Use solid color)** (picker): Paints the zone this exact colour with the finish's shine on top. Watch out: Only used when BASE COLOR = Use solid color.\n- **Custom gradient (stops + direction)** (section): 2 to 10 colour stops fading across the zone in a chosen direction. Watch out: Direction runs on the flat sheet, so each car side may fade differently - use one zone per side to control...\n- **Hue Shift** (slider): Rotates every colour around the colour wheel (-180 to +180). Keeps the finish's structure. Watch out: Shift = target hue minus current hue; +150 on green gives purple, not pink.\n- **Saturation** (slider): How vivid or grey the colour is (-100 to +100).\n- **Brightness** (slider): Lighter or darker (-100 to +200)."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: ZONE POPOUT PANEL (5 of 9)","k":"card","b":"- **Base Strength** (slider): Fades the whole base look over the source paint: 0 = original paint, 100 = full finish. Watch out: This also reduces colour changes; for shine only use Spec Strength.\n- **Spec Strength** (slider): Overall strength of the spec map (shine / metal / coat) of this zone.\n- **Base Scale** (slider): Size of the finish's texture inside this zone (0.05x to 5.0x; 1.00x is normal). Smaller = finer, more repeats. Watch out: Scales the texture, NOT the colours or the whole car; spec follows it unless Independent Spec is ticked.\n- **Base Rotation** (slider): Rotates the finish's texture in 5 degree steps.\n- **Color Depth** (slider): For candy / tinted finishes: 0 = no tint, 15 = glaze, 65 = rich, 100 = deepest. Watch out: Only shows on candy-like finishes.\n- **Color Flip** (slider): Adds a second hue that appears at an angle (0 = off, 90 = neighbour, 180 = opposite). Watch out: Only on finishes that support it.\n- **Underglow** (slider): How much of the ground coat burns through the brights.\n- **Independent Spec (checkbox by Spec Scale)** (toggle): Lets Spec Scale differ from Base Scale; otherwise spec follows the base size.\n- **Spec Scale** (slider): Size of the shine / metal texture (0.05x-5.0x) when independent. Watch out: Ignored until Independent Spec is ticked.\n- **Spec Rotation** (slider): Rotates the spec channels in 5 degree steps."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: ZONE POPOUT PANEL (6 of 9)","k":"card","b":"- **Spec Blend** (dropdown): How a pattern changes this base's optics: Normal, Ghost Carve, Chrome Inlay, Frost Etch, Angle Flip, Ember Gate, Depth Press, and legacy Multiply / Screen / Overlay...\n- **Spec Sliders (R Metal, G Rough, B Coat)** (section): Three sliders (-127 to +127) that push the whole zone's spec map: R = metal, G = roughness (low = mirror), B = clearcoat. Watch out: B Coat is inverted in iRacing terms - the number moves clearcoat strength, see the tooltip. Spec only...\n- **Auto-Pop** (button): One click nudges the three spec sliders toward glossier (more metal flash, less rough, deeper clearcoat) so the zone pops on track. Watch out: It nudges from where the sliders are; press repeatedly for more, Reset arrows to go back.\n- **Spec preset... dropdown** (dropdown): Applies a named spec feel (Wet Candy, Track Flash, Chrome Mirror, Deep Gloss, Soft Pearl, Satin Matte) to the R/G/B sliders.\n- **Save spec preset (disk icon)** (button): Saves this zone's R/G/B spec shifts under a name you can reuse.\n- **R Metal** (slider): Pushes the METAL channel (-127 to +127). More metal = the body colour flashes harder.\n- **G Rough** (slider): Pushes ROUGHNESS (-127 to +127). Lower = sharper mirror flashes, higher = soft satin glow.\n- **B Coat** (slider): Pushes CLEARCOAT (-127 to +127). 16 is max gloss: minus = glossier (stops at 16), plus = duller."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: ZONE POPOUT PANEL (7 of 9)","k":"card","b":"- **SPEC OVERLAYS + ADD SPEC OVERLAY** (section): Stack spec-only textures on top of the base: they change shine / metal / roughness patterns, never the colour. Watch out: Colour preview will not show them; look at the spec channel views.\n- **+ ADD SPEC OVERLAY** (button): Opens the spec-overlay picker to add one more spec texture layer. Watch out: Up to 5 layers on the primary base.\n- **PATTERN (section)** (section): Adds a visible pattern (carbon, camo, flames, stripes ...) on this zone, with Paint mode, Opacity, Strength, Hue, Saturation, Spec amount, Scale, Rotate and Position.\n- **Pattern 1 picker (name + dropdown arrow)** (picker): Choose the pattern from the catalogue; \"None\" (x) removes it.\n- **+ Add Layer (pattern)** (button): Adds a second / third pattern layer to the zone.\n- **Paint mode (Overlay / Blend)** (dropdown): Overlay = the pattern paints its own colours over the paint; Blend = it keeps the underlying paint colour. Watch out: In Overlay the pattern's own colours win, so the base colour is hidden - use Blend or Hue to recolour.\n- **Opacity (pattern)** (slider): How visible the pattern is, 0-100%.\n- **Strength (pattern)** (slider): Pattern paint strength in 5% steps; spec amount is separate.\n- **Hue / Saturation (pattern)** (slider): Recolours only the pattern artwork (hue -180..180, saturation -100..100). Overlay mode uses this colour."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: ZONE POPOUT PANEL (8 of 9)","k":"card","b":"- **Spec amount (pattern)** (slider): Starts at 0% so your base shine stays; raise to reveal the pattern's own metal / rough / coat. Watch out: Spec starts at 0 on purpose.\n- **Scale (pattern)** (slider): Size of the pattern: smaller = more repeats, larger = zoomed in (0.1x to 4x). Watch out: On a whole-car canvas a normal-size pattern looks huge: go below 1.0x for fine detail.\n- **Rotate (pattern)** (slider): Rotates the pattern 0-359 degrees (also a number box).\n- **Pattern placement: Full Canvas / Fit to Zone / Edit on Template** (button): Choose how the pattern is placed: tiled over the sheet, fitted to the zone, or dragged by hand on the template.\n- **Advanced Pattern Control Panel (Position X / Y, Flip H / V, Strength Map)** (section): Slide the pattern left/right and up/down, flip it, or paint where it is strong versus weak.\n- **OVERLAYS (2nd to 5th base)** (section): Stack extra base finishes over the first with blend modes.\n- **2nd Base (picker) + Add 3rd overlay** (picker): Pick a second finish blended on top of the primary base; \"+ Add 3rd overlay\" shows the next slot.\n- **Zone order (drag handle and priority)** (section): Top zone wins where two zones select the same pixels. Watch out: Remaining belongs at the bottom."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: ZONE POPOUT PANEL (9 of 9)","k":"card","b":"- **Zone eye / duplicate / link / x icons on each zone card** (button): Eye hides a zone for testing, the copy icon duplicates, the x deletes it. Watch out: x removes the zone (undoable with Ctrl+Z).\n- **Color Scale / Color Rotation** (slider): Zooms and rotates the colour art (gradient or borrowed special colours) without touching the material texture. Watch out: Solid colours have nothing to scale; these only appear for From special / Custom gradient.\n- **Intensity (zone strength, legacy preset buttons)** (slider): Overall strength of the zone's effect: lower = closer to the original paint and a calmer spec. Watch out: Not seen in the live panel of build 10.0.3 (listed in app_controls.json); prefer Base Strength / Spec...\n- **Wear / weathering** (slider): Scuffs and ages the finish (chips, dulling). Watch out: Not seen in the live panel of build 10.0.3; check for a Wear control or ask Chat for a weathered finish."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Centre column (1 of 2)","k":"card","b":"The paint (SOURCE) and the LIVE PREVIEW of the finished car, zoom buttons, the RENDER button and the spec channel strip. Where: Pro > centre > empty canvas.\n- **Blank Canvas** (button): Blank Canvas: start from plain white to design from scratch.\n- **Zone overlay opacity percent** (slider): Zone overlay opacity: how strongly the zone colour overlay shows on the canvas (default 50%).\n- **Import PSD** (button): Import PSD: load a Photoshop template to get editable layers.\n- **Load TGA** (button): Load TGA: load a flat paint picture (no layers).\n- **Edit Big** (button): Edit Big: hide the live preview and edit the source canvas larger.\n- **SOURCE** (button): SOURCE view: the original paint canvas where tools work.\n- **CAR** (button): CAR view: show the rendered car under the canvas while tools stay active.\n- **SPLIT** (button): SPLIT view (Shift+V): source and live preview side by side.\n- **Load Paint Image** (button): browse for a car paint TGA file\n- **Spatial brush size** (slider): Spatial brush size\n- **Blank Canvas** (button): start with a blank white canvas for color-shift effects\n- **Refresh** (button): aborts any stuck render, clears pipeline, and re-runs. Use this if the preview is hung.\n- **B/A** (button): compare the last preview against the current one\n- **Channels** (button): view spec map channels and numeric values"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Centre column (2 of 2)","k":"card","b":"- **Zoom out canvas** (button): decrease canvas zoom\n- **Zoom In (Ctrl+Plus)** (button): increase canvas zoom\n- **FIT** (button): fit canvas in viewport\n- **1:1** (button): 100% zoom (1:1 pixels)\n- **Compare** (button): before/after comparison slider"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Tool options bar (1 of 5)","k":"card","b":"Appears under the toolbar; its sliders change with the tool you picked (brush size, wand tolerance, text font ...). Where: Pro > centre > tool options bar (changes with the active tool).\n- **Selection mode dropdown (Add / Replace / Subtract)** (dropdown): How a new selection combines with the existing one: Add (+), Replace, Subtract.\n- **Brush size in pixels** (slider): Brush / eraser size in pixels (1-300); [ and ] keys change it.\n- **Brush shape dropdown** (dropdown): Shape of the brush tip: round, square, diamond, slash, noise.\n- **Pattern Brush \u2014 paint with a texture instead of solid color** (dropdown): Paint with a texture instead of a solid colour.\n- **Eraser mode \u2014 soft brush, hard square block, or clear the current Layer / Zone mask** (dropdown): Eraser style: soft brush, hard block, or clear the whole layer / zone mask.\n- **Gradient shape used by the active Layer or Zone** (dropdown): Shape of the gradient tool: linear, reflected, radial, angular, diamond.\n- **Gradient Reverse** (toggle): Flips the gradient direction.\n- **Gradient Fg To Transparent** (toggle): Fade the foreground colour to transparent instead of to the background colour.\n- **Font** (dropdown): Font for text options. Watch out: There is no Text button in the main tool row; add lettering as a PNG layer.\n- **Text Bold** (toggle): Bold text option."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Tool options bar (2 of 5)","k":"card","b":"- **Text Italic** (toggle): Italic text option.\n- **Text transform** (dropdown): Text case: as typed, UPPERCASE, lowercase, Capitalize.\n- **Text effect** (dropdown): Text effect: drop shadow, outer glow, emboss and more.\n- **Shape type** (dropdown): Shape for the shape tool: rectangle, rounded rectangle, ellipse, triangle, polygon, star, line.\n- **Shape Filled** (toggle): Fill the shape with the fill colour.\n- **Shape stroke color** (picker): Outline colour of a shape.\n- **Start cap** (dropdown): Line start cap: flat, round, arrow.\n- **End cap** (dropdown): Line end cap: flat, round, arrow.\n- **Dash style** (dropdown): Line style: solid, dashed, dotted, dash-dot.\n- **Fg Color Picker** (picker): Foreground (paint) colour for brushes and fills; X swaps with background.\n- **Layer Brush / Fill paint source** (dropdown): Brush / Fill source on a layer: solid colour or a baked Special finish.\n- **Clone Aligned** (toggle): Aligned clone: the source moves with the brush.\n- **Healing Aligned** (toggle): Aligned healing source.\n- **Color difference allowed (higher = more colors included)** (slider): How different a colour can be and still get picked (higher = more colours).\n- **Wand Contiguous** (toggle): Contiguous: only select touching pixels of that colour (off = everywhere)."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Tool options bar (3 of 5)","k":"card","b":"- **Sample area \u2014 averages color under cursor for more forgiving selection** (dropdown): Sample area for the wand: single point or an average of 3x3 / 5x5 / 11x11 pixels.\n- **Wand Anti Alias** (toggle): Smooths the wand selection edge.\n- **Active paint tool opacity percent** (slider): Active paint tool opacity: 100% (range 1-100%). Press 1-9 keys for quick opacity (1=10%, 5=50%, 0=100%).\n- **Smudge strength percent** (slider): Smudge strength: how firmly each dab carries picked-up pixels (1-100%).\n- **Dodge and Burn tonal range** (dropdown): Choose which tones Dodge or Burn affects most\n- **Dodge and Burn exposure percent** (slider): Dodge/Burn exposure: strength built up by each pass (1-100%). Number keys set exposure.\n- **Blur and Sharpen strength percent** (slider): Blur/Sharpen strength: effect built up by each pass (1-100%). Number keys set strength.\n- **Brush hardness percent** (slider): Brush hardness: 100% (range 0-100%, 0=soft feather, 100=hard edge). Use { } keys to adjust.\n- **Brush flow percent** (slider): how fast paint builds up per pass (1-100%)\n- **Brush spacing percent of brush size** (slider): distance between dabs (% of brush size)\n- **Brush stroke smoothing percent** (slider): averages pointer jitter (0-100%). 10% is the natural default."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Tool options bar (4 of 5)","k":"card","b":"- **Brush stabilizer distance in pixels** (slider): Lazy-mouse stabilizer rope in source pixels (0-200px). Higher values make the brush tip trail the pointer.\n- **Reference image opacity** (slider): Reference image opacity\n- **Font size (px)** (number input): Font size (px)\n- **Fill color** (picker): Fill color\n- **Outline color** (picker): Outline color\n- **Outline width** (number input): Outline width\n- **Letter spacing (px)** (number input): Letter spacing (px)\n- **Line height multiplier** (number input): Line height multiplier\n- **Shape fill color** (picker): Shape fill color (used when Fill is checked)\n- **Shape stroke width in canvas pixels** (number input): Shape stroke width in canvas pixels (0 disables stroke)\n- **Shape corner radius in canvas pixels** (number input): Rectangle corner radius in canvas pixels\n- **Shape vertex count** (number input): Polygon or star vertex count\n- **#hex** (text input): Foreground hex color\n- **Swap foreground and background colors** (button): swap foreground and background colors\n- **Reset foreground and background colors** (button): Reset foreground/background colors to default black/white (button only \u2014 D is Dodge)\n- **Save Swatch** (button): save foreground color to swatches\n- **Choose Special...** (button): Choose a baked Special finish for layer fill / brush"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Tool options bar (5 of 5)","k":"card","b":"- **Choose Special...** (button): Current baked Special source\n- **PathSelection** (button): Close any open path and convert it to the active Zone selection\n- **Clear Path** (button): Clear current path without changing selection history\n- **Clone opacity percent** (slider): Clone opacity\n- **Set source** (button): Arm source picking, then click a clean area on the canvas\n- **Clear source** (button): Forget the current Healing source\n- **Save snapshot** (button): Capture the current composite and every Layer for selective restoration\n- **Clear** (button): Forget the saved History Brush source\n- **Auto-feather selection edges (px). 0 = off (hard edge). Any value softens the edge of the NEXT selection you commit (marquee / lasso / wand / pen / smart-fill), so the finish fades in at the border. One Undo reverts the whole selection.** (number input): Auto-feather selection edges (px). 0 = off (hard edge). Any value softens the edge of the NEXT selection you commit (marquee / lasso / wand / pen / smart-fill), so...\n- **Edge Preview** (button): shows detected boundaries in red so you can adjust tolerance before clicking\n- **Spatial brush size** (slider): Spatial brush size\n- **Erase** (button): Erase spatial include/exclude strokes\n- **Erase** (button): Erase brush/wand/region strokes"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Selection / mask bar","k":"card","b":"Under the canvas: Include / Exclude brushes, Undo / Redo, Deselect, Invert, Grow / Shrink / Feather / Smooth, Copy / Mirror mask, Zoom to selection. Where: Pro > centre > selection / mask bar under the canvas.\n- **Include** (button): paint areas to KEEP in zone's color match (green overlay)\n- **Exclude** (button): paint areas to REMOVE from zone's color match (red overlay)\n- **Undo** (button): Undo last stroke (Ctrl+Z)\n- **Redo** (button): Redo last undone action (Ctrl+Y / Ctrl+Shift+Z)\n- **Deselect** (button): Clear selection for the current zone\n- **Invert** (button): Invert the current zone selection\n- **Spatial** (button): Clear spatial include/exclude for current zone\n- **Clear All** (button): Clear ALL drawn regions\n- **+ Grow** (button): Expand selection outward by 2px\n- **+1** (button): Expand selection by 1px\n- **Shrink** (button): Contract selection inward by 2px\n- **Contract selection by 1px** (button): Contract selection by 1px\n- **Fill** (button): Fill enclosed holes in selection\n- **Feather** (button): Soften selection edges (grow then shrink)\n- **Smooth** (button): Smooth jagged selection edges\n- **Copy** (button): Copy this zone's mask to another zone\n- **Mirror** (button): Mirror mask horizontally (flip leftright)\n- **Zoom** (button): Zoom viewport to fit current zone's selection"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Preview and spec channels (1 of 2)","k":"card","b":"LIVE PREVIEW of the render plus COMBINED / R METAL / G ROUGH / B COAT views of the spec map. Where: Pro > centre > spec channel strip under the preview.\n- **R METAL** (button): Red channel of the spec map: Metallic (brighter = more metal).\n- **G ROUGH** (button): Green channel: Roughness (darker = mirror, lighter = matte).\n- **B COAT** (button): Blue channel: Clearcoat (16 = max gloss, 255 = dull).\n- **Refresh** (button): Refresh preview (F5): aborts a stuck render and re-runs the live preview.\n- **Before After** (button): Before / After (B): compare the last preview with the current one.\n- **Spec Map Inspector** (button): Channels inspector: spec map channels with numeric values.\n- **COMBINED** (button): hover to enlarge, click for full view\n- **ALL** (button): Show all spec channels combined\n- **R Metal** (button): Metallic (0=dielectric, 255=full metallic)\n- **G Rough** (button): Roughness (0=mirror smooth, 255=fully matte)\n- **B Coat** (button): Clearcoat (16=max gloss, 255=dull)\n- **A Mask** (button): Specular Mask (rarely used, advanced control)\n- **PAINT** (button): View paint preview\n- **SPEC MAP** (button): View spec map preview\n- **Close lightbox** (button): Close lightbox (Esc)\n- **ALL** (button): Show all spec channels combined\n- **R Metal** (button): Metallic (0=dielectric, 255=metallic)\n- **G Rough** (button): Roughness (0=mirror, 255=matte)"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Preview and spec channels (2 of 2)","k":"card","b":"- **B Coat** (button): Clearcoat (16=max gloss, 255=dull)"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: RENDER and recipe card (1 of 2)","k":"card","b":"RENDER makes the finished paint + spec TGAs; the recipe card afterwards offers Copy Card, Save Card PNG, Share Recipe, Copy TP Desc, Save to keep, Deploy. Where: Pro > centre > RENDER button.\n- **RENDER** (button): RENDER (Ctrl+R): builds the finished paint TGA and the spec TGA and writes them to the iRacing car folder. Watch out: It will not start if the paint, customer ID or car folder is missing, or template layers are still on.\n- **Copy Card** (button): Copies the recipe card picture to the clipboard (paste into Discord).\n- **Share Recipe** (button): Downloads this look as a .shokkerrecipe file with preview.\n- **Save to keep** (button): Copies this render to a subfolder so the next render does not overwrite it.\n- **Deploy Car Select** (dropdown): Pick another iRacing car to also copy this render to.\n- **Deploy Now** (button): Copies this render to the chosen car's iRacing folder.\n- **Save Card PNG** (button): Save this recipe card as a PNG image file\n- **Copy TP Desc** (button): copy Trading Paints description (zone finishes, colors) to clipboard\n- **Recent renders** (button): recall one of the last 10 saved renders and restore its full recipe\n- **Deploy to a different car** (button): This render is already in the active car's iRacing folder (Live Link). Open this to also copy it into a different car's folder."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: RENDER and recipe card (2 of 2)","k":"card","b":"- **Close render statistics** (button): Close render stats panel"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Right column","k":"card","b":"Tabs: FINISHES (library) and LAYERS (PSD layers). Where: Pro > right column.\n- **FINISHES** (tab): FINISHES tab: opens the full-screen finish library.\n- **LAYERS** (tab): LAYERS tab: PSD layer list.\n- **Collapse arrow (right column)** (button): Collapses or expands the FINISHES / LAYERS column."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: LAYERS tab (1 of 3)","k":"card","b":"The layer list of a PSD / XCF / ORA: eye, name, opacity, blend, lock, ... plus Open Layered, + Layer, Actions, filter box. Where: Pro > right column > LAYERS tab.\n- **Open Layered** (button): Import a layered PSD / XCF / ORA with its layer tree.\n- **+ Layer** (button): + Layer: adds a PNG / JPG / WebP / GIF as a NEW image layer on top (a logo, a sponsor). Watch out: Dropping a file on the canvas instead REPLACES the paint.\n- **Actions** (button): Actions: + Blank layer, Flatten document, Merge visible, Photoshop round-trip, Thumbnail size. Watch out: Flatten discards layer separation.\n- **e.g. DLM438-base-001** (text input): Name for the exported car file in the Photoshop round trip.\n- **Path to export folder...** (text input): Folder shared with Photoshop for the round trip.\n- **Export** (button): Exports layers to the exchange folder for Photoshop editing; bring the TGA back afterwards.\n- **Clear All** (button): Clears all layer effects (Layer Effects dialog).\n- **Apply** (button): Applies the layer effects.\n- **Layer eye icon** (toggle): Shows / hides the layer. Alt+click isolates that layer. Watch out: Leaving Mask / Wire / Car_Mandatory on paints them into the car.\n- **Layer opacity** (slider): Fades the layer 0-100% (drag, or type an exact number)."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: LAYERS tab (2 of 3)","k":"card","b":"- **Layer blend mode** (dropdown): How the layer mixes with those below (Normal, Multiply, Screen, Overlay ...).\n- **Layer lock** (toggle): Locks the layer so it cannot be painted or changed. Watch out: The Shokker AI cannot edit locked layers - unlock first.\n- **Create a zone restricted to this layer** (button): One click makes a zone that only covers this layer's pixels; then give it a finish.\n- **Lock the active zone to this layer (Ctrl+L)** (button): Restricts the currently selected zone to this layer.\n- **Rename / duplicate / delete / merge / flip / rotate / effects icons** (button): Standard layer housekeeping: rename, duplicate (Shift = offset copy), delete, merge into the layer below, flip, rotate 90 degrees, Layer Effects (drop shadow, glow,... Watch out: Delete removes the layer art from the document; use the eye to just hide it.\n- **Filter layers box** (text input): Type part of a layer name or group to narrow a long list; Escape clears. Watch out: There is no sort-by-colour: the list is in PSD order. To work BY COLOUR use a zone with PICK COLOR FROM CAR.\n- **Layer name (click) / Ctrl+click / double-click** (button): Click selects the layer; Ctrl+click moves it on the canvas; double-click opens Layer Effects.\n- **+ Blank layer** (button): Add a blank transparent layer to paint on with the Retouch brushes"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: LAYERS tab (3 of 3)","k":"card","b":"- **Flatten document** (button): hidden Layers and Zone links are disclosed before removal\n- **Merge visible** (button): Ctrl+Shift+E\n- **Photoshop round-trip** (button): Export layers for Photoshop editing and bring the TGA back (round trip)\n- **Thumbnail size** (button): Cycle layer thumbnail size (small / medium / large)\n- **Layers filter box** (search box): Escape clears\n- **Cancel layer effects dialog** (button): Cancel (Esc)"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: FINISHES library","k":"card","b":"Full-screen browser of the whole catalogue (about 4,800 looks) with search, filters and favourites. Where: Pro > FINISHES library (full-screen).\n- **Finish library search box** (text input): Search the finish library by name, description or #tag. Watch out: Try plain words (\"gold chrome\") or hashtags (#carbon).\n- **Toggle favorites-only filter** (button): filter to starred finishes\n- **Library** (button): close fine tuning panel\n- **Automatically collapse other sections when opening a new one** (toggle): Automatically collapse other sections when opening a new one"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Base Material picker","k":"card","b":"Popup opened from a zone BASE section: search, #hashtag chips (#carbon, #chrome ...), On-Car Stage, Surprise me, See on paint, Color Lock. Where: Pro > zone editor > Base Material picker (popup).\n- **Color: AUTO** (button): Color Lock: when ON, picking a finish keeps your current colour instead of adopting the finish's default.\n- **Finish picker search box** (text input): Search finishes in the base picker by name, idea or #tag.\n- **Surprise me** (button): Surprise me: rolls a high-ranked finish onto the On-Car Stage; confirm with Enter / click.\n- **See on paint** (button): See on paint: previews the selected finish on your paint file.\n- **Clear search** (button): Clears the search so the whole list shows again.\n- **USE IT** (button): USE IT: applies the previewed finish to this zone.\n- **Preview on paint** (button): Applies the preview of the selected finish on your paint.\n- **Internal picker review queue** (button): Internal picker review queue\n- **Internal picker category planning** (button): Internal picker category planning\n- **\u2039 ON-CAR STAGE** (button): Show on-car preview"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Spec Tools (1 of 3)","k":"card","b":"Decal Rescue Kit, Lighting Mask, Material Sampler (read M/R/CC of any pixel), Range Remapper. For spec-map fixing. Where: Pro > Spec Tools > Material Sampler.\n- **Point reads the exact UV pixel; local median rejects isolated flake and texture outliers** (dropdown): Sample size for the Material Sampler: exact pixel or local median.\n- **Copy M/R/CC/A** (button): Copies the M / R / CC / A values you sampled.\n- **Select Connected** (button): Selects the connected area with the same material values.\n- **Select All Similar** (button): Selects every pixel with similar material values.\n- **Apply to Active Zone** (button): Gives the active zone the sampled material values.\n- **Clear Zone Override** (button): Removes the sampled override from the zone.\n- **Flat Vinyl Neutralizes chrome or candy beneath numbers and sponsor stamps. M 0 R 100 CC 110** (button): Flat vinyl spec under numbers / sponsors: neutralises chrome or candy beneath.\n- **Satin Decal Keeps printed vinyl readable with a controlled soft sheen. M 0 R 100 CC 75** (button): Satin decal spec: keeps printed vinyl readable.\n- **Gloss Decal Adds clean printed gloss without metallic contamination. M 0 R 42 CC 22** (button): Gloss decal spec: clean printed gloss."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Spec Tools (2 of 3)","k":"card","b":"- **Use Source Alpha Remove SPB's override and preserve the finish or imported map. AUTO** (button): Lighting mask: use the source file's alpha, removing Shokker's override.\n- **Full Lighting Force normal lighting and reflections in the selected footprint. A 255** (button): Lighting mask: force normal lighting.\n- **Reduced Lighting Half-strength response for recessed vents and deep seams. A 128** (button): Lighting mask: half-strength lighting response.\n- **Kill Lighting Suppress spec and environment light for cutout geometry. A 0** (button): Lighting mask: suppress spec and environment (fake a hole or dead-dark vent).\n- **Original** (button): Range Remapper preset: original values.\n- **Metallic Texture** (button): Range Remapper preset: metallic texture.\n- **Printed Vinyl** (button): Range Remapper preset: printed vinyl.\n- **Matte Texture** (button): Range Remapper preset: matte texture.\n- **Gloss Texture** (button): Range Remapper preset: gloss texture.\n- **Range Remapper: MLow** (number input): Metallic range low end (0-255).\n- **Range Remapper: MHigh** (number input): Metallic range high end.\n- **Range Remapper: RLow** (number input): Roughness range low end.\n- **Range Remapper: RHigh** (number input): Roughness range high end.\n- **Range Remapper: CCLow** (number input): Clearcoat range low end."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Spec Tools (3 of 3)","k":"card","b":"- **Range Remapper: CCHigh** (number input): Clearcoat range high end.\n- **Restore Original** (button): Puts the zone's original spec ranges back.\n- **Apply Remap** (button): Applies the remapped ranges to the active zone.\n- **ALL** (button): Show all four spec map channels combined\n- **R Metallic** (button): Red channel: Metallic (0=dielectric, 255=full metallic)\n- **G Roughness** (button): Green channel: Roughness (0=mirror smooth, 255=fully matte)\n- **B Clearcoat** (button): Blue channel: Clearcoat (16=max gloss, 255=dull, 0-15=none)\n- **A Mask** (button): Alpha channel: Specular mask (rarely used, advanced control)\n- **Maximum allowed difference in each M/R/CC/A channel; 0 selects exact matches** (slider): Maximum allowed difference in each M/R/CC/A channel; 0 selects exact matches"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: Undo History","k":"card","b":"List of recent actions with Undo / Redo / Clear. Where: Pro > Undo History panel.\n- **Undo** (button): Undo last action (Ctrl+Z)\n- **Redo** (button): Redo last action (Ctrl+Y / Ctrl+Shift+Z)\n- **Clear** (button): Clear all history (cannot be undone)"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: SHOKK files (1 of 2)","k":"card","b":"Save or load a whole session (zones + finishes, optionally the paint) as a .shokk file. Where: Pro > ZONES > More > LOAD SHOKK FILE.\n- **Close SHOKK Library** (button): Closes the SHOKK library.\n- **e.g. Purple Color Shift v1** (text input): Name for the .shokk file.\n- **Your name or username (optional)** (text input): Your name (optional) stored in the file.\n- **Short description of this paint recipe (e.g. 'Holographic chrome with red flake highlights \u2014 works great on dark cars')...** (text input): Short description of the recipe.\n- **Search by name, author, or tag...** (text input): Filter SHOKK files by name, author, or tag\n- **Open Selected** (button): Open the selected SHOKK file\n- **Channel PNG Export** (button): extracts selected SHOKK paint/spec into PNG inspection files. This does not create final iRacing TGAs.\n- **Path to PS export folder...** (text input): folder where paint_base.png, spec_full.png, and separated channel PNGs are written\n- **Browse** (button): Choose folder in File Explorer\n- **Folder** (button): Open the SHOKK Library folder in Explorer\n- **Save SHOKK** (button): Save current session as a .shokk file\n- **Include the paint TGA in the .shokker preset file for full portability** (toggle): Include the paint TGA in the .shokker preset file for full portability"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro: SHOKK files (2 of 2)","k":"card","b":"- **Save SHOKK** (button): Save the current zones, finishes, and (optionally) paint to a .shokk file"},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro / Chat: Shokker AI panel (1 of 2)","k":"card","b":"The \"AI\" button (bottom right) opens the copilot: type what you want, it changes zones; each answer has Undo. Gear = key, model, Claude / ChatGPT connection. Where: Pro / Chat > Shokker AI panel.\n- **AI button (bottom right)** (button): Opens the Shokker AI panel (the copilot).\n- **Shokker AI panel** (panel): Chat window: type what you want, the copilot changes zones and layers. Works with no key for common requests (colours, matte / gloss / chrome, stripes, spec looks). Watch out: It cannot import files, export, or hand-paint; it can only tell the buyer where to click.\n- **Tell me what you want... box** (text input): Type your request; Enter sends, Shift+Enter adds a line.\n- **Attach a picture** (button): Attach a livery you like, a logo or a flag; the AI can copy its design or colours (needs an AI key). Watch out: Cheap models cannot read UV sheets; results may need correcting.\n- **Undo (under each answer)** (button): Puts everything back the way it was before that answer (all zones and layer changes of that answer).\n- **Another take / Refine / Ask the AI** (button): Another try with a different idea; Refine looks at the preview and fixes what is off; Ask the AI undoes and lets the AI have a go."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Pro / Chat: Shokker AI panel (2 of 2)","k":"card","b":"- **Gear (key, model, daily cap, Claude / ChatGPT connection)** (button): Settings: your OpenRouter key and model (one model only), a daily spending cap, and \"Let an AI assistant (Claude or ChatGPT/Codex) control Shokker Paint Booth\" with... Watch out: The gear MODEL only applies to the in-app copilot; Claude Desktop uses its own model. Use Take over in SPB...\n- **Use Claude Desktop through MCP** (toggle): Install Shokker into Claude Desktop, then ask Claude \"Using Shokker Paint Booth, give me a Gulf-style livery\". Changes appear in the AI panel with Undo. Watch out: Restart Claude Desktop after installing; Shokker must be open.\n- **Connect ChatGPT / Codex** (toggle): Add SPB to Codex settings, restart Codex and sign in with ChatGPT. Watch out: Your subscription limits apply."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Chat: Chat mode","k":"card","b":"Pro screen plus the AI copilot opened for talking; same zones, same Undo. Where: Chat > Chat mode."},{"t":"Where everything is: the app map (AI knowledge card, generated from scripts/ai_atlas/ui_map.json) > Retired controls (not in this build)","k":"card","b":"Fleet mode and Season mode are retired in this booth build: the panel stays hidden, nothing opens it, and the buttons only show a \"disabled\" message. Do not send a buyer to them. Render one car at a time with the normal RENDER button.\n- **Add Car, Add Race, Quick: Wear Ramp, Render All Cars, Render All Races** (retired buttons): they cannot be clicked. For a worn look pick a worn Base Material and lower Base Strength (see the Wear article)."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I load my paint file (a flat TGA, PNG or JPEG)?","k":"card","b":"[hdi.load_flat | pro | needs: none | ui: paintFile, pro.header.tga_png_jpeg, pro.center.load_tga]\nAlso asked as: where do i load my paint; how to import tga; my paint wont load; how do i start\n1. Top row, find SOURCE PAINT. Click the \"TGA/PNG/JPEG\" button beside it (or on the empty canvas click \"Load TGA\" / \"Load Paint Image\").\n2. Pick your paint file in the window that opens, then confirm.\n3. Wait for the paint to appear in the SOURCE picture in the middle; the LIVE PREVIEW fills in next.\n4. You can also paste the full file path into the Source Paint box and press Enter.\nA flat TGA has no layers. Dropping a picture onto the canvas also loads it as the whole paint, it does not add a logo."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I load a layered PSD template (so I get layers)?","k":"card","b":"[hdi.load_psd | pro | needs: none | ui: pro.header.psd_xcf_ora, onboardingImportPsdBtn, pro.layers.open_layered]\nAlso asked as: how do i open a psd; where do i load my paint; my paint wont load; wheres my layres\n1. Top row, SOURCE PAINT, click the \"PSD/XCF/ORA\" button (or \"Import PSD\" on the empty canvas, or the LAYERS tab > \"Open Layered\").\n2. Choose your PSD (XCF and ORA also work) and confirm.\n3. Wait while the layers load, then open the LAYERS tab on the right to see them.\n4. Before rendering, switch the template layers (Mask, Wire, Car_Mandatory) OFF with their eye icons."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I start from a blank canvas with no paint file?","k":"card","b":"[hdi.blank_canvas | pro | needs: none | ui: pro.center.blank_canvas]\n1. On the empty centre canvas click \"Blank Canvas\".\n2. You get a plain white canvas to build colours on with zones and finishes.\n3. Set the iRacing customer ID and car folder at the top before you render."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I switch between PRO and CHAT?","k":"card","b":"[hdi.switch_mode | any | needs: none | ui: spbModeProBtn, spbModeChatBtn]\n1. At the top find the pill with PRO and CHAT.\n2. Click the one you want. Your paint and zones stay open.\nPro = every control. Chat = type what you want."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I make a zone?","k":"card","b":"[hdi.make_zone | pro | needs: paint | ui: pro.zones.add_zone, zone.section_color, zone.base_material]\nAlso asked as: how do i make a zone; what is a zone\n1. In the left ZONES column click \"+ Add Zone\". The new zone goes to the top and opens in the ZONE POPOUT PANEL.\n2. In COLOR choose which pixels it covers: \"PICK COLOR FROM CAR\" then click the car, or tick a layer under RESTRICT TO LAYERS.\n3. In BASE click Base Material and choose a finish.\n4. Watch the LIVE PREVIEW. A zone needs BOTH an area (colour, layer or box) and a finish."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I put a finish on just one part of the car (the hood, the roof, one side)?","k":"card","b":"[hdi.finish_one_part | pro | needs: paint, zone | ui: pro.zones.add_zone, zone.draw_box, zone.base_material]\nAlso asked as: how do I make just the hood different; make the roof black\n1. Click \"+ Add Zone\".\n2. In the ZONE POPOUT PANEL find APPLY AREA and click \"Draw box\".\n3. Drag a box on the paint around that panel (the sheet is flat: hood, roof and sides are separate rectangles).\n4. Under BASE click Base Material and pick the finish.\nFaster: in Chat or the AI panel just say \"make the hood chrome\" if the car's parts are known."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I change only one colour of my livery (say all the red)?","k":"card","b":"[hdi.change_one_colour | pro | needs: paint | ui: zone.pick_color_from_car, zone.base_color_mode]\nAlso asked as: how do i do a two tone; how do i select just the red\n1. Click \"+ Add Zone\".\n2. In COLOR click \"PICK COLOR FROM CAR\", then click a red spot on the car. Raise the tolerance if red edges are left.\n3. In BASE pick a finish.\n4. To make it a different colour set the BASE COLOR dropdown to \"Use solid color\" and choose the colour."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I select a colour so a zone only affects that colour?","k":"card","b":"[hdi.select_by_colour | pro | needs: zone, paint | ui: zone.pick_color_from_car, zone.tolerance, vtModeEyedropper]\nAlso asked as: how do i select a color; how do i select just the red; the edges are left behind; it picked too much\n1. Select the zone, open COLOR.\n2. Click \"PICK COLOR FROM CAR\", then click the colour on the paint. A second click on another colour ADDS it.\n3. Adjust the tolerance sliders until the edges are clean (about 30-50 is normal).\nThe \"Remaining\" button instead catches everything no higher zone claims."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I sort or see my layers by colour?","k":"card","b":"[hdi.sort_layers_by_colour | pro | needs: psd | ui: layer.search, zone.pick_color_from_car]\nAlso asked as: can i sort by color\n1. The LAYERS tab lists layers in the PSD's own order; there is no sort-by-colour. Use the \"filter...\" box at the top of the list to find a layer by name.\n2. To work BY COLOUR instead: in Pro make a zone and use \"PICK COLOR FROM CAR\"."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I find one layer in a long PSD?","k":"card","b":"[hdi.find_layer | pro | needs: psd | ui: layer.search, rpTabLayers]\nAlso asked as: how do i find a layer; i have too many layers\n1. Open the LAYERS tab.\n2. Type part of the name in the \"filter...\" box (top right of the list); Escape clears it.\n3. Alt+click an eye icon to see only that layer."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I put a finish on the numbers?","k":"card","b":"[hdi.finish_numbers | pro | needs: paint | ui: zone.restrict_layers, layer.make_zone]\nAlso asked as: how do i do the numbers; make the numbers gold chrome; how do i make a finish only on the numbers layer; i cant find the numbers\n1. With a PSD: open the LAYERS tab and click the zone icon on the Numbers layer (it makes a zone limited to that layer). Then in BASE pick the finish.\n2. Or make a zone and tick \"Numbers\" under RESTRICT TO LAYERS.\n3. With a flat TGA: if the numbers are one clear colour, \"+ Add Zone\" > \"PICK COLOR FROM CAR\" and click a number.\nIf the colour is also used elsewhere add a box with APPLY AREA > \"Draw box\". Not every paint has numbers drawn (iRacing can stamp them)."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I recolour the numbers?","k":"card","b":"[hdi.recolour_numbers | pro | needs: paint | ui: zone.base_color_mode, zone.solid_color, pro.toolbar.color_replace]\nAlso asked as: make the numbers purple; how do i colour the numbres; how do i do the numbers\n1. Quickest: in the AI panel type \"numbers purple metallic\".\n2. In Pro make a zone for the numbers (see \"put a finish on the numbers\"), then in BASE set BASE COLOR to \"Use solid color\" and pick the colour.\n3. To change the actual pixels instead use ADJUST > \"Color Replace\" on the Numbers layer.\nSolid colour flattens finishes that bring their own colours; use Hue Shift for those."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I teach the app where the numbers are?","k":"card","b":"[hdi.teach_numbers | chat | needs: paint | ui: ai.panel, ai.input]\nAlso asked as: i cant find the numbers; the app doesnt know where my numbers are; there are no numbers on my paint\n1. Open the AI panel (the AI button bottom right) and ask for something on the numbers, e.g. \"make the numbers gold\".\n2. It shows the car and asks. If its guess is right press \"Yes, that is right\".\n3. If not press \"No, I will show you\", then draw a box around ONE number (a single one, not the whole panel). It finds the rest.\n4. If the paint has none press \"There are none on this paint\".\nIt remembers places for this car. Never draw around a big area."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I tell Shokker where the car's parts are (hood, roof, sides)?","k":"card","b":"[hdi.teach_parts | chat | needs: paint | ui: ai.panel]\nAlso asked as: how do i tell it where the hood is; it doesnt know my car; make the roof black\n1. Ask the AI panel for a part change (\"make the roof black\"). If it does not know the car it shows the sheet and asks.\n2. Draw a box around the part when asked (one part at a time) and say which part it is.\n3. It remembers the car's parts from then on. The gear drawer can save or load a car map."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I make a colour or finish \"pop\" on the car?","k":"card","b":"[hdi.make_pop | pro | needs: zone | ui: zone.auto_pop, zone.spec_sliders, zone.spec_preset]\nAlso asked as: it looks flat how do i make it pop; how do i make the colors pop; make it shinier\n1. Select the zone, open BASE > Spec Sliders.\n2. Click \"Auto-Pop\" (it nudges the spec toward glossy and metallic). Click again for more.\n3. Or choose a \"Spec preset...\" such as Track Flash or Wet Candy.\n4. Neighbouring areas in complementary colours help a finish read from far away."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I make the shine shinier without changing the colour (spec only)?","k":"card","b":"[hdi.spec_only_shine | pro | needs: zone | ui: zone.base_color_mode, zone.spec_sliders, zone.g_rough]\nAlso asked as: make it shinier; how do i keep my colors but change the shine; i want to change only the shine; how do i change just the spec; where is the shiny thing\n1. Select the zone that covers the area (or make one).\n2. In BASE choose a Foundation finish such as Chrome / Satin Chrome / Metallic / Pearl / Satin, and set the BASE COLOR dropdown to \"Use source paint (spec only)\".\n3. Or keep your finish and open Spec Sliders: lower \"G Rough\" and raise \"R Metal\" for shinier, or click \"Auto-Pop\".\n4. The colour preview may barely move; look at the spec channel views (R METAL, G ROUGH, B COAT) under the preview."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I make something matte (flat, no shine)?","k":"card","b":"[hdi.make_matte | pro | needs: zone | ui: zone.base_material, zone.g_rough]\nAlso asked as: how do i make it matte\n1. Select the zone, BASE > Base Material > Matte (or Flat Black for the deadest look).\n2. Keep your colour: BASE COLOR \"Use source paint (spec only)\".\n3. Or push \"G Rough\" up in Spec Sliders. Satin is the in-between."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I make something chrome?","k":"card","b":"[hdi.make_chrome | pro | needs: zone | ui: zone.base_material, zone.base_color_mode]\nAlso asked as: how do i make it chrome; how do i mak it chrome; metalic look\n1. Select the zone, BASE > Base Material > Chrome (mirror) or Satin Chrome (softer).\n2. Chrome repaints the zone silver. To keep your colours and only get the shine, use a Foundation chrome with \"Use source paint (spec only)\".\n3. In iRacing the paint under a metal part should be near white for chrome to read."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I change a finish's colour?","k":"card","b":"[hdi.finish_colour | pro | needs: zone | ui: zone.base_color_mode, zone.solid_color, zone.hue_shift]\nAlso asked as: change the color of the finish; how do i recolor a carbon finish; i picked pink and the camo turned flat; ugh the colors are all wrong\n1. In BASE look at the BASE COLOR dropdown.\n2. Plain finishes (gloss, matte, satin, candy, pearl, metallic) take a colour: choose \"Use solid color\" and pick it.\n3. Finishes that bring their own colours (carbon, camo, holographic, flames ...) keep their look: use \"Hue Shift\" (and Saturation / Brightness) instead.\nSolid colour on a brings-its-own-colours finish flattens it to one colour."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > Why is the colour not applying to my finish?","k":"card","b":"[hdi.colour_not_applying | pro | needs: zone | ui: zone.base_color_mode, zone.lock_base_color, zone.hue_shift]\nAlso asked as: why is the color not changing; i picked a color and it didnt apply; color wont apply; i picked pink and the camo turned flat; the pattern covers my color; ugh the colors are all wrong\n1. Check BASE COLOR. \"Use finish's own color\" ignores your colour; \"Use source paint (spec only)\" keeps the car's colour. Pick \"Use solid color\" to force one.\n2. Some finishes bring their own palette (camo, carbon, holographic). A solid colour on those makes one flat colour and loses the pattern: use Hue Shift to recolour them.\n3. A pattern in \"Overlay\" paint mode paints its own colours over yours: set Paint mode to \"Blend\" or use the pattern Hue slider.\n4. If colours keep changing when you change finish, switch ON the Lock beside Base Color (or Color Lock in the picker)."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I make a gradient (fade) between two colours?","k":"card","b":"[hdi.gradient | pro | needs: zone | ui: zone.base_color_mode, zone.gradient]\nAlso asked as: how do i make a gradient; fade from red to black\n1. Select the zone and in BASE set BASE COLOR to \"Custom gradient\".\n2. Set 2 colour stops (more for a sunset) and the direction.\n3. The fade runs across the flat sheet, so each side of the car may fade differently; use one zone per side to control it."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I crush a pattern finer (smaller texture)?","k":"card","b":"[hdi.pattern_finer | pro | needs: zone | ui: zone.pattern_scale, zone.base_scale]\nAlso asked as: the pattern is too big; make the pattern smaller; how do i crush the pattern finer; the texture looks huge; what does scale do; carbon looks too big\n1. Select the zone, open PATTERN.\n2. Drag \"Scale\" to the left (below 1.00x). Smaller means more repeats.\n3. For the base finish's own texture use \"Base Scale\" in BASE.\n4. On a whole car even normal-size patterns look big; 0.3x to 0.6x is typical for fine detail."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > What does the Base Scale slider do?","k":"card","b":"[hdi.what_base_scale | pro | needs: zone | ui: zone.base_scale, zone.spec_scale]\nAlso asked as: what does the base scale slider do; what does scale do; carbon looks too big; the texture looks huge\n1. It changes how big the finish's own texture (flake, weave, grain) is inside that zone, from 0.05x to 5.0x (1.00x is normal).\n2. Smaller = finer and more repeats; bigger = zoomed in.\n3. It does not change colours or resize the car. Spec Scale follows it until you tick Independent Spec."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I add a pattern (carbon, flames, camo ...)?","k":"card","b":"[hdi.add_pattern | pro | needs: zone | ui: zone.section_pattern, zone.pattern, zone.pattern_paint_mode]\nAlso asked as: how do i add a pattern; the pattern covers my color; how do i add flake\n1. Select the zone, open PATTERN.\n2. Click the pattern name box (shows \"None\") and choose a pattern.\n3. Set \"Paint mode\": \"Overlay\" = the pattern's own colours cover the paint; \"Blend\" = it keeps your colour.\n4. Use Opacity, Scale and Rotate to taste."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I remove a pattern?","k":"card","b":"[hdi.remove_pattern | pro | needs: zone | ui: zone.pattern]\nAlso asked as: how do i remove the pattern\n1. Select the zone, open PATTERN.\n2. Click the small x (\"Remove this pattern\") beside the pattern name."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I rotate a pattern?","k":"card","b":"[hdi.rotate_pattern | pro | needs: zone | ui: zone.pattern_rotation]\nAlso asked as: how do i rotate the pattern\n1. PATTERN > \"Rotate\" slider (0-359 degrees) or type the number in the box beside it.\n2. For the base finish texture use \"Base Rotation\" in BASE."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I move a pattern to a specific spot?","k":"card","b":"[hdi.move_pattern | pro | needs: zone | ui: zone.pattern_placement, zone.pattern_position]\nAlso asked as: move the pattern\n1. In PATTERN find \"Pattern placement\" and click \"Edit on Template\" to drag it by hand, or \"Fit to Zone\".\n2. For fine control open \"Advanced Pattern Control Panel\" and use Position X / Position Y, Flip H / Flip V."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I add a shiny texture without changing the colour (spec overlay)?","k":"card","b":"[hdi.spec_overlay | pro | needs: zone | ui: zone.section_spec_overlays, zone.add_spec_overlay]\nAlso asked as: what is an overlay\n1. Select the zone, open BASE > SPEC OVERLAYS.\n2. Click \"+ ADD SPEC OVERLAY\" and choose a texture (brushed, hammered, scratched ...).\n3. It changes shine and metal only. Check the R METAL / G ROUGH / B COAT views to see it."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I stack two finishes (second base)?","k":"card","b":"[hdi.second_base | pro | needs: zone | ui: zone.section_overlays, zone.second_base]\nAlso asked as: how do i layer two finishes; what is an overlay\n1. Select the zone, open OVERLAYS.\n2. Click the \"2nd Base\" box and pick a finish; use \"+ Add 3rd overlay\" for more (up to five layers).\n3. Each overlay has its own blend controls."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I make a finish less strong (blend it with my paint)?","k":"card","b":"[hdi.finish_less_strong | pro | needs: zone | ui: zone.base_strength, zone.spec_strength]\n1. BASE > \"Base Strength\": lower it. 0% = your original paint, 100% = full finish.\n2. \"Spec Strength\" does the same for the shine only."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I change the order or priority of zones?","k":"card","b":"[hdi.zone_order | pro | needs: zone | ui: zone.order, pro.zones]\n1. In the left ZONES column drag a zone card by its handle (the three-line icon).\n2. Top = highest priority; where two zones select the same pixels the higher one wins.\n3. A catch-all \"Remaining\" zone belongs at the bottom."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > Why is my zone not showing / doing anything?","k":"card","b":"[hdi.zone_not_showing | pro | needs: zone | ui: zone.order, zone.section_color, zone.base_material]\nAlso asked as: i made a zone and nothing happens; zone not working; my zone does nothing; why is my zone not showing; why wont it change\n1. Does it have an area (colour, layer, or box) AND a finish? The panel warns \"No color or region set yet\".\n2. Is a zone ABOVE it claiming the same pixels? Drag it higher.\n3. Is the colour tolerance too tight? Raise it.\n4. Is the zone muted (eye icon off) or limited to a hidden layer?\n5. Is the preview stale? Press the Refresh button or F5."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > Why is my preview not changing?","k":"card","b":"[hdi.preview_not_changing | pro | needs: paint | ui: btnPreviewRefresh, zone.order, zone.section_color]\nAlso asked as: why wont it change; why cant i see my changes; preview wont update; preveiw wont chnage; nothing works\n1. Press F5 (or the \"Refresh\" button beside the preview) to force it.\n2. Make sure the zone has an area and a finish, and nothing above it claims the same pixels.\n3. Spec-only changes (shine, metal, coat) hardly change the colour preview: look at R METAL / G ROUGH / B COAT.\n4. Make sure the view is not on SOURCE only: use SPLIT or CAR (buttons next to the zoom).\n5. If it says \"Preview failed - showing the LAST GOOD render\", click that bar; reopen the app if it persists."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > I loaded my paint and nothing happened. What now?","k":"card","b":"[hdi.loaded_nothing | pro | needs: paint | ui: paintFile, pro.zones.add_zone, btnRender]\nAlso asked as: i loaded my paint and nothing happened\n1. Loading only shows your paint. Nothing changes until you give a zone a finish.\n2. Click \"+ Add Zone\", pick a colour with \"PICK COLOR FROM CAR\", then choose a finish in BASE.\n3. Or switch to CHAT and just say what you want.\n4. Press RENDER at the end to write the files."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > What do I do first? (a complete beginner)","k":"card","b":"[hdi.what_now | any | needs: none | ui: spbGuideToggle, mode.chat]\nAlso asked as: this is confusing; what now; help; i dont get it; how do i start; i hate this i cant figure it out\n1. Load your paint: top row, SOURCE PAINT, \"TGA/PNG/JPEG\" (flat) or \"PSD/XCF/ORA\" (layers).\n2. Make zones in PRO, or switch to CHAT to type what you want.\n3. Pick looks, check the LIVE PREVIEW.\n4. Set your iRacing customer ID and car folder at the top, then press RENDER.\nPress \"Tutorial\" in the top bar for Training Wheels: quests that teach the app step by step."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I turn on the step-by-step tutorial (Training Wheels)?","k":"card","b":"[hdi.tutorial | pro | needs: none | ui: spbGuideToggle, trainingWheelsCheckbox]\nAlso asked as: how do i get a tutorial; this is confusing; i hate this i cant figure it out\n1. Click \"Tutorial\" in the top bar, or tick Training Wheels in Settings (the gear).\n2. Follow the quests: load, zone, finish, render, then patterns, spec, overlays.\n3. Click it again to turn it off."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > What are layers?","k":"card","b":"[hdi.what_are_layers | pro | needs: none | ui: rpTabLayers, pro.layers]\nAlso asked as: what are layers; wheres my layres\n1. A layered PSD keeps parts of the livery on separate sheets: Car Paint (body colours), Numbers, Sponsors, Tape, Decals.\n2. Layers let you change one thing (just the numbers) without touching the rest.\n3. Template layers (Mask, Wire, Car_Mandatory) only show the car outlines and must be OFF when you render.\n4. A flat TGA has no layers. Load a PSD (\"PSD/XCF/ORA\") to get them; see the LAYERS tab on the right."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I turn a layer on or off?","k":"card","b":"[hdi.layer_visibility | pro | needs: psd | ui: layer.eye]\nAlso asked as: how do i hide a layer\n1. Open the LAYERS tab.\n2. Click the eye icon on the layer. Alt+click shows only that layer."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I switch off the template lines (Mask, Wire, Car_Mandatory) before exporting?","k":"card","b":"[hdi.template_layers_off | pro | needs: psd | ui: layer.eye]\nAlso asked as: there are lines all over my car; i see the wireframe on my paint; how do i turn off mask and wire\n1. LAYERS tab: click the eye on Car_Mandatory, Mask and Wire (the group \"Turn Off Before Exporting TGA\").\n2. Then render. If lines still show on the car, one of them was left on."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I add a logo or sponsor picture?","k":"card","b":"[hdi.add_logo | pro | needs: paint | ui: pro.layers.layer, layer.rename]\nAlso asked as: i dropped a picture on the canvas and it replaced everything; how do i add a logo; how do i add my sponsor\n1. Open the LAYERS tab and click \"+ Layer\".\n2. Choose a PNG / JPG / WebP / GIF (transparent PNG is best).\n3. Drag it with Move (V) in LAYER mode, or use Transform (Ctrl+T) to size it.\nDo not drop it onto the canvas: that REPLACES the whole paint."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I move or resize a number or logo?","k":"card","b":"[hdi.move_logo | pro | needs: psd | ui: btnToolbarModeLayer, vtModeLayerMove, vtModeLayerTransform]\nAlso asked as: how do i move a layer; how do i move the numbers; how do i resize a logo\n1. Click LAYER in the ZONE | LAYER switch (top toolbar).\n2. Pick Move (V), click the number / logo (it isolates it), drag.\n3. Use Transform (Ctrl+T) for size and rotation; \"Apply\" confirms."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I change a layer's opacity or blend mode?","k":"card","b":"[hdi.layer_opacity | pro | needs: psd | ui: layer.opacity, layer.blend]\nAlso asked as: how do i change layer opacity\n1. LAYERS tab, find the layer row.\n2. Drag its opacity slider (or type a value), and use the blend dropdown (Normal, Multiply, Screen, Overlay ...)."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I delete or duplicate a layer?","k":"card","b":"[hdi.layer_delete | pro | needs: psd | ui: layer.rename]\nAlso asked as: how do i delete a layer\n1. LAYERS tab, use the layer's duplicate (Shift = offset copy) or delete icon.\n2. Deleting removes the art; use the eye icon if you only want it hidden. Ctrl+Z undoes."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I merge or flatten layers?","k":"card","b":"[hdi.merge_flatten | pro | needs: psd | ui: layerActionsMenuBtn]\nAlso asked as: how do i merge layers\n1. LAYERS tab > \"Actions\".\n2. \"Merge visible\" combines the visible layers (hidden ones survive); \"Flatten document\" makes one layer and loses separation."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I paint on a layer by hand?","k":"card","b":"[hdi.paint_on_layer | pro | needs: psd | ui: btnToolbarModeLayer, vtModeBrush, vtModeColorBrush]\nAlso asked as: how do i paint on a layer\n1. Click LAYER in the ZONE | LAYER switch.\n2. Pick Brush (B) and set size / opacity in the options bar (or open RETOUCH for Color Brush, Recolor, Smudge).\n3. For a fresh blank layer: LAYERS tab > Actions > \"+ Blank layer\"."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I make a zone follow one layer (restrict to a layer)?","k":"card","b":"[hdi.restrict_to_layer | pro | needs: psd, zone | ui: zone.restrict_layers, layer.make_zone, layer.lock_zone]\nAlso asked as: how do i make a finish only on the numbers layer\n1. Select the zone, COLOR section > RESTRICT TO LAYERS, tick the layer(s).\n2. Or press the zone icon on a layer row to make a new zone limited to it, or Ctrl+L to lock the active zone to the selected layer.\nChoose only paintable layers (Car Paint, Sponsors, Numbers ...), not Mask or Wire."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I keep sponsors and numbers untouched when I change the body?","k":"card","b":"[hdi.protect_sponsors | pro | needs: psd | ui: zone.restrict_layers]\nAlso asked as: only change the body not the sponsors; how do i leave the numbers alone\n1. Make a zone for the body and tick only \"Car Paint\" under RESTRICT TO LAYERS.\n2. Or in Chat say \"change the body but leave the numbers alone\"."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I undo?","k":"card","b":"[hdi.undo | pro | needs: paint | ui: pro.toolbar.undo_ctrl_z, pro.toolbar.undo_history, ai.undo]\nAlso asked as: undo; how do i undo; i messed up; put it back; how do i go back several steps; i dropped a picture on the canvas and it replaced everything\n1. Press Ctrl+Z, or the Undo button in the top toolbar (HISTORY menu).\n2. To go back several steps open \"Undo History...\".\n3. Under an AI panel answer press Undo to take back that whole answer.\nCtrl+Y or Ctrl+Shift+Z redoes."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I start over completely?","k":"card","b":"[hdi.start_over | pro | needs: paint | ui: pro.zones.reset_all_zones]\nAlso asked as: i want to start over; i messed up\n1. Pro: left ZONES column > \"Reset All Zones\" (undoable, resets to the default zones).\n2. One zone only: \"Reset Zone\" at the top of its panel."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I export my paint to iRacing?","k":"card","b":"[hdi.export_iracing | pro | needs: paint, car_folder | ui: iracingId, outputDir, btnRender]\nAlso asked as: how do i export; how do i get it into iracing; where does the file go; where is the render button; how doo i exprot; how do i save\n1. Top row: enter your iRacing customer number (IRACING USER ID) and set IRACING CAR FOLDER (use the car list button or browse).\n2. Turn the template layers (Mask, Wire, Car_Mandatory) OFF.\n3. Click RENDER (Ctrl+R). The paint and spec files are written to the car folder.\n4. In iRacing press Alt+Tab, then Ctrl+R to reload paints."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I get Shokker to write straight into my iRacing folder every time?","k":"card","b":"[hdi.live_link | pro | needs: car_folder | ui: outputDir, liveLinkCheckbox]\n1. Set IRACING CAR FOLDER at the top: that alone copies every render there.\n2. Settings (gear) > \"Auto-deploy\" only matters when the car folder is empty."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I choose my iRacing car?","k":"card","b":"[hdi.pick_car | pro | needs: none | ui: carPickBtn, outputDir]\nAlso asked as: which car folder do i pick; how do i pick my car; where does the file go\n1. Top row, click the car-list button beside IRACING CAR FOLDER (\"Pick detected iRacing car\").\n2. Choose your car (most recently painted first), or use the browse button."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > What is my iRacing customer ID and where do I put it?","k":"card","b":"[hdi.customer_id | pro | needs: none | ui: iracingId]\nAlso asked as: what is my customer id; what do i put in the iracing user id box\n1. It is your iRacing member number (4-7 digits), shown in your iRacing account.\n2. Type it in IRACING USER ID at the top. It is part of the saved file names; a wrong one means iRacing shows nothing."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > What is the difference between Custom Number and Sim-Stamped Number?","k":"card","b":"[hdi.number_type | pro | needs: none | ui: useCustomNumberCheckbox, useSimStampedCheckbox]\nAlso asked as: what is custom number vs sim stamped\n1. Custom Number: the number is part of your paint (files car_num_ID.tga); iRacing adds none. Needs Hide Car Numbers ON in iRacing.\n2. Sim-Stamped Number: iRacing stamps the number in the series font (files car_ID.tga). Do not also paint a number.\n3. Switch at the top (CUSTOM NUMBER / SIM-STAMPED NUMBER)."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > Why doesn't my paint show in iRacing?","k":"card","b":"[hdi.not_in_iracing | pro | needs: render, car_folder | ui: iracingId, outputDir, useCustomNumberCheckbox]\nAlso asked as: my paint doesnt show in iracing; i rendered but its not in the sim; iracing shows the old paint\n1. Check the customer ID is right.\n2. Check CUSTOM / SIM-STAMPED matches iRacing's Hide Car Numbers setting.\n3. Check IRACING CAR FOLDER is the exact car folder.\n4. Render again, then Alt+Tab and press Ctrl+R in iRacing.\n5. Make sure the template layers were off and the file is a 2048 TGA."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I get my paint to look the same in iRacing as in Shokker?","k":"card","b":"[hdi.look_differs | pro | needs: render | ui: btnRender]\nAlso asked as: the chrome looks dark in iracing; looks different in iracing; iracing shows the old paint\n1. Remember the preview is a quick flat view; iRacing adds sun, shadow and its own stamps.\n2. Chrome needs light paint under it and strong metal in the spec map.\n3. Reload with Ctrl+R in iRacing; if the shine looks old move the old car_spec .mip file away."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > What is a spec map?","k":"card","b":"[hdi.what_is_spec | pro | needs: none | ui: pro.preview, btnSpecMapInspector]\nAlso asked as: what is a spec map; what does spec mean; what is R G B coat; spek map\n1. It is a second picture iRacing reads to know how shiny each pixel is.\n2. Red = metal (255 = metal), Green = roughness (0 = mirror, 255 = matte), Blue = clearcoat (16 = best gloss, 255 = dull).\n3. You see it under the preview as COMBINED, R METAL, G ROUGH, B COAT. RENDER writes both the paint and the spec file."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > Where are the spec sliders?","k":"card","b":"[hdi.where_spec_sliders | pro | needs: zone | ui: zone.spec_sliders, zone.r_metal, zone.g_rough, zone.b_coat]\nAlso asked as: where is the shiny thing; where are the spec sliders; where is metal rough coat\n1. Click a zone card in the left column to open the ZONE POPOUT PANEL.\n2. Open the BASE section and scroll to \"Spec Sliders\": R Metal, G Rough, B Coat.\n3. Strength of the whole spec is \"Spec Strength\" higher up in BASE."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I see the spec map?","k":"card","b":"[hdi.see_spec | pro | needs: paint | ui: pro.preview.r_metal, btnSpecMapInspector, btnSpecMapInspectorSource]\nAlso asked as: how do i see the spec\n1. Under the LIVE PREVIEW click COMBINED, R METAL, G ROUGH or B COAT.\n2. Click one to open it larger, or use \"Channels\" for exact numbers."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I read the exact metal / rough / coat of a spot?","k":"card","b":"[hdi.read_spec_value | pro | needs: render | ui: pro.toolbar.material_sampler]\nAlso asked as: how do i read the exact metal value\n1. Top toolbar > SPEC TOOLS > \"Material Sampler...\".\n2. Click a spot on the spec map: M / R / CC values appear; \"Apply to Active Zone\" copies them to the zone."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I make numbers and sponsors read cleanly under chrome or candy?","k":"card","b":"[hdi.decal_rescue | pro | needs: paint | ui: pro.toolbar.decal_rescue_kit]\nAlso asked as: sponsors look weird under chrome; my numbers look sparkly\n1. Top toolbar > SPEC TOOLS > \"Decal Rescue Kit...\".\n2. Choose Flat Vinyl, Satin Decal or Gloss Decal. It puts a plain non-metal spec under stamped numbers and sponsors."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I make fake grille holes or vents (lighting mask)?","k":"card","b":"[hdi.lighting_mask | pro | needs: paint | ui: pro.toolbar.lighting_mask]\nAlso asked as: how do i make a vent\n1. Top toolbar > SPEC TOOLS > \"Lighting Mask...\".\n2. Choose Use Source Alpha, Full Lighting, Reduced Lighting or Kill Lighting for the area."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I pick or change a finish for a zone?","k":"card","b":"[hdi.pick_finish | pro | needs: zone | ui: zone.base_material, swatchSearchInput, swatchStageUseBtn]\nAlso asked as: how do i add flake; how do i pick a finish; where are the finishes; metalic look; how do i search for a finish; i dont know what finish to use\n1. Select the zone, BASE > click the Base Material box.\n2. Search by name or idea (try \"gold chrome\" or #carbon), or tap a #tag chip.\n3. Preview on the On-Car Stage, then press \"USE IT\". \"Surprise me\" rolls a random good one."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I search the whole finish library?","k":"card","b":"[hdi.search_finishes | pro | needs: none | ui: rpTabFinishes, finishSearch, fbSearch]\nAlso asked as: how do i search for a finish; where are the finishes\n1. Click the FINISHES tab on the right (full-screen library).\n2. Type in the search box: names, ideas (\"icy blue\"), or #tags; use the filters and the star for favourites."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I get ideas for a finish I can't name?","k":"card","b":"[hdi.finish_ideas | chat | needs: paint | ui: swatchDiceBtn, ai.panel]\nAlso asked as: i dont know what finish to use; give me ideas\n1. In the AI panel describe the feel (\"like a rainy city night, but glossier\") and it offers several real finishes with previews.\n2. Or open the Base Material picker and press \"Surprise me\"."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I apply a ready-made look (preset)?","k":"card","b":"[hdi.presets | pro | needs: paint | ui: pro.zones.more, pro.zones_more.presets_gallery]\nAlso asked as: are there presets\n1. Left column > \"More\" (three dots) > \"Presets Gallery\".\n2. Click a preset to apply it."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I give every zone the same finish?","k":"card","b":"[hdi.same_finish_all | pro | needs: zone | ui: pro.zones_more.apply_finish_to_all]\nAlso asked as: same finish on everything\n1. Pick the finish on one zone.\n2. Left column > More > \"Apply Finish to All\"."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I duplicate a zone?","k":"card","b":"[hdi.duplicate_zone | pro | needs: zone | ui: zone.mute]\nAlso asked as: how do i copy a zone\n1. On the zone card in the left column click the copy icon.\n2. Change the area or finish of the copy."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I hide a zone for a moment?","k":"card","b":"[hdi.hide_zone | pro | needs: zone | ui: zone.mute]\nAlso asked as: how do i hide a zone\n1. Click the eye icon on its card in the ZONES column. Click again to bring it back."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I delete a zone?","k":"card","b":"[hdi.delete_zone | pro | needs: zone | ui: zone.mute]\nAlso asked as: how do i delete a zone\n1. Click the x on the zone's card (Ctrl+Z undoes). The Chat copilot cannot delete zones."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I draw the exact area a zone covers (a box or lasso)?","k":"card","b":"[hdi.draw_area | pro | needs: zone, paint | ui: zone.draw_box, zone.lasso, zone.clear_area]\nAlso asked as: how do i draw a box; how do i use lasso\n1. In the zone's APPLY AREA click \"Draw box\" or \"Lasso\".\n2. Drag on the paint. \"Clear\" removes it, \"Activate\" turns it back on."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I use the magic wand or lasso to select an area?","k":"card","b":"[hdi.wand_select | pro | needs: paint | ui: vtModeWand, wandTolerance, useRegionBtn]\nAlso asked as: how do i use the magic wand; how do i use lasso\n1. Pick Wand (W) in the top toolbar (or Lasso L / Rect O). Click or drag on the paint.\n2. Shift adds, Alt subtracts; the Tolerance slider sets how similar colours must be.\n3. Select a zone in the left column and press \"Use Region\" to give it that selection."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I select a number or logo as a whole?","k":"card","b":"[hdi.grab_object | pro | needs: paint | ui: vtModeGrabObject, useRegionBtn]\nAlso asked as: how do i select a logo\n1. Top toolbar > SELECT menu > \"Grab Object\" (G).\n2. Click inside a solid part of the number; its outline is selected.\n3. Use \"Use Region\" on the zone you want."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I grow, shrink or soften a selection edge?","k":"card","b":"[hdi.mask_edges | pro | needs: zone | ui: pro.toolbar.grow_1_px, pro.toolbar.feather_2_px, pro.toolbar.smooth_edges]\nAlso asked as: how do i soften the edge\n1. Top toolbar > MASK menu: \"Grow 1 px / 2 px\", \"Shrink\", \"Fill Holes\", \"Feather 2 px\", \"Smooth Edges\", \"Invert Mask\".\n2. The same buttons sit in the bar under the canvas (Grow, Shrink, Feather, Smooth)."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I invert or copy a zone's area?","k":"card","b":"[hdi.mask_copy | pro | needs: zone | ui: pro.toolbar.invert_mask, pro.toolbar.copy_mask, pro.toolbar.mirror_mask]\n1. Top toolbar > MASK: \"Invert Mask\" swaps selected / unselected, \"Copy Mask\" copies it to another zone, \"Mirror Mask\" flips it left-right."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I remove one spot from a zone's colour match?","k":"card","b":"[hdi.exclude_region | pro | needs: zone | ui: vtModeSpatialExclude, vtModeSpatialInclude]\nAlso asked as: how do i exclude a spot\n1. Top toolbar > MASK > \"Exclude Region\", then paint over the bits to leave out (red overlay).\n2. \"Include Region\" paints bits to keep (green); \"Erase Spatial\" removes those strokes."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I zoom and move around the canvas?","k":"card","b":"[hdi.zoom | pro | needs: paint | ui: pro.center.fit, pro.center.1_1]\nAlso asked as: how do i zoom\n1. Buttons beside the canvas: zoom out, +, FIT (Ctrl+0), 1:1 (actual size).\n2. Ctrl+plus / Ctrl+minus also zoom."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I compare before and after?","k":"card","b":"[hdi.before_after | pro | needs: render | ui: btnBeforeAfter, btnCompare, btnSplitView]\nAlso asked as: how do i compare before and after\n1. Click \"B/A\" (or press B) to flip between the last preview and now.\n2. \"Compare\" gives a wipe slider; SPLIT shows source and preview side by side."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I see the car preview bigger?","k":"card","b":"[hdi.preview_bigger | pro | needs: paint | ui: btnPreviewRefresh, btnSourceFocus, btnSplitView]\n1. Click the preview picture to open it full size (PAINT / SPEC MAP)."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I save my project and come back later?","k":"card","b":"[hdi.save_project | pro | needs: paint | ui: spbProjectsButton, pro.zones_more.save_shokk]\nAlso asked as: how do i save; how do i save my project; how do i come back to this later\n1. Click \"Save / Open\" in the top toolbar (SPB Projects). It saves the paint (PSD included), every zone and layer settings in one file.\n2. To reopen, click \"Save / Open\" again and load it.\nThere is no File menu."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I share my finish setup with someone?","k":"card","b":"[hdi.share_recipe | pro | needs: render | ui: pro.render.share_recipe, pro.render.copy_card]\nAlso asked as: how do i share my paint recipe\n1. After RENDER the recipe card appears: \"Copy Card\" (paste into Discord), \"Save Card PNG\", \"Share Recipe\" (a .shokkerrecipe file) or \"Copy TP Desc\" (Trading Paints description).\n2. Others load it with \"Import Recipe\" in the top toolbar."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I load a recipe someone sent me?","k":"card","b":"[hdi.import_recipe | pro | needs: paint | ui: pro.toolbar.import_recipe]\nAlso asked as: how do i load a recipe\n1. Top toolbar > \"Import Recipe\".\n2. Choose the .shokkerrecipe file; its zones, colours and finishes are applied to your car."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I save a zone layout as a template?","k":"card","b":"[hdi.save_template | pro | needs: zone | ui: pro.zones_more.save_as_template, templateSelect]\nAlso asked as: how do i save a template\n1. Left column > More > \"Save as Template\", name it, Save.\n2. Load it later from the \"Load Template...\" dropdown in the same menu."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I go back to an earlier render?","k":"card","b":"[hdi.old_render | pro | needs: render | ui: pro.toolbar.render_history, pro.toolbar.recent, btnSaveToKeep]\nAlso asked as: go back to my old render\n1. Top toolbar > RENDER HISTORY > \"Recent\" or \"Gallery\", click a thumbnail to restore it with its full recipe.\n2. To keep one safe, press \"Save to keep\" on the recipe card."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I save a zip of my paint files?","k":"card","b":"[hdi.zip_export | pro | needs: render | ui: exportZipCheckbox]\n1. Settings (gear) > tick the ZIP option. Every render bundles the paint TGA, spec TGA and preview."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I export the spec channels as pictures (for Photoshop)?","k":"card","b":"[hdi.export_png_channels | pro | needs: render | ui: pro.zones_more.png_channels_export]\n1. Left column > More > \"PNG Channels Export\" (choose the export folder first).\n2. Or LAYERS tab > Actions > \"Photoshop round-trip\" to export layers and bring a TGA back."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I use the Chat mode / AI panel?","k":"card","b":"[hdi.use_chat | chat | needs: paint | ui: mode.chat, ai.panel, ai.input]\nAlso asked as: how do i use chat; how do i talk to the ai; what can the ai do; do i need an api key\n1. Click CHAT in the pill (or the AI button bottom right).\n2. Type what you want: \"make the hood matte black\", \"retro red white and blue stripes\", \"numbers gold chrome\". Enter sends.\n3. Each answer has an Undo button; \"Another take\" tries a different idea.\nIt works with no key for common requests; a key makes it smarter."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I talk to Claude about my paint through MCP?","k":"card","b":"[hdi.use_claude_mcp | pro | needs: paint | ui: mcp.claude, ai.gear]\nAlso asked as: how do i use claude with this; how do i use mcp\n1. Open the AI panel, press the gear, switch ON \"Let an AI assistant (Claude or ChatGPT/Codex) control Shokker Paint Booth\".\n2. Press \"Install in Claude Desktop\" and restart Claude Desktop.\n3. With Shokker open, ask Claude: \"Using Shokker Paint Booth, give me a Gulf-style livery\".\n4. Every change shows in the AI panel with an Undo button. No API key needed; your Claude plan is used."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I use ChatGPT / Codex with Shokker?","k":"card","b":"[hdi.use_chatgpt | pro | needs: paint | ui: mcp.chatgpt, ai.gear]\nAlso asked as: how do i connect chatgpt; how do i use mcp\n1. AI panel > gear > bridge settings > \"Connect ChatGPT / Codex\", review, then \"Add SPB to Codex settings\".\n2. Restart Codex, sign in with ChatGPT, choose a model, chat with Shokker open.\n3. Use \"Take over in SPB\" before asking the in-app copilot while an outside assistant has control."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I give the in-app copilot an AI key (and which model)?","k":"card","b":"[hdi.ai_key | chat | needs: none | ui: ai.gear]\nAlso asked as: do i need an api key\n1. AI panel > gear.\n2. Paste your OpenRouter key and pick the one model offered (DeepSeek v4.1 Flash is recommended). A daily cap protects your spend.\n3. Without a key the built-in designer still handles common requests."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > What can the AI copilot NOT do?","k":"card","b":"[hdi.ai_limits | chat | needs: none | ui: ai.panel]\nAlso asked as: what can the ai do; the ai cant do what i asked\n1. It cannot delete zones, open or save files, import a paint, export to iRacing, or hand-paint.\n2. It can tell you the exact buttons to click. Every change it makes has an Undo."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I make a livery from a description (retro stripes, Gulf style ...)?","k":"card","b":"[hdi.design_from_words | chat | needs: paint | ui: ai.panel, ai.input]\nAlso asked as: how do i make a livery from a description\n1. Open the AI panel and describe it: \"retro red white and blue stripes, flat with chrome trim\" or \"black and gold two-tone\".\n2. Refine: \"thinner\", \"make the red orange\", \"matte\", \"another take\".\n3. Press Undo under any answer to go back."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I copy the look of a picture?","k":"card","b":"[hdi.copy_picture | chat | needs: paint | ui: ai.attach]\nAlso asked as: copy this picture\n1. In the AI panel click the paper-clip (Attach a picture) and choose the livery, logo or flag.\n2. Ask it to copy the design or the colours. Needs an AI key; check the preview and refine."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I change the on-screen size of the buttons?","k":"card","b":"[hdi.ui_size | pro | needs: none | ui: pro.header.ui_smaller, pro.header.ui_larger]\nAlso asked as: how do i make the buttons smaller\n1. Top row, the minus and plus buttons beside the percentage (\"UI Smaller / UI Larger\"). They resize the toolbars, not the canvas."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I see the keyboard shortcuts?","k":"card","b":"[hdi.shortcuts | pro | needs: none | ui: pro.settings.keyboard_shortcuts]\nAlso asked as: what are the keyboard shortcuts\n1. Press ? or Settings (gear) > \"Keyboard Shortcuts\"."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I move the finish library or panels out of the way?","k":"card","b":"[hdi.collapse_panels | pro | needs: none | ui: leftCollapseBtn, rightCollapseBtn]\n1. Click the small arrow at the edge of the left or right column to collapse it. Press E to show / hide the zone editor."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I fix a stuck or blank preview?","k":"card","b":"[hdi.fix_preview | pro | needs: paint | ui: btnPreviewRefresh]\nAlso asked as: preview is blank; the preview is stuck; preview wont update\n1. Press F5 or the \"Refresh\" button.\n2. Click the red \"Preview failed\" bar if shown.\n3. Close and reopen the app if the engine says it is offline."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > Why won't the RENDER button start?","k":"card","b":"[hdi.render_wont_start | pro | needs: paint | ui: btnRender, paintFile, iracingId, outputDir]\nAlso asked as: the render button doesnt work; render wont start; nothing works\n1. Is a paint loaded? Does the Source Paint box have a full path?\n2. Did you enter your iRacing customer ID (4-7 digits)?\n3. Does every zone you want have BOTH a colour/area and a finish? A message says which does not.\n4. Is another render still running? Wait a minute."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I recolour artwork on the paint itself (not just a finish)?","k":"card","b":"[hdi.recolour_pixels | pro | needs: paint | ui: pro.toolbar.hue_saturation, pro.toolbar.color_replace]\n1. Top toolbar > ADJUST > \"Hue / Saturation\" (shift every colour) or \"Color Replace\" (one colour to another).\n2. In LAYER mode these edit the selected layer."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I add text (lettering) to the paint?","k":"card","b":"[hdi.add_text | pro | needs: psd | ui: pro.layers.layer, pro.layers.open_layered]\nAlso asked as: can i put text on it\n1. There is no Text button in the main tool row. The easiest way: make the lettering as a transparent PNG (or in your PSD in Photoshop) and add it with LAYERS tab > \"+ Layer\".\n2. Then move and size it with Move (V) and Transform (Ctrl+T) in LAYER mode.\n3. For a PSD, edit the text layer in Photoshop and re-open it with \"Open Layered\"."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I use the eyedropper to match a colour on the car?","k":"card","b":"[hdi.eyedropper | pro | needs: zone, paint | ui: vtModeEyedropper, eyedropperAddColorBtn, eyedropperSetBtn]\n1. Pick Color (P) in the toolbar, choose the zone in the box that appears, click the colour on the SOURCE picture.\n2. \"+ Add Color\" adds it to the zone; \"Set\" replaces the zone's colour."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I make a car side different from the other side?","k":"card","b":"[hdi.left_vs_right | pro | needs: paint | ui: zone.draw_box, zone.order]\nAlso asked as: how do i make the left side different from the right; how do i do a two tone\n1. Make one zone per side with APPLY AREA > \"Draw box\" around each side's panel on the flat sheet.\n2. Give each its own finish or colour; both sides are separate rectangles.\n3. Or in Chat say \"make the left side matte black\" if the car's parts are known."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > What are Foundation finishes and what is a \"brings its own colours\" finish?","k":"card","b":"[hdi.finish_kinds | pro | needs: none | ui: zone.base_material, zone.base_color_mode]\n1. Foundation (f_) finishes change only the shine; with \"Use source paint (spec only)\" they leave your colours alone.\n2. Plain bases (gloss, matte, satin, candy, pearl, metallic) take the zone colour.\n3. Special finishes (carbon, camo, holographic, flames ...) bring their own colours: recolour them with Hue Shift, not a solid colour."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I know what the base finishes do?","k":"card","b":"[hdi.base_finishes | pro | needs: none | ui: zone.base_material]\n1. Gloss = standard shiny paint, Matte = flat, Satin = soft sheen, Chrome = mirror, Candy = deep tinted gloss, Pearl = shimmer, Metallic = flake.\n2. Hover or tap a finish in the picker to read what it does."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I make a finish more or less glossy?","k":"card","b":"[hdi.gloss_level | pro | needs: zone | ui: zone.g_rough, zone.b_coat, zone.spec_strength]\nAlso asked as: how do i make it glossy\n1. Spec Sliders: \"G Rough\" lower = glossier, higher = duller.\n2. \"B Coat\" sets the clearcoat glass look. \"Spec Strength\" scales it all."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I fix numbers or sponsors that look wrong under a special finish?","k":"card","b":"[hdi.numbers_look_wrong | pro | needs: psd | ui: zone.restrict_layers, pro.toolbar.decal_rescue_kit]\nAlso asked as: my numbers look sparkly\n1. Make sure the body zone is limited to \"Car Paint\" under RESTRICT TO LAYERS so numbers are not covered.\n2. Use SPEC TOOLS > \"Decal Rescue Kit...\" if they read sparkly or dull."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I get started with a PSD that has many layers and I'm overwhelmed?","k":"card","b":"[hdi.psd_overwhelmed | pro | needs: psd | ui: layer.search, spbGuideToggle]\nAlso asked as: i have too many layers\n1. Turn on Training Wheels (\"Tutorial\").\n2. In Pro use the \"filter...\" box in the LAYERS tab and ignore Mask / Wire / Car_Mandatory."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I use SPEC SCULPT?","k":"card","b":"[hdi.spec_sculpt | pro | needs: paint | ui: pro.header.spec_sculpt]\n1. Click \"SPEC SCULPT\" in the top row for the guided look library of spec-only effects.\n2. After saving a Sculpt spec the main RENDER keeps that spec; clear the imported spec map in Settings to go back to zone shine."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I import art or a pack (Shokk Drop)?","k":"card","b":"[hdi.shokk_drop | pro | needs: paint | ui: pro.header.shokk_drop]\n1. Click \"Shokk Drop\" in the top row.\n2. Import art, Import DNA spec, or share .spbdrop packs."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > How do I randomise a look for ideas?","k":"card","b":"[hdi.randomise | pro | needs: paint | ui: pro.zones_more.rand_current_zone, pro.zones_more.rand_all_zones, swatchDiceBtn]\nAlso asked as: surprise me; randomize everything; give me ideas\n1. Left column > More > \"Rand Current Zone\" or \"Rand All Zones\".\n2. In the picker, \"Surprise me\" rolls one good finish. Ctrl+Z undoes."},{"t":"How do I ... in Shokker Paint Booth (AI knowledge card: step by step with the exact button names) > What is NOT in Shokker today (animation, other sims, 3D view, a shop, live Photoshop sync, Mac)?","k":"card","b":"[hdi.not_in_shokker | any | needs: none | ui: btnRender, live_preview]\nAlso asked as: can i make an animated paint; does it work with other sims; is there a mac version; can i sell my paints; can i paint in 3d; live photoshop sync; glow in the dark\n1. Honest answer: that is not available in Shokker today. Not in the app: animated or moving paints, glow-in-the-dark paint (iRacing has no emissive paint), other sims (Shokker writes iRacing paint + spec TGAs only), a 3D car view or painting on a 3D model, a shop or marketplace to sell paints, live sync with Photoshop while you edit, and a Mac version (Windows only).\n2. Nearest thing you can do: render, then look at the car in iRacing's own 3D paint viewer; for Photoshop, save your PSD and load it again with \"PSD/XCF/ORA\" (top row, SOURCE PAINT).\n3. Everything else - colours, finishes, patterns, spec - is in Pro; ask \"how do I ...\" for the steps."},{"t":"Sliders and controls: what every zone setting does > Controls: colour (hue, saturation, brightness, solid colour, source paint)","k":"card","b":"BASE COLOR dropdown [color / gradient]: \"Use finish's own color\" (the material keeps its colour), \"Use source paint (spec only)\" (keep the car's colours, change only the shine: color \"source\"), \"Use solid color\" (an exact #rrggbb), \"From special\", \"Custom gradient\" (2-10 stops, direction horizontal / vertical / diagonal / radial). A plain solid colour renders exactly; never use the Color Lab (Depth / Flip / Underglow) for an exact colour. HUE SHIFT [hue -180..180] rotates every colour of the zone round the colour wheel (measured on green: +180 = magenta, -150 = hot pink, +150 = purple; shift = target hue minus current hue); SATURATION [saturation -100..100] greys out or boosts; BRIGHTNESS [brightness -100..200] darkens or lightens. They apply after the colour mode, on top of the finish's own or the source colours, and never change the shine. Greys have no hue: they need a colour mode, not a hue shift."},{"t":"Sliders and controls: what every zone setting does > Controls: base material (scale, rotation, strength, intensity)","k":"card","b":"BASE SCALE [scale 0.05-5x, 1 = normal]: smaller = finer flake / grain of the base material. BASE ROTATION [rotation]: direction of brushed or grain textures. BASE STRENGTH [base_strength 0-100%, UI] fades the whole finish over the car's own paint (0 = original paint, 100 = full finish). SPEC STRENGTH [spec_strength] weakens or boosts only the material (shine / metal) not the colour. INTENSITY [intensity 0-100] is the whole-zone strength preset: lower = calmer, closer to the original. WEAR [wear] scuffs the finish. Wrong control = no visible change: for \"more subtle\" use base strength or intensity, for \"less shiny\" use spec strength."},{"t":"Sliders and controls: what every zone setting does > Controls: pattern (id, scale, rotation, opacity, paint mode)","k":"card","b":"PATTERN swatch [pattern.id] paints a repeating design on the zone. PATTERN SCALE [pattern.scale, UI 0.1-4x]: a SMALLER number repeats the pattern MORE times = a finer weave, smaller scales, tighter camo; 0.5 is twice as fine and is what the owner means by \"crushed to 50%\"; the car is one 2048 sheet, so 1.0 often reads big. ROTATE [pattern.rotation 0-359]. OPACITY [pattern.opacity 0-100] fades the pattern into the base colour (30-50 = subtle). STRENGTH (pattern effect in paint and spec). PAINT MODE (measured: in Overlay a snake pattern paints its own brown and your base colour does not show): Overlay draws the pattern's own colours; Blend keeps the paint colour and only modulates light / dark with the pattern, so the base colour decides the camo hue. More pattern layers (up to 4 extra) each carry their own opacity, scale, rotation and blend; edit_zone sets pattern 1 only, use a second zone for another pattern."},{"t":"Sliders and controls: what every zone setting does > Controls: spec patterns (shine texture, never colour)","k":"card","b":"SPEC PATTERNS [spec_patterns: up to 5 layers, each {id, opacity, scale, rotation, channels}] change HOW the surface reflects: sparkle, brushed sheen, scale-by-scale highlights. Opacity (default 50) is the strength, Scale smaller = finer, channels M / R / C pick Metal, Roughness, Clearcoat. They do not change the paint colour, so a flat colour preview looks the same: judge them in the spec preview. The call REPLACES the existing spec stack, so send every layer you want to keep. Use them to weave a pattern's look into the shine without touching the colours."},{"t":"Sliders and controls: what every zone setting does > Controls: direct metal / roughness / clearcoat (spec shift)","k":"card","b":"SPEC SHIFT [spec_shift {metal, rough, clearcoat}, each -127..127] pushes the zone's Metal, Roughness and Clearcoat channels. Metal + = more metallic; rough + = duller, rough - = glossier; clearcoat: 16 is the maximum gloss and higher is duller, so clearcoat + dulls. Satin = rough +40..+80 and clearcoat +30..+60. These add on top of the finish, patterns and spec strength. There is no slider for absolute values: pick a finish whose card has the wanted shine, then shift."},{"t":"Sliders and controls: what every zone setting does > Controls: which pixels, order, mute (zone rules)","k":"card","b":"A zone owns pixels chosen by region: named part (left side, hood), band (height roof-line to rocker, length front to rear), layer, element (numbers / sponsors / stripes), colours with tolerance (6-100: \"the blue parts\"), exclude, or everything / remaining. WHERE TWO ZONES SELECT THE SAME PIXEL THE ONE HIGHER IN THE LIST WINS (lower index = top). New zones go on top. The \"remaining\" zone must stay last. MUTE hides a zone without deleting it. If a new zone shows nothing, a zone above has already claimed those pixels."},{"t":"Sliders and controls: what every zone setting does > Controls: the colour rules that trip people up","k":"card","b":"1) Items split into \"takes the zone colour\" (gloss, satin, matte, candy, pearl, metallic: a solid colour or gradient recolours them) and \"brings its own colours\" (monolithic specials, most pattern palettes, camo / snake finishes). Solid colour on an own-colour finish (measured) paints it one flat colour and loses the camo: shift its hue / saturation instead, or choose a take-colour base plus a pattern. 2) Hue shift is relative to what is there, not an absolute target: measure, then nudge by 10-20 degrees. 3) The helper never sets Color Lab depth. 4) Whole-car looks use the zone region everything + paintable; decals (numbers, sponsors) stay on top."},{"t":"Sliders and controls: what every zone setting does > Recipe: \"pink camo rattlesnake\" built from sliders when no such finish exists","k":"card","b":"1) Do not search for the exact phrase: split it. Camo = the look, pink = a colour, rattlesnake = a scale pattern. 2) Base zone (this is the pink): a base that takes colour (gloss, satin or matte), colour solid pink (#ff69b4 hot pink, #f4a6c0 soft) or, if you start from an existing green camo finish, hue shift about -150 (measured: green becomes hot pink) plus saturation +30 and brightness +40. 3) Camo on the same zone: pattern \"multicam\" (or \"camo\") with paint mode Blend so the pink base colour stays, opacity 70, scale 0.6. 4) Rattlesnake: the paint pattern \"snake_skin_3\" (hourglass viper saddles) as a second zone on top at opacity 40-60 and scale 0.5, or keep colour untouched and weave it into the shine with spec pattern \"spec_snake_scales\" at opacity 50-70, scale 0.4-0.6, channels MR. 5) Optional satin: spec shift rough +40, clearcoat +30. 6) Look at the preview, say plainly what was matched and what was approximated."},{"t":"Tutorial 1 \u2014 Your First Livery > Open SPB and meet the Silverado","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Launch SPB from the Start Menu. The first time you open the app, the **Chevy Silverado 2019** demo PSD loads automatically. You don't have to find a file, import anything, or configure anything. SPB just opens to a real, paint-able truck.\n\nTake a quick tour:\n\n- **Center:** the canvas. That's the truck's UV-unwrapped paint texture.\n- **Right side:** the **Layers** and **Finishes** panels (two tabs at the top).\n- **Left side:** the **Zones** panel, currently empty, plus the toolbar.\n- **Top:** the file menu, the big gold **RENDER** button, and the active-layer dock.\n\nIf you don't see all of this, press `Tab` once to toggle the panels back on.","x":1},{"t":"Tutorial 1 \u2014 Your First Livery > Add a zone","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Look at the **Zones** panel on the left. Click **+ Add Zone**.\n\nA card appears called `Zone 1` with a placeholder color swatch and finish slot. This is the basic building block of SPB: a zone is \"a region of the paint that gets one specific color and finish.\" Most liveries are built from three to ten zones.","x":1},{"t":"Tutorial 1 \u2014 Your First Livery > Pick a color","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Click the color swatch on the Zone 1 card. The color picker pops open.\n\nFor your first livery, pick something bold. **Hex `#E63946`** is a great race red. Type it into the hex field, hit Enter, then click **Apply**.\n\nThe swatch updates. The whole truck doesn't turn red yet because we haven't told the zone *where* to paint. By default a fresh zone covers the whole car, so the entire truck is now flagged for red \u2014 but you won't see it until we apply a finish. That's next.","x":1},{"t":"Tutorial 1 \u2014 Your First Livery > Pick a finish","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Click the **Finishes** tab at the top of the right panel.\n\nScroll until you find the **Candy / Liquid** category. Expand it and click **candy_apple**.\n\nWithin a second or two, the canvas redraws. The Silverado is now wearing a deep, juicy candy-apple red coat. The Live Preview pane (split with the canvas) shows you the same paint with realistic 3D-aware shading so you can see how light catches the curves.\n\nPause and admire. You are five clicks into SPB and you have a real livery.\n\n> Tip: candy_apple is one of dozens of finishes. The **\u2605 COLORSHOXX** category at the very top has the wildest premium options. We'll cover the full catalog in Tutorial 4.","x":1},{"t":"Tutorial 1 \u2014 Your First Livery > Hit RENDER","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) In the top header, click the big gold **RENDER** button.\n\nSPB does three things in sequence:\n\n1. Composites the final color paint texture (the `.tga` iRacing reads for color)\n2. Generates a matching spec map (the `_spec.tga` iRacing reads for material properties)\n3. Copies both into your iRacing car folder (the **iRacing Car Folder** in the top bar)\n\nA green banner under the render tells you where the files went, something like:\n\nDocuments\\iRacing\\paint\\trucks silverado2019\\car_num_<your-iracing-id>.tga\nDocuments\\iRacing\\paint\\trucks silverado2019\\car_spec_<your-iracing-id>.tga\n\n(`car_num_` when **Custom Number** is selected next to your ID, `car_` for **Sim-Stamped Number**; iRacing loads the one that matches its **Hide Car Numbers** setting.) If the car folder is empty, SPB still renders but nothing is copied into iRacing, and a banner tells you to set the car folder.","x":1},{"t":"Tutorial 1 \u2014 Your First Livery > See it in iRacing","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) If iRacing is already running with your car:\n\n1. **Alt+Tab** to iRacing.\n2. Press **Ctrl+R** (Reload Car Textures). The car flashes white, then shows your new paint.\n\nIf iRacing isn't running, start it: the custom paint loads when you sit in the car.\n\nThat's it. You painted a car. Welcome to the club.\n\n---","x":1},{"t":"Tutorial 2 \u2014 Layer Basics > Open the Layers panel","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) If you've still got the Silverado loaded from Tutorial 1, look at the right side of the screen. There are two tabs at the top: **Layers** and **Finishes**. Click **Layers**.\n\nYou'll see a long, scrollable list. Each row is a layer in the underlying PSD template \u2014 things like:\n\n- `Background`\n- `Body Base`\n- `Hood`\n- `Doors`\n- `Roof`\n- `Numbers`\n- `Sponsors`\n- `Stripes`\n- `Window Trim`\n\nThe exact list depends on the template (different cars have different parts). The Silverado has about 30 layers.","x":1},{"t":"Tutorial 2 \u2014 Layer Basics > What's a PSD layer, in 30 seconds","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) iRacing's car painting templates are Photoshop files (`.psd`). A PSD is a stack of transparent images, one on top of the other, that combine to form the final paint. Each layer is one piece \u2014 the hood is a layer, the door numbers are a layer, the manufacturer logo is a layer. When SPB loads a PSD, it preserves that layer structure.\n\nThis matters because **zones in SPB can be restricted to a single layer.** That means you can say \"paint the Hood layer red\" without affecting any other part of the truck. We'll do exactly that in Tutorial 3.","x":1},{"t":"Tutorial 2 \u2014 Layer Basics > Select a layer","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Click the **Numbers** layer in the panel.\n\nTwo things happen:\n\n1. The row highlights gold. That layer is now your **active layer**.\n2. The **active-layer dock** above the canvas updates to show the layer's name and a few quick-action buttons.\n\n> Tip: Selecting a layer here tells SPB which layer your *drawing tools* (brush, eraser, fill bucket) will paint on. Selecting a layer does NOT yet restrict any zone to that layer \u2014 that requires the gold **Lock** button, covered in Tutorial 3.","x":1},{"t":"Tutorial 2 \u2014 Layer Basics > Tour the active-layer dock","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) The dock above the canvas is a small but powerful UI element. From left to right it has:\n\n- **Layer name** \u2014 confirms which layer you've got selected\n- **Visibility toggle** (eye icon) \u2014 show or hide the layer\n- **Solo** \u2014 temporarily hide every other layer so you only see this one\n- **Opacity slider** \u2014 fade the layer from 0 to 100 percent\n- **Lock to Layer** (the gold padlock) \u2014 pin the active zone to this layer (Tutorial 3 covers this in detail)\n- **Effects** (FX) \u2014 open the Layer Effects dialog (Tutorial 7)\n\nHover any of these for a tooltip. The dock is the single most-used UI element after the zones panel itself.","x":1},{"t":"Tutorial 2 \u2014 Layer Basics > Toggle visibility","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Click the eye icon next to a layer in the panel \u2014 say, **Sponsors**.\n\nThe sponsor logos disappear from the canvas. Click again, they come back. Visibility toggles are non-destructive: hiding a layer doesn't delete anything, it just stops drawing it during preview and render.\n\nThis is incredibly useful for:\n\n- A/B testing designs (\"does the truck look better with or without the door numbers?\")\n- Cleaning up the canvas while you work on a fiddly part\n- Temporarily hiding clutter to take a clean screenshot\n\n> Tip: `Alt+click` the eye icon to **solo** the layer \u2014 hide everything except the one you clicked. `Alt+click` again to restore.","x":1},{"t":"Tutorial 2 \u2014 Layer Basics > Move a layer in the stack","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Click and drag the **Stripes** layer up or down in the list.\n\nLayer order matters. Layers higher in the panel render *on top of* layers below. Move Stripes above Sponsors and your stripes will cover the sponsor logos. Move it back down and the sponsors paint over the stripes.\n\nThis is the same as Photoshop layer ordering. If you've done any digital art, it'll feel familiar instantly. If you haven't, the rule of thumb is: **top of the panel = on top of the canvas.**","x":1},{"t":"Tutorial 2 \u2014 Layer Basics > Lock a layer","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Right-click any layer and pick **Lock layer** from the menu (or use the lock icon in the layer row).\n\nA locked layer can't be edited by the drawing tools. It's a guardrail \u2014 useful when you're doing detail work near a layer you don't want to bump.\n\n`Ctrl+L` while a layer is selected toggles its lock state.\n\n---","x":1},{"t":"Tutorial 3 \u2014 Zones Explained > What's a zone, really?","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) A **zone** is a named region of your paint that gets one combined \"look\" \u2014 a color, a base finish, a pattern, and a spec map override. Think of it as a recipe for one part of the truck:\n\n> \"The hood is matte black with a carbon-weave pattern.\"\n> \"The doors are candy red with chrome accents.\"\n> \"The numbers are gloss white with a gold stroke and drop shadow.\"\n\nEach of those sentences is one zone.\n\nThe brilliance of zones is that you don't have to hand-paint every pixel. You define a region (by color, by layer, or by both) and assign a finish to it. SPB does the rest.","x":1},{"t":"Tutorial 3 \u2014 Zones Explained > Color match selection","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Add a fresh zone (`+ Add Zone` in the Zones panel). Click its color swatch.\n\nIn the color picker dialog, instead of typing a hex code, click the **Eyedropper** icon. Then click anywhere on the truck canvas \u2014 say, on the yellow door numbers.\n\nTwo things happened:\n\n1. The zone's **color** is now that exact yellow.\n2. The zone's **mask** is now \"every pixel on the truck that matches this yellow.\"\n\nThat second one is the magic. SPB looked at every pixel on the entire truck, found the ones whose color is close to the yellow you sampled, and made them the zone's region. You didn't draw a selection. You didn't paint a mask. You just sampled a color.\n\nHit RENDER. The yellow numbers (and only the yellow numbers) get whatever finish you assign to this zone. Everything else is unchanged.","x":1},{"t":"Tutorial 3 \u2014 Zones Explained > Add tolerance and multiple colors","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Real liveries don't have one perfect pixel of yellow \u2014 they have a spectrum because of anti-aliasing, JPG artifacts, and shading. SPB handles this with **tolerance**.\n\nIn the zone card, find the **Tolerance** slider. Default is around 12. Drag it up to 30. The zone now matches yellow plus near-yellow pixels too.\n\nNeed to match multiple distinct colors in the same zone? Click **+ Add Color** in the zone card and sample a second color. The zone now matches *both*. Useful for things like \"match all the team colors as one zone.\"","x":1},{"t":"Tutorial 3 \u2014 Zones Explained > Layer restriction (the gold button)","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Color matching by itself is powerful but imperfect. Sometimes pixels of the same color exist in places you don't want \u2014 a yellow numbers zone might accidentally pick up yellow pixels in a sponsor logo on the other side of the truck.\n\nThis is where layer restriction comes in.\n\nSelect the **Numbers** layer in the right panel (Tutorial 2 covers this). Then look above the canvas at the active-layer dock. The gold button labeled **\ud83d\udd12 Lock Active Zone to This Layer** is the one we want.\n\nClick it.\n\nTwo things just happened:\n\n1. The active zone is now restricted to **only paint pixels that exist on the Numbers layer.**\n2. The zone card shows a small layer badge confirming the binding.\n\nNow even if the same yellow exists in 20 other places on the truck, the zone won't touch them. Color match + layer lock is the combination that powers 90% of professional liveries.\n\n> Tip: This gold button is the single biggest workflow shortcut in SPB. Whenever you find yourself wishing you could \"just paint this one part,\" reach for it.","x":1},{"t":"Tutorial 3 \u2014 Zones Explained > Multiple zones and priority","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Add a second zone. Make it red. Sample a red pixel somewhere on the truck (or just type `#E63946`). Pick a finish.\n\nYou now have two zones: yellow Numbers and red Something Else.\n\nLook at the zones panel \u2014 they stack. The zone at the **top of the stack has higher priority.** If two zones target overlapping pixels, the higher-priority zone wins.\n\nDrag-and-drop to reorder. This is the same metaphor as Photoshop layers but applied to *paint regions.* The intuition is exactly the same: top wins.","x":1},{"t":"Tutorial 3 \u2014 Zones Explained > Special zones: Remaining and Everything","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Look at the dropdown that normally says \"Custom\" on a zone card. There are two special values:\n\n- **Remaining** \u2014 fills every pixel on the truck that isn't already claimed by a higher-priority zone.\n- **Everything** \u2014 fills every pixel on the truck regardless of other zones (this is essentially a \"background\" override).\n\n`Remaining` is the workhorse. The pattern goes:\n\n1. Build several specific zones for important parts (numbers, sponsors, hood)\n2. Add one final zone, set it to **Remaining**, and give it your base body color and finish\n\nThat last `Remaining` zone catches everything else. You don't have to build a \"body base\" zone manually \u2014 SPB does it for you.","x":1},{"t":"Tutorial 3 \u2014 Zones Explained > The yellow #55 bug story (and the alpha-mask fix)","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Real story from SPB development that teaches a critical lesson.\n\nA user built a livery with yellow #55 numbers. Color matched, layer locked, finish assigned. Render came out \u2014 and the entire truck had subtle yellow halos on the edges of every other shape. Tiny, but visible in bright light.\n\nWhat happened? Anti-aliased edges. The pixels at the boundary of every shape on the truck contain a little of every nearby color, including yellow. Color matching at high tolerance picked them up. Even with layer restriction, the *layer* itself had partially-transparent yellow pixels at its boundaries.\n\nThe fix was an **alpha-mask threshold**: SPB now ignores pixels with an alpha below a configurable threshold (default 0.5) when building zone masks. If a pixel is less than half-opaque on its layer, it doesn't count.\n\nThe lesson for you: if you ever see \"ghost\" zone coverage where you don't expect it, check the **Alpha Threshold** slider on the zone card. Pull it up to 0.6 or 0.7 to be stricter. Most of the time the default works, but it's the first thing to adjust when masks misbehave.\n\n---","x":1},{"t":"Tutorial 4 \u2014 Finishes Deep Dive > Open the Finishes tab","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Click **Finishes** in the right panel. You'll see the picker organized into expandable categories. The first thing to notice: the categories are stacked top-to-bottom by *fanciness*. The premium catalogs are at the top, the workhorse bases are in the middle, and the spec patterns sit in their own separate area.\n\nThere's also a search bar at the top. Type any partial name and the list filters in real time. `Ctrl+F` jumps focus there.","x":1},{"t":"Tutorial 4 \u2014 Finishes Deep Dive > The Foundations (bases)","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) A **base** is the fundamental \"kind of paint\" a zone has. Every zone needs exactly one base. The base controls the underlying color, gloss level, metallic flake, and overall material feel.\n\nCommon bases:\n\n- **gloss_clean** \u2014 high-gloss solid color. Your default for most race liveries.\n- **matte_clean** \u2014 flat, no-gloss solid color. Modern stealth look.\n- **satin_clean** \u2014 the in-between. A subtle sheen that's neither candy nor matte.\n- **metallic_standard** \u2014 solid color with metallic flake suspended in the paint. The classic factory metallic look.\n- **candy_apple** \u2014 translucent candy coat over a metallic base. Deep, juicy, color-shifting.\n- **chrome_mirror** \u2014 full mirror chrome. Reflects the world.\n- **carbon_composite** \u2014 a carbon-fiber look without a separate pattern overlay.\n- **ceramic_glass** \u2014 a deep, slightly translucent ceramic finish with subsurface scatter feel.\n\nClick a few. Each one totally changes the feel of the truck while keeping your zone's color the same. The *color* you pick on the zone is the *hue* the base wears \u2014 so a candy_apple zone with green color is candy green, not candy red.\n\n> Tip: 80% of liveries you'll see in the wild use **gloss_clean** or **metallic_standard**. Start there before reaching for the exotic stuff.","x":1},{"t":"Tutorial 4 \u2014 Finishes Deep Dive > Patterns (overlays)","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) A **pattern** sits on top of a base and adds repeating texture. Patterns don't replace the base \u2014 they modulate it.\n\nCommon patterns:\n\n- **carbon_weave** \u2014 classic carbon fiber 2x2 twill weave\n- **scales** \u2014 overlapping scale pattern, dragon-skin look\n- **honeycomb** \u2014 hexagonal cells\n- **forge_mesh** \u2014 industrial mesh\n- **chameleon** \u2014 color-shifting iridescence\n- **brushed_directional** \u2014 brushed metal grain\n\nPick a base (try metallic_standard) and then expand the **Patterns** category. Click **carbon_weave**. The truck now has metallic paint with a carbon weave on top \u2014 visible up close, blended at distance, exactly like real carbon-pattern wraps.\n\nPatterns have a **strength slider** in the zone card. 100% is full pattern; 0% is no pattern. Most users live between 30 and 70 depending on how subtle they want the effect. The new Pattern Strength Zones feature (v6.1.1) lets you vary strength per zone region \u2014 useful for fading a pattern out across the body.","x":1},{"t":"Tutorial 4 \u2014 Finishes Deep Dive > Monolithics (the all-in-one premium finishes)","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) A **monolithic** is a complete finish that bakes the base, pattern, and spec into one unit. You don't pick a base or a pattern when you use a monolithic \u2014 the monolithic is the whole package.\n\nThe premium monolithic catalogs:\n\n### \u2605 COLORSHOXX\n\nColor-shifting, energy-feel finishes. They auto-tint based on your zone color but bring their own visual personality.\n\n- **CX Inferno** \u2014 flame energy, shifts from base color through orange and yellow\n- **CX Aurora** \u2014 soft northern-lights gradient\n- **CX Glitch** \u2014 digital corruption / RGB split aesthetic\n- **CX Plasma** \u2014 electric-purple plasma feel\n\n### \u2605 MORTAL SHOKK\n\nAggressive, high-contrast battle finishes. Less color-shifty than COLORSHOXX, more \"this car wants to fight.\"\n\n- **MS Battlescar** \u2014 distressed, scratched battle-worn look\n- **MS Kintsugi** \u2014 gold-cracked ceramic feel\n- **MS Warpaint** \u2014 bold tribal slash overlay\n\n### \u2605 PARADIGM\n\nThe flagship category. Each PARADIGM finish is hand-tuned to look like a specific high-end real-world finish you'd pay $20k for at a custom shop.\n\n- **PD Liquid Metal** \u2014 molten chrome look\n- **PD Holographic** \u2014 true holographic foil aesthetic\n- **PD Cosmic** \u2014 galaxy / nebula effect\n- **PD Prism** \u2014 prism diffraction rainbow\n\nTry one. Click **CX Inferno** with a yellow zone. The truck transforms into a deep, color-shifting flame finish that no amount of base+pattern stacking would have produced. That's why monolithics exist \u2014 some looks are too cohesive to build by hand. ...","x":1},{"t":"Tutorial 4 \u2014 Finishes Deep Dive > Spec Patterns (the PBR layer)","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) A **spec pattern** is a separate overlay that adds variation to the **spec map** without changing the color paint. Most users miss this category at first because it's not in the main bases list \u2014 it lives in its own section.\n\nWhy does this matter? The spec map controls *material*, not color. A spec pattern can add things like:\n\n- **clearcoat_orange_peel** \u2014 subtle orange-peel texture on the clearcoat (looks like real automotive paint up close)\n- **water_droplets** \u2014 beaded water on the surface\n- **scuff_micro** \u2014 micro-scuffing for a worn-in look\n- **rain_streaks** \u2014 vertical rain streaks for \"drove home in a storm\" realism\n- **honeycomb_spec** \u2014 hexagonal honeycomb in the spec channel only (color stays uniform; reflectance varies)\n\nThese don't change what color the car is. They change how light catches it. Stacking a clearcoat_orange_peel spec pattern on top of a glossy red base is the difference between \"video game paint\" and \"this looks like a real car.\"\n\nThe new SPB v6.2 catalog has 100+ spec patterns. Most are subtle on purpose. Apply one and look at the **Live Preview** with light dragged across it \u2014 you'll see the surface respond differently than before.","x":1},{"t":"Tutorial 4 \u2014 Finishes Deep Dive > The full stack","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) The maximum recipe is:\n\nZone Color: red\nBase:           metallic_standard\nPattern:        carbon_weave (40% strength)\nSpec Pattern:   clearcoat_orange_peel\n\nColor (red) flows through metallic_standard (which gives a metallic red base), then carbon_weave overlays a subtle weave pattern, then the clearcoat_orange_peel spec pattern adds realistic clearcoat micro-texture.\n\nHit RENDER. Look closely. That's a four-layer finish \u2014 and it took four clicks to build.\n\n---","x":1},{"t":"Tutorial 5 \u2014 Spec Map Mastery > What's a spec map?","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) When you hit RENDER, SPB writes two files:\n\n- `car_<id>.tga` \u2014 the **color paint**. Tells the renderer what color each pixel is.\n- `car_spec_<id>.tga` \u2014 the **spec map**. Tells the renderer what *material* each pixel is.\n\nColor is the hue. Spec is the feel. Same red color can be glossy candy, matte rally, mirror chrome, or dusty primer \u2014 and the only difference between those four is the spec map.\n\niRacing (and most modern games) use a Physically Based Rendering (PBR) pipeline that combines both textures with the camera position and the world lighting to produce the final pixel you see. Without a correct spec map, the renderer doesn't know how the surface should respond to light, and your paint looks wrong even when the color is perfect.","x":1},{"t":"Tutorial 5 \u2014 Spec Map Mastery > The four channels","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) A spec map is a regular image with four 8-bit channels: R, G, B, A. Each channel encodes one material property:\n\n| Channel | Property | 0 means | 255 means |\n|---|---|---|---|\n| **R** | Metallic | Dielectric (paint, plastic) | Pure metal (chrome, steel) |\n| **G** | Roughness | Mirror smooth | Diffused/matte |\n| **B** | Clearcoat | Max gloss (yes, really \u2014 see Step 4) | No clearcoat / dull |\n| **A** | Specular Mask | Special-case override | Default behavior |\n\nYes, blue being **inverted** is weird. Yes, every newcomer trips on it. Step 4 has the full story.","x":1},{"t":"Tutorial 5 \u2014 Spec Map Mastery > Iron Rules","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) These are the \"always\" and \"never\" rules. Memorize them.\n\n**Always:**\n- Match metallic + clearcoat sensibly. Chrome (R=255) should have B near 16 (max gloss), not 200.\n- Use SPB's bases \u2014 they encode correct R/G/B for you. The picker is a shortcut for not having to think about this.\n- Sanity-check by rendering and looking under a moving light. If the surface \"doesn't move\" with the camera, the spec map is wrong.\n\n**Never:**\n- Crank G (roughness) to 255 expecting \"more shine.\" That's backwards. 255 is *more matte*.\n- Set B to 255 thinking \"max clearcoat.\" That's *no clearcoat*. (See Step 4.)\n- Hand-paint spec maps in Photoshop without reference. Use SPB's bases or copy from `SPB_SPEC_MAP_GUIDE.md`.\n\nIf you only remember one Iron Rule, make it: **B is inverted. 16 = max gloss. 255 = dull.**","x":1},{"t":"Tutorial 5 \u2014 Spec Map Mastery > The inverted clearcoat gotcha","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) This is so important it gets its own step.\n\nClearcoat is the glossy clear layer over automotive paint. More clearcoat = more gloss. Intuitively, you'd expect a 0-255 channel where 0 = none and 255 = max. iRacing did the opposite.\n\n**B = 0 to 15:** No clearcoat (dull, no glassy reflection on top).\n**B = 16:** **Maximum clearcoat / gloss.** This is the \"deep show-car wet-look\" value.\n**B = 17 to 255:** Clearcoat fades back out, with 255 being effectively no clearcoat at all.\n\nYes, this means the *one specific value of 16* is the sweet spot for max gloss. SPB encodes this correctly under the hood \u2014 when you pick a glossy base, the spec map's B channel gets 16, not 255. But if you're ever editing a spec map by hand, this is the gotcha that will eat your day.\n\nReference values for the canonical materials (from `SPB_SPEC_MAP_GUIDE.md`):\n\n| Material | R | G | B |\n|---|---|---|---|\n| Chrome mirror | 255 | 0 | 16 |\n| Glossy paint | 0 | 30 | 16 |\n| Metallic paint | 200 | 60 | 16 |\n| Satin | 0 | 130 | 100 |\n| Matte | 0 | 220 | 15 |\n| Carbon weave | 50 | 100 | 16 |","x":1},{"t":"Tutorial 5 \u2014 Spec Map Mastery > The channel inspector","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) SPB has a built-in tool for visually debugging spec maps. Open it from `View \u2192 Channel Inspector` (or `Ctrl+Shift+I`).\n\nYou get four small thumbnails \u2014 one per channel \u2014 showing the spec map decomposed. Hover any pixel on the main canvas and the inspector shows the R/G/B/A values at that exact location.\n\nThis is gold for debugging:\n\n- \"Why does this part look matte?\" \u2192 Check G. If it's high (200+), there's your answer.\n- \"Why isn't my chrome reflecting?\" \u2192 Check R. If it's not 255, it isn't fully metallic.\n- \"Why does it look dusty everywhere?\" \u2192 Check B. If it's high (200+), clearcoat is suppressed.\n\nSpend a minute exploring the inspector with different finishes applied. You'll start to develop intuition for what \"good spec\" looks like in each channel.","x":1},{"t":"Tutorial 5 \u2014 Spec Map Mastery > A is rarely used","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) The alpha channel (specular mask) is technically supported but rarely used. iRacing's renderer treats A=255 as \"use the spec map normally\" and A<255 as \"fade the spec effect by this amount.\" Most SPB finishes leave A at 255.\n\nIf you're not building unusual cosmetic effects, you can ignore A entirely. SPB doesn't currently expose a UI for editing A directly \u2014 and that's fine, because in production work it almost never matters.\n\n---","x":1},{"t":"Tutorial 6 \u2014 Sponsor Placement > Find the Sponsors layer","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) In the Layers panel, scroll until you see a layer (or a group) called **Sponsors**. The Silverado template has a small starter set of placeholder sponsor logos already on this layer.\n\nClick the **Sponsors** layer to make it active.\n\n> Tip: If your template has sponsors in a group rather than a single layer, expand the group to see individual logos as sub-layers. SPB treats group children as fully independent layers.","x":1},{"t":"Tutorial 6 \u2014 Sponsor Placement > Import a logo","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Most users want to add their own sponsor logos, not the placeholders. Two ways to do it.\n\n**Method A \u2014 the Layers panel (right column, LAYERS tab):**\n1. Click **+ Layer**.\n2. Pick a PNG, JPG, WebP or GIF of your sponsor logo. PNG with transparency is best.\n3. The logo arrives as a new image layer, sized at original resolution.\n\n**Do not drag the file onto the canvas.** Dropping a .tga/.png/.jpg onto the centre canvas area loads it as your WHOLE PAINT FILE and replaces what you have.\n\nFor best results your logo PNG should:\n\n- Be transparent background (no white square around the logo)\n- Be sized at least 512x512 (we'll downscale, but starting big preserves detail)\n- Use a single solid color or simple gradient (busy logos lose detail in iRacing's compression)","x":1},{"t":"Tutorial 6 \u2014 Sponsor Placement > The Move tool","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Press `V` to switch to the Move tool. Click your new logo on the canvas. Drag to position it.\n\nYou'll see:\n\n- A **bounding box** around the logo with eight handles for resize\n- A **center pivot** for rotation (drag the small circle outside the bounding box)\n- **Smart guides** that snap to other layer edges and the canvas centerlines\n\nHold `Shift` while dragging a corner handle to scale uniformly. Hold `Alt` to scale from center. Hold `Ctrl` while rotating to snap to 15-degree increments.\n\nFor sponsor placement on a truck, common positions are:\n\n- **Front door panel** \u2014 primary sponsor, biggest size\n- **Quarter panel** \u2014 secondary sponsor, medium size\n- **Hood** \u2014 manufacturer or series sponsor, large\n- **Rear bumper** \u2014 small text sponsors","x":1},{"t":"Tutorial 6 \u2014 Sponsor Placement > Mirror Clone","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Race cars are usually visually symmetric \u2014 what's on the driver's side is mirrored on the passenger side. SPB has a one-click solution: **Mirror Clone**.\n\nWith your logo layer selected:\n\n1. `Layer \u2192 Mirror Clone Across Centerline` (or `Ctrl+M`)\n2. Pick the axis: **Vertical (left-right)** for the typical \"mirror to the other side\" use case.\n3. Click **OK**.\n\nA new layer is created \u2014 an exact horizontal mirror of your original \u2014 placed at the corresponding position on the opposite side of the truck.\n\nThis is non-destructive in a clever way: the mirror clone is its own layer, fully editable. You can move, rotate, or even delete one side independently. They aren't linked \u2014 Mirror Clone is a one-time operation.\n\n> Tip: If you want a *linked* mirror that updates when you change the original, use `Ctrl+Shift+M` to create a **smart mirror** instead. Smart mirrors re-sync any time you edit the source. Costs a small render performance hit, but worth it for iterative design work.","x":1},{"t":"Tutorial 6 \u2014 Sponsor Placement > Layer effects: Stroke","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Logos often look weak floating on a body color. A **stroke** (outline) makes them pop.\n\nDouble-click the logo's layer in the Layers panel. The **Layer Effects** dialog opens.\n\nIn the left list, click **Stroke**. Then:\n\n- **Size:** 4-8 pixels for a noticeable but not overpowering outline\n- **Color:** White if your body is dark, black if your body is light\n- **Position:** Outside (the stroke sits outside the logo edge \u2014 most common)\n- **Opacity:** 100% for a solid edge, 50-70% for a softer feel\n\nHit **OK**. The logo now has a clean outline that separates it from the body color.","x":1},{"t":"Tutorial 6 \u2014 Sponsor Placement > Layer effects: Drop Shadow","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) A subtle drop shadow adds depth and makes a sponsor feel \"applied to the body\" rather than \"floating.\"\n\nRe-open Layer Effects (double-click the layer). Click **Drop Shadow**.\n\n- **Distance:** 3-5 pixels\n- **Spread:** 0-2 pixels\n- **Size (blur):** 4-8 pixels\n- **Angle:** 135\u00b0 (standard \"light from upper-left\" convention)\n- **Opacity:** 40-60% \u2014 subtlety is key, real shadows aren't black\n- **Color:** Pure black, or a darker version of the body color for a warmer feel\n\nHit **OK**. The sponsor now sits convincingly on the surface.","x":1},{"t":"Tutorial 6 \u2014 Sponsor Placement > Bake or live?","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) By default, layer effects are **live** \u2014 they re-render every time you adjust them, and they persist as editable across save/load. If you want to flatten them into the layer permanently (so the effect baked into the layer pixels rather than applied at render), right-click the layer and pick **Rasterize Effects**.\n\nMost users leave effects live so they can tweak. Rasterize when you're done iterating, or to free up render budget on a heavy livery with many effects.\n\n---","x":1},{"t":"Tutorial 7 \u2014 Layer Effects > Open Layer Effects","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) In the Layers panel, **double-click** any layer name (not the checkbox, the name). The Layer Effects dialog opens as a floating panel with a list of effects on the left and the settings for the selected effect on the right.\n\nEach effect has a checkbox. Check it to enable; uncheck to disable without losing settings. This makes A/B-ing a design very fast \u2014 check and uncheck effects to compare.","x":1},{"t":"Tutorial 7 \u2014 Layer Effects > Drop Shadow","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Cast a soft shadow behind the layer. The most-used effect for floating UI elements (logos, numbers, stripes).\n\n**Starting preset:**\n- Distance: 4px\n- Spread: 0\n- Size (blur): 6\n- Angle: 135\u00b0\n- Opacity: 50%\n- Color: Black\n\nTweak opacity down for subtlety. Tweak distance and angle for a stronger \"floating off the surface\" feel.","x":1},{"t":"Tutorial 7 \u2014 Layer Effects > Inner Shadow","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Cast a shadow *inside* the layer edge. Makes elements look recessed into the surface.\n\n**Starting preset:**\n- Distance: 3px\n- Size: 4\n- Angle: 135\u00b0\n- Opacity: 60%\n- Color: Black\n\nUse on: number panels that should feel \"cut into\" the body, text that should look debossed.","x":1},{"t":"Tutorial 7 \u2014 Layer Effects > Outer Glow","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) A soft color halo around the layer edge. Great for neon feels and highlighting.\n\n**Starting preset:**\n- Size: 10\n- Spread: 0\n- Opacity: 70%\n- Color: Match a complementary hue (yellow glow on red text, blue on white, etc.)\n- Blend Mode: **Screen** (this is critical \u2014 Normal looks wrong)\n\nUse on: neon-style text, highlight stripes, \"power on\" effects.","x":1},{"t":"Tutorial 7 \u2014 Layer Effects > Inner Glow","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) A soft color halo *inside* the layer edge. Subtle and adds dimension to text.\n\n**Starting preset:**\n- Size: 6\n- Opacity: 40%\n- Color: Pure white or lighter version of the fill\n- Source: Edge (glows inward from the edge)\n\nUse on: polished chrome text, gem-like logos, anything that should catch light from within.","x":1},{"t":"Tutorial 7 \u2014 Layer Effects > Stroke","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) A clean outline around the layer. Tutorial 6 covered this; here's the full parameter set:\n\n**Starting preset:**\n- Size: 4px\n- Position: Outside (Outside / Center / Inside)\n- Color: Contrasting to body\n- Opacity: 100%\n- Blend Mode: Normal\n\nPosition matters: Outside keeps the layer's fill unchanged; Inside eats into the fill; Center straddles the edge. Outside is safest for logos.","x":1},{"t":"Tutorial 7 \u2014 Layer Effects > Color Overlay","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Flood the whole layer with a solid color. Useful for mass-recoloring a sponsor logo to match a livery palette.\n\n**Starting preset:**\n- Color: Any\n- Blend Mode: **Multiply** (preserves logo shape) or **Normal** (hard replace)\n- Opacity: 100%\n\nUse on: recoloring black/white logos to match livery, turning a full-color logo into a monochrome version.","x":1},{"t":"Tutorial 7 \u2014 Layer Effects > Gradient Overlay","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Same as Color Overlay but with a gradient.\n\n**Starting preset:**\n- Gradient: Two-color linear\n- Angle: 90\u00b0\n- Opacity: 100%\n- Blend Mode: Normal\n\nUse on: number panels that fade top-to-bottom, stripes that shift hue along their length.","x":1},{"t":"Tutorial 7 \u2014 Layer Effects > Pattern Overlay","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Tile a pattern over the layer. Different from the finish Pattern system \u2014 this is layer-level, not zone-level.\n\n**Starting preset:**\n- Pattern: Pick from the dropdown\n- Scale: 50%\n- Opacity: 60%\n- Blend Mode: Multiply or Overlay\n\nUse on: adding texture to text (wood grain, carbon, fabric weave) without changing the underlying finish of the zone.","x":1},{"t":"Tutorial 7 \u2014 Layer Effects > Bevel & Emboss","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Add a 3D beveled edge to the layer. The most \"Photoshop-y\" of the effects.\n\n**Starting preset:**\n- Style: Inner Bevel\n- Depth: 100%\n- Size: 4px\n- Angle: 135\u00b0, Altitude 30\u00b0\n- Highlight: White, Screen mode, 75%\n- Shadow: Black, Multiply mode, 75%\n\nUse on: 3D-looking team logos, embossed number panels, coin-like stamps. Use sparingly \u2014 overdone bevels look very 1998.","x":1},{"t":"Tutorial 7 \u2014 Layer Effects > Satin","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) A subtle inner sheen that simulates satin fabric. Rarely used but beautiful in the right spot.\n\n**Starting preset:**\n- Color: Darker than fill\n- Opacity: 30%\n- Size: 14\n- Distance: 8\n- Blend Mode: Multiply\n\nUse on: silky-smooth team logos, stylized name plates. Very subtle effect.","x":1},{"t":"Tutorial 7 \u2014 Layer Effects > Stacking and order","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Layer effects stack in a specific order, top-to-bottom in the dialog list. You can't reorder them \u2014 Photoshop uses the same fixed order.\n\nThe render order is:\n\n1. Pattern Overlay, Gradient Overlay, Color Overlay (in that order, later ones on top)\n2. Inner Shadow\n3. Inner Glow\n4. Satin\n5. Bevel & Emboss\n6. Stroke\n7. Outer Glow\n8. Drop Shadow (at the back)\n\nThis order is why drop shadow always appears *behind* the layer fill, and stroke always *outlines* the fill.","x":1},{"t":"Tutorial 7 \u2014 Layer Effects > Effect presets","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) If you build a combo you like, save it as a preset. In the Layer Effects dialog, click **Save Preset...** at the bottom. Give it a name like \"Gold Logo\" or \"Neon Pink.\"\n\nPresets are stored per-project by default; tick **Save to global library** to make them available in every project.\n\nTo apply a preset to a new layer: double-click the layer to open effects, click **Load Preset...**, pick your saved set.","x":1},{"t":"Tutorial 7 \u2014 Layer Effects > Copy / paste layer style","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Built a complex effect combo on Layer A and want it on Layer B?\n\n- Right-click Layer A \u2192 **Copy Layer Style**\n- Right-click Layer B \u2192 **Paste Layer Style**\n\nEvery effect, every setting, applied in one click. Much faster than recreating.\n\n---","x":1},{"t":"Tutorial 8 \u2014 Recipe Workflow > Browse the recipe library","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Recipes live in two places:\n\n- **Bundled library** \u2014 ships with SPB, in the `recipes/` folder inside the app install\n- **User library** \u2014 your own recipes, stored in `Documents\\Shokker Paint Booth\\recipes\\`\n\nOpen the Recipe Browser via `File \u2192 Recipes \u2192 Browse Library` (or `Ctrl+R`).\n\nYou'll see a grid of recipe cards. Each card shows:\n\n- A thumbnail preview\n- The recipe name (e.g., \"NASCAR Classic,\" \"JDM Drift,\" \"F1 Retro\")\n- The tags / categories\n- The author\n- The date created\n\nThe bundled library has around 30 recipes covering common livery archetypes \u2014 classic stock car, modern NASCAR, sports car racing, drift culture, retro F1, GT3, rally, custom street. Good starting points for your own work.","x":1},{"t":"Tutorial 8 \u2014 Recipe Workflow > Preview a recipe","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Hover any card. A larger preview pops up with all angles of the livery rendered on a stock chassis. If the preview looks like what you want, click **Preview in Project**.\n\nSPB applies the recipe's zones and finishes to *your current truck* in a non-destructive preview mode. Your existing zones are still there \u2014 the preview is just temporary.\n\nHit `Esc` to cancel the preview without applying. Hit **Apply** to commit the recipe to your project.","x":1},{"t":"Tutorial 8 \u2014 Recipe Workflow > Import NASCAR Classic","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Let's walk through a real example.\n\n1. Open the Recipe Browser.\n2. Find **NASCAR Classic**. Click **Preview in Project**.\n3. Your Silverado transforms into a classic stock-car-style livery: large body color, white horizontal stripe across the middle, big black door numbers, a few placeholder sponsors.\n\n4. Hit **Apply** to commit.\n\nNow look at your Zones panel \u2014 you have a full set of zones (maybe 6-8) that the recipe created. Everything is named clearly: \"Body,\" \"Centerline Stripe,\" \"Door Numbers,\" \"Hood Number,\" etc.","x":1},{"t":"Tutorial 8 \u2014 Recipe Workflow > Customize the colors","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) The recipe gave you structure. Now personalize it. Every zone in the recipe is a normal zone \u2014 you can edit it like any zone you built yourself.\n\nClick the **Body** zone. Change its color. Say, from default red to a deep blue (`#0E2C5C`). The truck body updates immediately.\n\nClick the **Centerline Stripe** zone. Change the color to bright yellow (`#FFD60A`).\n\nClick each door number zone and change the number color to something that contrasts with the new body.\n\nYou've just reskinned a full NASCAR-style livery in 30 seconds. No zone wiring, no layer binding, no finish picking \u2014 the recipe did all of that; you just picked palette.","x":1},{"t":"Tutorial 8 \u2014 Recipe Workflow > Customize the finishes","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Same deal for finishes. Click any zone's finish slot and pick a new base or pattern.\n\nCommon customizations:\n\n- Body from `gloss_clean` to `candy_apple` for a juicy deep-gloss feel\n- Numbers from `gloss_clean` to `chrome_mirror` for a flashy reflective number\n- Stripes from solid to `chameleon` pattern for color-shift\n\nEach swap respects the recipe's structure \u2014 you're only changing the finish on an existing zone, not rewiring anything.","x":1},{"t":"Tutorial 8 \u2014 Recipe Workflow > Save as a new recipe","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Happy with your customization? Save it as a new recipe for future reuse.\n\n1. `File \u2192 Recipes \u2192 Save Current as Recipe`.\n2. Enter a name (e.g., \"Blue/Yellow NASCAR 2026\").\n3. Tag it (recipes support multi-tag \u2014 \"nascar, retro, blue, yellow\" is fine).\n4. Optionally add a description and author name.\n5. Click **Save**.\n\nThe recipe is written to your `Documents\\Shokker Paint Booth\\recipes\\` folder as a JSON file (or `.spb-recipe` with the same contents). It now appears in the Recipe Browser alongside the bundled library.","x":1},{"t":"Tutorial 8 \u2014 Recipe Workflow > Share a recipe with teammates","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Recipe files are portable. To share:\n\n1. Open `Documents\\Shokker Paint Booth\\recipes\\`.\n2. Find your `.spb-recipe` file (it has the name you gave it).\n3. Send it to your teammate via Discord, email, or any file share.\n4. Teammate drops it into their own `Documents\\Shokker Paint Booth\\recipes\\` folder.\n5. Teammate opens SPB \u2014 your recipe appears in their Recipe Browser.\n\nRecipes are designed to be template-agnostic within reason. A recipe built on the Silverado will apply to the Ford F-150 template too, because SPB matches zone bindings by layer *role* (e.g., \"Numbers\" layer) not by specific coordinates. Cross-series recipes (Silverado recipe on a GT3 car) work less perfectly because the layer sets are different \u2014 SPB will apply what it can and flag the rest.","x":1},{"t":"Tutorial 8 \u2014 Recipe Workflow > Recipe vs. project save","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Two save systems, different purposes:\n\n- **Project save** (`Ctrl+S`, `.spb` file) \u2014 saves *this specific* paint file with all its pixel-level paint, mask data, and zone state. Locked to the current template.\n- **Recipe save** (`File \u2192 Recipes \u2192 Save Current`) \u2014 saves only the *zone recipe* (colors, finishes, bindings, effects). Template-agnostic. Small file.\n\nUse project save for \"this is my current work-in-progress.\" Use recipe save for \"this is a reusable design formula.\"\n\n---","x":1},{"t":"Tutorial 9 \u2014 Advanced Tools > Brush Stabilizer","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Everyone's hand shakes a little. At canvas zoom levels, even a small tremor produces wobbly lines. SPB's **brush stabilizer** fixes this by lagging your brush stroke behind the cursor slightly and smoothing the path.\n\nPick the Brush tool (`B`). In the **Tool Options** bar above the canvas, find the **Stabilizer** slider. Default is 0 (off). Try 30.\n\nDraw a long curved line. The line follows your cursor but smoother \u2014 micro-tremor is filtered out. The brush tip \"trails\" the cursor by a controlled amount.\n\nSettings guide:\n\n- **0-10:** Minimal stabilization. Fast response, near-raw cursor.\n- **30-50:** Comfortable zone for most hand-drawn work. Visible smoothing without feeling laggy.\n- **60-80:** Heavy smoothing. Great for long flowing lines. Feels laggy on short strokes.\n- **90+:** Extreme. The brush trails substantially behind the cursor. Use for calligraphy-style effects.\n\n> Tip: Stabilizer works on brush, pencil, eraser, smudge, dodge, and burn. Set it once and every pen tool benefits.","x":1},{"t":"Tutorial 9 \u2014 Advanced Tools > Smart Guides","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Smart guides are alignment lines that appear automatically when you move a layer or draw near the edges or center of other shapes.\n\nPress `V` (Move tool). Drag any sponsor logo. As it approaches the horizontal centerline of the canvas, a pink line snaps on and the layer jumps to center. Same for the vertical centerline, and for alignment with any other layer's edges.\n\nToggle smart guides with `View \u2192 Smart Guides` (or `Ctrl+;`). They can get chatty on a busy canvas \u2014 disable if they're in the way, re-enable for final alignment pass.","x":1},{"t":"Tutorial 9 \u2014 Advanced Tools > Snap to Pixel","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) At fine zoom levels, cursor positions fall between pixel boundaries. Without pixel snap, a text layer might land with its edge at position 237.6 px, causing subtle antialiasing blur.\n\nEnable `View \u2192 Snap to Pixel`. Now every move, resize, and shape creation rounds to integer pixel positions. Lines are crisp. Edges don't blur.\n\n> Tip: Disable snap-to-pixel when you *want* sub-pixel positioning for organic feel (like scattered grass, dust, or stippled effects). Enable for geometric, technical work (numbers, stripes, logos).","x":1},{"t":"Tutorial 9 \u2014 Advanced Tools > Recent Colors palette","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) The **Recent Colors** row below the main color picker keeps the last 20 colors you used. Click any swatch to reload that color instantly.\n\nThe palette is per-project by default (each paint file has its own recent colors history). `Ctrl+.` and `Ctrl+,` cycle forward and back through recent colors.\n\n**Pin a color** by right-clicking the swatch \u2192 **Pin to Palette**. Pinned colors move to the left and never get pushed off by new colors. Useful for team palette (\"these four colors are our team brand; always keep them\").","x":1},{"t":"Tutorial 9 \u2014 Advanced Tools > Brush Presets","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) If you customize brush size, hardness, flow, spacing, and stabilizer for a specific look, save it as a preset.\n\n- `Brush \u2192 Save Current as Preset`\n- Name it (\"Soft Detail,\" \"Hard Line,\" \"Grain Spray\")\n- Optionally assign a keyboard shortcut (`Brush \u2192 Assign Shortcut`)\n\nPresets appear in the **Brush Presets** dropdown in the toolbar. Pick one to load all its settings at once.\n\nBundled presets worth trying:\n\n- **Hard Round** \u2014 100% hardness, 100% flow. Classic pixel brush.\n- **Soft Airbrush** \u2014 0% hardness, 30% flow. Cloud / fade work.\n- **Pencil 1px** \u2014 tiny hard brush for pixel art cleanup.\n- **Grain Spray** \u2014 textured brush for noise / dust effects.","x":1},{"t":"Tutorial 9 \u2014 Advanced Tools > Smudge Tool","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) `R` (or `Shift+S` on some configs). The smudge tool pushes color around as if you were dragging wet paint. Great for:\n\n- Softening a hard edge\n- Blending two colors into a gradient\n- Creating \"streaking\" feel (rain, blur, motion)\n\nParameters:\n\n- **Strength:** How much color is carried per stroke (30-50% for gentle, 80%+ for aggressive drag)\n- **Sample All Layers:** On = pick up color from all visible layers; off = only from the active layer\n\nLight smudging on the boundary of two zones (with a zone merged and flattened first) hides the hard transition beautifully.","x":1},{"t":"Tutorial 9 \u2014 Advanced Tools > Clone Stamp","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) `S`. Sample pixels from one part of the canvas and paint them at another.\n\nWorkflow:\n\n1. Hold `Alt` and click a source point (where you want to copy from).\n2. Release `Alt`. Move to the destination.\n3. Paint. Pixels from the source are painted under the cursor.\n\nUseful for:\n\n- Extending a pattern across a surface (clone a stripe to make it longer)\n- Covering up a spec speckle by cloning a clean area over it\n- Duplicating a sponsor logo without re-importing\n\n**Aligned mode** (checkbox in tool options): the sample point follows the cursor offset. **Unaligned**: the sample point resets to the original every stroke.","x":1},{"t":"Tutorial 9 \u2014 Advanced Tools > Dodge & Burn","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) `O` for dodge (lighten), `Shift+O` for burn (darken). Classic darkroom tools for subtle tonal adjustment.\n\n- **Dodge** brightens the area under the brush.\n- **Burn** darkens it.\n\nBoth have a **Range** setting: **Shadows, Midtones, or Highlights**. Only pixels in the chosen tonal range respond to the stroke. This lets you brighten highlights without blowing out midtones, or deepen shadows without crushing midtones.\n\n**Exposure** (0-100%) controls strength per stroke. Keep it low (10-20%) for subtle work; multiple light strokes build up more natural than one heavy stroke.\n\nUse cases:\n\n- **Dodge highlights on a metallic zone** to simulate where light catches the flake.\n- **Burn shadows under a drop shadow** for extra depth.\n- **Dodge the center of a logo** to make it feel lit from within.\n\n---","x":1},{"t":"Tutorial 10 \u2014 Render & Export > Live Preview vs. full Render","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) SPB has two rendering modes:\n\n- **Live Preview** \u2014 continuous, automatic, lower-quality. Updates as you work so you always see approximately what the final looks like.\n- **Full Render** \u2014 on-demand, high-quality, writes TGAs to disk. This is what you send to iRacing.\n\nLive Preview runs in a background thread. It's fast, lightweight, and uses GPU acceleration where available. Any time you change a zone, swap a finish, adjust a layer \u2014 Live Preview re-composites within ~500ms.\n\nFull Render is slower (1-3 seconds on a modern machine) because it runs the full paint engine at 2048x2048 with all the extra polish \u2014 anti-aliasing, high-precision spec map computation, final clearcoat pass. This is what you commit to disk.\n\nThe rule: **iterate with Live Preview. Commit with Full Render.**","x":1},{"t":"Tutorial 10 \u2014 Render & Export > The F5 key","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Press `F5` any time the Live Preview looks stale or wrong. It flushes the cache and forces a full Live Preview rebuild.\n\nMoments when you'll want F5:\n\n- After changing a layer's visibility and the preview doesn't update\n- After reloading a modified external PNG that's used as a pattern\n- After changing graphics settings and wanting a fresh comparison\n- Whenever the preview \"feels\" stuck\n\nNinety percent of \"my preview is stuck\" support questions resolve with one F5 press.","x":1},{"t":"Tutorial 10 \u2014 Render & Export > Hit RENDER","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) In the top header, the big gold **RENDER** button. Click it.\n\nThree things happen in sequence:\n\n1. **Color pass:** SPB composites the final color TGA at full resolution.\n2. **Spec pass:** SPB generates the matching spec map TGA.\n3. **Deploy:** if **iRacing Car Folder** (top bar) is set, both files are copied into it: `car_num_<ID>.tga` (Custom Number) or `car_<ID>.tga` (Sim-Stamped Number), and `car_spec_<ID>.tga`. With no car folder nothing reaches iRacing (a banner says so). Shokker keeps the two newest renders in its own render folder.\n\nA green banner under the render tells you where the files went; a red one tells you what failed.","x":1},{"t":"Tutorial 10 \u2014 Render & Export > Render History","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Every render is logged in the **Render History** panel (`View \u2192 Render History` or `Ctrl+H`).\n\nEach entry shows:\n\n- Timestamp\n- Thumbnail of the render\n- File paths (color and spec)\n- Zone snapshot (which zones were active, which finishes applied)\n\nFrom any history entry you can:\n\n- **Re-open** \u2014 load that render state back into the project (great for \"wait, I liked it better three changes ago\")\n- **Copy paths** \u2014 grab file paths for sharing or backup\n- **Delete** \u2014 prune old renders you don't want cluttering the list\n\nHistory is stored in `Documents\\Shokker Paint Booth\\render_history\\` as a JSON log plus the actual TGA files. You can clean it out manually \u2014 older renders eat disk.","x":1},{"t":"Tutorial 10 \u2014 Render & Export > Getting the files into iRacing","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) The top bar holds everything iRacing needs:\n\n- **iRacing User ID:** your iRacing **Customer ID** (4\u20137 digits; helmet icon in iRacing \u2192 Profile). It is part of every file name; it is not your car number.\n- **Custom Number / Sim-Stamped Number:** Custom Number writes `car_num_<ID>.tga` (your paint carries its own number; iRacing loads it only with **Settings \u2192 Graphics \u2192 Hide Car Numbers ON**). Sim-Stamped Number writes `car_<ID>.tga` (iRacing stamps your number on; Hide Car Numbers OFF). They must agree. If you are unsure, render once in each mode: both files stay in the folder.\n- **iRacing Car Folder:** the car's folder, for example `Documents\\iRacing\\paint\\stockcars chevyss\\` (the \u25be menu lists the folders iRacing created; run a car once in iRacing to create its folder).\n\nWith the car folder set, every RENDER copies the paint and spec files into it. **Auto-deploy after render** (Settings gear) only matters when the car folder is empty. Then in iRacing press **Alt+Tab \u2192 Ctrl+R** (Reload Car Textures).\n\nSomething not showing? Say **it does not show up in iRacing** in the chat and the built-in helper checks your settings and your folder.","x":1},{"t":"Tutorial 10 \u2014 Render & Export > Export config (.shokker file)","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Project saves (`.spb`) are self-contained but tied to a specific template. To share a **complete painting project** with a friend \u2014 including custom patterns, imported logos, reference images \u2014 use the `.shokker` export.\n\n`File \u2192 Export \u2192 Shokker Package` (or `Ctrl+Shift+E`).\n\nPick an output filename. SPB bundles:\n\n- The `.spb` project file\n- All imported layers (logos, patterns)\n- Render history (optional, toggle off for smaller file)\n- Any custom finishes or presets you've created\n- A README with project metadata\n\nThe result is a single `.shokker` file that your friend can open on their machine (`File \u2192 Open` reads `.shokker` directly) and see your entire project, exactly as you built it. It's the canonical way to share, back up, or submit to a team archive.","x":1},{"t":"Tutorial 10 \u2014 Render & Export > Sharing renders publicly","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) Just want to show off the finished paint on Discord or Twitter? Two fast paths.\n\n**From the Render History:**\n1. Right-click an entry.\n2. **Copy as PNG** \u2014 puts a PNG of the render on your clipboard.\n3. Paste into Discord / X / wherever.\n\n**From the canvas:**\n1. `File \u2192 Export \u2192 PNG Snapshot` (or `Ctrl+Shift+P`).\n2. Pick resolution (1080, 1440, or 4K).\n3. Save or copy to clipboard.\n\nPNG exports are for social media only \u2014 they don't carry the spec map, so they can't be used in iRacing. Use TGA export for the sim.","x":1},{"t":"Tutorial 10 \u2014 Render & Export > Verify in iRacing","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) The loop closes in-sim.\n\n1. Fire up iRacing.\n2. Load the relevant car (Silverado if you followed along).\n3. Go to Paint screen.\n4. Reload. Your custom paint appears.\n\nDrive a lap. The paint responds to track lighting, direction of motion, and camera angle. This is where your spec map decisions (Tutorial 5) shine or fall flat. If something looks off in-sim, check the Channel Inspector back in SPB, adjust, re-render, reload iRacing.\n\nThe fast iteration loop: **SPB change \u2192 RENDER \u2192 iRacing reload**. Less than 10 seconds, ideally. Budget to do it dozens of times per livery.\n\n---","x":1},{"t":"Tutorial 10 \u2014 Render & Export > What's next?","k":"tutorial","b":"(Tutorial text: menu paths such as File / View / Layer -> ... come from an older layout and may not exist; name buttons only as in the WHERE THINGS ARE card.) You've finished the tutorial series. You can build zones, manage layers, stack finishes, author spec maps, place sponsors, apply effects, work with recipes, use the advanced toolbox, and ship renders to iRacing.\n\nNow the fun part: **make something good.** Browse the `#livery-showcase` channel on Discord for inspiration. Import a recipe you like and remix it. Build your own team's brand.\n\nWhen you hit walls, the reference docs in the `/` root folder cover every feature in depth:\n\n- `SPB_GUIDE.md` \u2014 the full user guide\n- `SPB_FEATURES.md` \u2014 feature catalog with use cases\n- `SPB_SPEC_MAP_GUIDE.md` \u2014 the spec map bible\n- `SPB_TIPS_AND_TRICKS.md` \u2014 workflow speed-ups\n- `SPB_TROUBLESHOOTING.md` \u2014 when things break\n- `SPB_FAQ.md` \u2014 the 40 most common questions\n\nAnd if you build a workflow worth teaching, come back and write Tutorial 11. We'd love the contribution. See README.md for submission guidelines.\n\nHappy painting.","x":1}];
    var STOP = {a:1,an:1,the:1,and:1,or:1,of:1,to:1,in:1,on:1,is:1,it:1,for:1,with:1,i:1,my:1,me:1,do:1,how:1,can:1,what:1,you:1,this:1,that:1,be:1,are:1,so:1,at:1,as:1,make:1,want:1,would:1,like:1,some:1,type:1};
    var SYN = {shiny:'gloss',glossy:'gloss',mirror:'chrome',reflective:'chrome',holo:'holographic',rainbow:'holographic',iridescent:'holographic',prismatic:'holographic',sparkle:'flake',glitter:'flake',metallic:'metal',fade:'gradient',blend:'gradient',transition:'gradient',stripe:'accent',stripes:'accent',trim:'accent',deploy:'export',folder:'export',undo:'undo',wrong:'flat',broken:'flat',hidden:'priority',covered:'priority',order:'priority'};
    function stem(w) { return w.length > 4 ? w.replace(/(ing|ed|es|s)$/, '') : w.replace(/s$/, ''); }
    function toks(s) {
        var out = [], w = String(s || '').toLowerCase().split(/[^a-z0-9]+/);
        for (var i = 0; i < w.length; i++) { if (w[i].length < 2 || STOP[w[i]]) continue; out.push(stem(SYN[w[i]] || w[i])); }
        return out;
    }
    var PREP = CHUNKS.map(function (c) { return { c: c, tt: toks(c.t), bt: toks(c.b) }; });
    // search(query, maxChars): best chunks first, cards ranked above tutorials on ties; returns [{title, text}]
    function search(q, maxChars) {
        var qt = toks(q); if (!qt.length) return [];
        var scored = [];
        PREP.forEach(function (p) {
            var s = 0;
            qt.forEach(function (t) {
                if (p.tt.indexOf(t) !== -1) s += 5;
                var n = 0; for (var i = 0; i < p.bt.length; i++) if (p.bt[i] === t) n++;
                s += Math.min(n, 4);
            });
            if (s > 0) scored.push({ s: s + (p.c.k === 'card' ? 3 : 0) - (p.c.x ? 6 : 0), c: p.c });
        });
        scored.sort(function (a, b) { return b.s - a.s; });
        var out = [], used = 0, limit = maxChars || 3000;
        for (var i = 0; i < scored.length && out.length < 4; i++) {
            var c = scored[i].c;
            if (out.length && used + c.b.length > limit) continue;
            out.push({ title: c.t, text: c.b }); used += c.b.length;
        }
        return out;
    }
    // searchScored(q, maxChars): same ranking as search(), but every hit carries its score and how many DISTINCT query words it matched (2026-10-02: the support helper only answers when the match is real)
    function searchScored(q, maxChars) {
        var qt = toks(q); if (!qt.length) return { nq: 0, hits: [] };
        var uq = qt.filter(function (t, i) { return qt.indexOf(t) === i; }), scored = [];
        PREP.forEach(function (p) {
            var s = 0, m = 0;
            uq.forEach(function (t) {
                var inT = p.tt.indexOf(t) !== -1, n = 0; if (inT) s += 5;
                for (var i = 0; i < p.bt.length; i++) if (p.bt[i] === t) n++;
                s += Math.min(n, 4); if (inT || n) m++;
            });
            if (s > 0) scored.push({ s: s + (p.c.k === 'card' ? 3 : 0) - (p.c.x ? 6 : 0), m: m, c: p.c });
        });
        scored.sort(function (a, b) { return b.s - a.s; });
        var out = [], used = 0, limit = maxChars || 3000;
        for (var i = 0; i < scored.length && out.length < 4; i++) {
            var c = scored[i].c;
            if (out.length && used + c.b.length > limit) continue;
            out.push({ title: c.t, text: c.b, score: scored[i].s, matched: scored[i].m }); used += c.b.length;
        }
        return { nq: uq.length, hits: out };
    }
    window.SpbAIKnowledge = { search: search, searchScored: searchScored, count: CHUNKS.length, titles: function () { return CHUNKS.map(function (c) { return c.t; }); } };
})();
